  ui_story_5053_50530001_102_dialog_content = "是鐘聲……？我想起來了！",
  ui_story_5053_50530001_103_dialog_content = "剛才有隻怪物忽然竄出來，然後我們就一直戰鬥到一天即將結束的時候……",
