  ui_story_5053_50530001_125_dialog_content = "PlayerName！！！",
  ui_story_5053_50530001_126_dialog_content = "抓住了！我抓住凱萊布了！",
  ui_story_5053_50530001_127_dialog_content = "……PlayerName？",
  ui_story_5053_50530101_1_dialog_content = "<color=#e8d9bb>啾啾、啾啾啾！</color>",
  ui_story_5053_50530101_2_dialog_content = "（嗯……是小鳥的叫聲嗎？）",
  ui_story_5053_50530101_3_dialog_content = "（空之山谷的小鳥總愛來叫我起床，真是想賴個床都不行啊。）",
  ui_story_5053_50530101_4_dialog_content = "（可是……）",
  ui_story_5053_50530101_5_dialog_content = "（我為什麼睡在草地上啊？！）",
  ui_story_5053_50530101_6_dialog_content = "（不、不對，這裡不是空之山谷……這裡是白夜城？！）",
  ui_story_5053_50530101_7_dialog_content = "（對啊，我是在白夜城！當時我和蜜雅進入了「永憶鏡晶」的世界，然後……）",
  ui_story_5053_50530101_8_dialog_content = "（我們在最後關頭從那裡逃出來了！）",
