  ui_story_5053_50530101_13_dialog_content = "加晴、凱萊布，大家——",
  ui_story_5053_50530101_14_dialog_content = "<size=30>小聲點。</size>",
  ui_story_5053_50530101_15_dialog_content = "<size=30>城主殿下？！</size>",
  ui_story_5053_50530101_16_dialog_content = "<size=30>您為什麼要這樣低聲說話？</size>",
  ui_story_5053_50530101_17_dialog_content = "<size=30>看那邊。</size>",
  ui_story_5053_50530101_18_dialog_content = "城主殿下，一切準備就緒。遊行的馬車已經停在門外，隨時可以出發。",
  ui_story_5053_50530101_19_dialog_content = "嗯，我知道了。卡蓮，妳先上車吧。",
  ui_story_5053_50530101_20_dialog_content = "卡蓮……卡蓮想留下來陪母親大人！",
  ui_story_5053_50530101_21_dialog_content = "白夜城所有的人都在等我們，卡蓮。你應該懂得自己身上的使命和責任。",
  ui_story_5053_50530101_22_dialog_content = "……是，卡蓮知道了。",
  ui_story_5053_50530101_23_dialog_content = "卡蓮會乖乖在馬車上等父親大人。",
  ui_story_5053_50530101_24_dialog_content = "卡蓮公主年紀雖小，卻能夠如此顧全大局，這是我們所有白夜城城民的福氣。",
  ui_story_5053_50530101_25_dialog_content = "……",
  ui_story_5053_50530101_26_dialog_content = "殿下，您還在擔心城主夫人嗎？",
  ui_story_5053_50530101_27_dialog_content = "約書亞一向健康，很少會說自己身體不適，尤其是在今天這樣的日子。",
  ui_story_5053_50530101_28_dialog_content = "夫人近來為了向各位貴族夫人宣傳城主的政策，的確費了不少精力。",
  ui_story_5053_50530101_29_dialog_content = "……罷了。",
  ui_story_5053_50530101_30_dialog_content = "紅女士，妳留下來照顧夫人，有什麼情況立刻向我報告。",
  ui_story_5053_50530101_31_dialog_content = "是，殿下。",
  ui_story_5053_50530101_32_dialog_content = "那是年輕的城主大人？怎麼會這樣？！也就是說……",
  ui_story_5053_50530101_33_dialog_content = "我們還是沒能離開。",
  ui_story_5053_50530101_34_dialog_content = "父親……",
  ui_story_5053_50530101_35_dialog_content = "……父親？還有……PlayerName。",
  ui_story_5053_50530101_36_dialog_content = "我們現在是、是已經回到現實世界了嗎？",
  ui_story_5053_50530101_37_dialog_content = "這裡不是現實世界。",
  ui_story_5053_50530101_38_dialog_content = "咦？不是現實世界？如果無法在一天結束之前走出去的話……",
  ui_story_5053_50530101_39_dialog_content = "我們現在，是不是永遠困在「永憶鏡晶」裡面了？",
  ui_story_5053_50530101_40_dialog_content = "我也不清楚，只能問問加晴了。",
  ui_story_5053_50530101_41_dialog_content = "呼......呼......呼......",
  ui_story_5053_50530101_42_dialog_content = "加晴！",
  ui_story_5053_50530101_43_dialog_content = "幽呼……這樣好癢唷。我還想再多睡點……",
  ui_story_5053_50530101_44_dialog_content = "加晴，我是PlayerName！事態緊急，快醒醒！",
  ui_story_5053_50530101_45_dialog_content = "嗯？什麼啊，是PlayerName呀？呼啊——",
  ui_story_5053_50530101_46_dialog_content = "咦？這裡是……",
  ui_story_5053_50530101_47_dialog_content = "噓——！",
  ui_story_5053_50530101_48_dialog_content = "你有沒有聽見什麼聲音？",
  ui_story_5053_50530101_49_dialog_content = "嗯，好像有聲音從那邊的灌木叢裡傳出來。",
  ui_story_5053_50530101_50_dialog_content = "走，去看看。",
  ui_story_5053_50530101_51_dialog_content = "咕……？",
  ui_story_5053_50530101_52_dialog_content = "什麼啊，原來是兔子！",
  ui_story_5053_50530101_53_dialog_content = "<size=50>咕——嘰嘰！</size>",
  ui_story_5053_50530101_54_dialog_content = "嚇死我了，原來兔子也會叫啊？",
  ui_story_5053_50530101_55_dialog_content = "算了，一隻兔子而已，也沒什麼威脅，我們再去前面巡邏一圈吧。",
  ui_story_5053_50530101_56_dialog_content = "好險……",
  ui_story_5053_50530101_57_dialog_content = "幸好我急中生智，把凱萊布變成一隻兔子，成功轉移了他們的注意力！",
  ui_story_5053_50530101_58_dialog_content = "嘰嘰嘰嘰！",
  ui_story_5053_50530101_59_dialog_content = "可是不對啊？我們為什麼要躲起來？",
  ui_story_5053_50530101_60_dialog_content = "加晴，我們還在「永憶鏡晶」的世界裡。",
