  ui_story_5053_50530101_62_dialog_content = "我回憶一下……",
  ui_story_5053_50530101_63_dialog_content = "當時十二點的鐘聲已經敲響，我們已經來到了一天的盡頭。",
  ui_story_5053_50530101_64_dialog_content = "要想出去，必須同時發動<color=#FFB400>時光回溯</color>和<color=#FFB400>離開「永憶鏡晶」</color>的咒語。",
  ui_story_5053_50530101_65_dialog_content = "剛剛我們看到紅女士送走了小舒瓦茲和小卡蓮，也就是說……",
  ui_story_5053_50530101_66_dialog_content = "離開「永憶鏡晶」的咒語<color=#FFB400>沒生效</color>，但時光回溯的咒語<color=#FFB400>生效了</color>？",
  ui_story_5053_50530101_67_dialog_content = "會不會是受到那隻怪物的影響……？",
  ui_story_5053_50530101_68_dialog_content = "啊，我記得那隻怪物！現在想想還是會覺得那怪物好嚇人啊！",
  ui_story_5053_50530101_69_dialog_content = "牠頭上長著好多翅膀，密密麻麻的非常恐怖。",
  ui_story_5053_50530101_70_dialog_content = "就好像是……",
  ui_story_5053_50530101_71_dialog_content = "就好像是，一隻帶來絕望的黑色天使。",
  ui_story_5053_50530101_72_dialog_content = "對！一隻<color=#FFB400>「黑天使」</color>！",
  ui_story_5053_50530101_73_dialog_content = "哎，不管這麼多了，我馬上發動離開的咒語帶大家出去！",
  ui_story_5053_50530101_74_dialog_content = "那個……",
  ui_story_5053_50530101_75_dialog_content = "嘰嘰嘰嘰嘰！",
  ui_story_5053_50530101_76_dialog_content = "還是先把凱萊布舅父變回來吧？",
  ui_story_5053_50530101_77_dialog_content = "啊～差點把這件事給忘了！",
  ui_story_5053_50530101_78_dialog_content = "繆塔提歐～繆塔提歐～繆塔提歐！",
  ui_story_5053_50530101_79_dialog_content = "請讓凱萊布恢復原貌吧！",
  ui_story_5053_50530101_80_dialog_content = "阿布拉卡達布拉！",
  ui_story_5053_50530101_81_dialog_content = "<color=#e8d9bb>砰！</color>",
  ui_story_5053_50530101_82_dialog_content = "……",
  ui_story_5053_50530101_83_dialog_content = "「永憶鏡晶」的縫隙裡……是巨人國……",
  ui_story_5053_50530101_84_dialog_content = "巨人國，消失了？",
  ui_story_5053_50530101_85_dialog_content = "凱萊布，歡迎回來！",
  ui_story_5053_50530101_86_dialog_content = "回來……？",
  ui_story_5053_50530101_87_dialog_content = "我回來了？！但我還沒拿到姐姐的……可惡！",
  ui_story_5053_50530101_88_dialog_content = "嗯？你這是什麼意思？",
  ui_story_5053_50530101_89_dialog_content = "……凱萊布，我從一開始就覺得你好奇怪啊。",
  ui_story_5053_50530101_90_dialog_content = "一下擅自離開，一下又跑去偷「永憶鏡晶」，你到底想幹什麼？",
  ui_story_5053_50530101_91_dialog_content = "<color=#e8d9bb>嗖——</color>",
  ui_story_5053_50530101_92_dialog_content = "什麼人？我們還是被衛兵發現了嗎？！",
  ui_story_5053_50530101_93_dialog_content = "加晴，拿起武器……",
  ui_story_5053_50530101_94_dialog_content = "「黑天使」又出現了！",
  ui_story_5053_50530101_95_dialog_content = "在……這……裡？",
  ui_story_5053_50530102_1_dialog_content = "在……這……裡？",
  ui_story_5053_50530102_2_dialog_content = "水晶球，釋放！",
  ui_story_5053_50530102_3_dialog_content = "「黑天使」怎麼又追過來了啊？我們不是重設時間了嗎！",
  ui_story_5053_50530102_4_dialog_content = "是、是姐姐的聲音……",
  ui_story_5053_50530102_5_dialog_content = "這……裡！",
  ui_story_5053_50530102_6_dialog_content = "白夜！庇護！",
  ui_story_5053_50530102_7_dialog_content = "凱萊布，戰場上不要胡思亂想！",
  ui_story_5053_50530102_8_dialog_content = "輪不到妳來教我！這到底是怎麼回事……",
  ui_story_5053_50530102_9_dialog_content = "闖入者，給我放下武器！",
  ui_story_5053_50530102_10_dialog_content = "竟敢在城主宅邸打群架，好大的膽子？！",
  ui_story_5053_50530102_11_dialog_content = "喝——啊！",
  ui_story_5053_50530102_12_dialog_content = "怪、怪物？！天啊！那是什麼！",
  ui_story_5053_50530102_13_dialog_content = "快去請求增援！",
  ui_story_5053_50530102_14_dialog_content = "好、好……",
  ui_story_5053_50530102_15_dialog_content = "舒……瓦茲……！",
  ui_story_5053_50530102_16_dialog_content = "……",
  ui_story_5053_50530102_17_dialog_content = "為什麼……為什麼「黑天使」總是追著父親一個人攻擊？",
  ui_story_5053_50530102_18_dialog_content = "而且「黑天使」一直在喊你們的名字，難道牠認識你們？",
  ui_story_5053_50530102_19_dialog_content = "可是我完全不認識牠呀……！",
  ui_story_5053_50530102_20_dialog_content = "呀啊——！",
  ui_story_5053_50530102_21_dialog_content = "主宰之刃！",
  ui_story_5053_50530102_22_dialog_content = "呃……",
  ui_story_5053_50530102_23_dialog_content = "你的力量比初次交手時遜色不少。",
  ui_story_5053_50530102_24_dialog_content = "哈——啊！！！",
  ui_story_5053_50530102_25_dialog_content = "……但仍然非常纏人。",
  ui_story_5053_50530102_26_dialog_content = "請讓我來指揮！雖然感應能力變弱了不少，但輔助戰鬥還是沒問題的！",
  ui_story_5053_50530102_27_dialog_content = "感謝你的好意，我已經有更好的人選了。",
  ui_story_5053_50530102_28_dialog_content = "蜜雅，妳知道該如何突破嗎？",
  ui_story_5053_50530102_29_dialog_content = "我、我？！讓我來指揮……？",
  ui_story_5053_50530102_30_dialog_content = "不要緊，把我當成妳手中的棋子。",
  ui_story_5053_50530102_31_dialog_content = "說吧，我該往哪裡走？",
  ui_story_5053_50530102_32_dialog_content = "也許……父親可以繼續吸引「黑天使」往前走……我從後方一同發起攻勢？",
  ui_story_5053_50530102_33_dialog_content = "不夠！",
  ui_story_5053_50530102_34_dialog_content = "那、那……",
  ui_story_5053_50530102_35_dialog_content = "妳手裡的棋子，可不只我一枚！",
  ui_story_5053_50530102_36_dialog_content = "對不起，我想不出來……",
  ui_story_5053_50530102_37_dialog_content = "蜜雅，別緊張，妳一定辦得到的！",
  ui_story_5053_50530102_38_dialog_content = "PlayerName……",
  ui_story_5053_50530102_39_dialog_content = "（這簡直就像是在騎士團裡進行訓練。父親，您是在引導我嗎？）",
  ui_story_5053_50530102_40_dialog_content = "（我不能讓他失望……不，我不能辜負騎士的榮譽！）",
  ui_story_5053_50530102_41_dialog_content = "……嗯，我知道了。",
  ui_story_5053_50530102_42_dialog_content = "趁著父親吸引「黑天使」的時候……加晴，麻煩妳從這一側追擊，舅父從另一側包抄。",
  ui_story_5053_50530102_43_dialog_content = "大家形成三角形的攻勢，一起圍攻「黑天使」……這樣應該沒問題吧？",
  ui_story_5053_50530102_44_dialog_content = "哇喔，好專業呀，遵命～！",
  ui_story_5053_50530102_45_dialog_content = "不壞的戰術，就這麼辦吧。",
  ui_story_5053_50530102_46_dialog_content = "在……這裡……",
  ui_story_5053_50530102_47_dialog_content = "妳究竟是什麼東西？為何要追殺我們？",
  ui_story_5053_50530102_48_dialog_content = "舒……瓦茲……！！！",
  ui_story_5053_50530102_49_dialog_content = "（「黑天使」的動作突然放緩了？但這是攻擊的最佳時機！）",
  ui_story_5053_50530102_50_dialog_content = "就是現在，大家一起！",
  ui_story_5053_50530102_51_dialog_content = "抱歉了……！",
  ui_story_5053_50530102_52_dialog_content = "水晶球，釋放！！",
  ui_story_5053_50530102_53_dialog_content = "這就是我的力量！",
  ui_story_5053_50530102_54_dialog_content = "啊——！",
  ui_story_5053_50530102_55_dialog_content = "全部命中！我們也太厲害了吧？",
  ui_story_5053_50530102_56_dialog_content = "痛……好痛……！！",
  ui_story_5053_50530102_57_dialog_content = "她看起來好痛苦……",
  ui_story_5053_50530102_58_dialog_content = "千萬別在這時候心軟呀！是「黑天使」一直無緣無故攻擊我們！",
  ui_story_5053_50530102_59_dialog_content = "對，戰場上不能留情……妳說得對。",
  ui_story_5053_50530102_60_dialog_content = "攻擊奏效了嗎……？",
  ui_story_5053_50530102_61_dialog_content = "啊啊……啊啊啊啊——！",
  ui_story_5053_50530102_62_dialog_content = "咦……好詭異的叫聲。",
  ui_story_5053_50530102_63_dialog_content = "糟糕！「黑天使」似乎在積蓄力量，馬上就要爆發了！",
  ui_story_5053_50530102_64_dialog_content = "怎、怎麼辦……！",
  ui_story_5053_50530102_65_dialog_content = "蜜雅，妳做得不錯。接下來交給我吧。",
  ui_story_5053_50530102_66_dialog_content = "父親……？",
  ui_story_5053_50530102_67_dialog_content = "所有人退下！",
  ui_story_5053_50530102_68_dialog_content = "舒……",
  ui_story_5053_50530102_69_dialog_content = "舒……瓦茲……！！！",
  ui_story_5053_50530102_70_dialog_content = "妳就如此想與我一個人交手嗎？",
  ui_story_5053_50530102_71_dialog_content = "如妳所願。",
  ui_story_5053_50530102_72_dialog_content = "接下，妳的墓誌銘——！",
  ui_story_5053_50530102_73_dialog_content = "<color=#e8d9bb>轟——！！</color>",
  ui_story_5053_50530102_74_dialog_content = "呃……呃……",
  ui_story_5053_50530102_75_dialog_content = "那個「黑天使」去哪裡了？",
  ui_story_5053_50530102_76_dialog_content = "好像是沿著外面的小路逃跑了。",
  ui_story_5053_50530102_77_dialog_content = "城主大人那一下，真的是天崩地裂！",
  ui_story_5053_50530102_78_dialog_content = "「黑天使」再厲害，也一定被傷得不輕，應該逃不了多遠吧？",
  ui_story_5053_50530102_79_dialog_content = "……",
  ui_story_5053_50530102_80_dialog_content = "舅父大人，您還是很在意那個「黑天使」嗎？",
  ui_story_5053_50530102_81_dialog_content = "畢竟牠的聲音……不，算了。姐姐怎麼可能變成怪物呢。",
  ui_story_5053_50530102_82_dialog_content = "加晴，趁現在，快唸咒語。",
  ui_story_5053_50530102_83_dialog_content = "咦……是喔！這個半路上闖出來的「黑天使」終於走了，我現在就帶大家出去！",
  ui_story_5053_50530102_84_dialog_content = "艾·普勒俄森斯～艾·普勒俄森斯～艾·普勒俄森斯～",
  ui_story_5053_50530102_85_dialog_content = "讓我們回到現實中去吧！",
  ui_story_5053_50530102_86_dialog_content = "阿布拉卡達布拉！",
  ui_story_5053_50530102_87_dialog_content = "<color=#e8d9bb>………………</color>",
  ui_story_5053_50530102_88_dialog_content = "好像沒有效呀……",
  ui_story_5053_50530102_89_dialog_content = "我再試一次！",
  ui_story_5053_50530102_90_dialog_content = "艾·普勒俄森斯～艾·普勒俄森斯～艾·普勒俄森斯！",
  ui_story_5053_50530102_91_dialog_content = "讓我們回到現實中去吧！阿布拉卡達布拉！",
  ui_story_5053_50530102_92_dialog_content = "加晴，妳確定妳有唸對咒語嗎？",
  ui_story_5053_50530102_93_dialog_content = "那是當然！大家手都牽好了嗎？我看看……都牽好了啊！",
  ui_story_5053_50530102_94_dialog_content = "我本來以為上次失敗是因為場面混亂，大家沒牽好手。",
  ui_story_5053_50530102_95_dialog_content = "可是怎麼牽好了還是不行啊？！",
  ui_story_5053_50530102_96_dialog_content = "加晴上次使用咒語的時候拿著這個世界的「永憶鏡晶」，妳是不是忘記這件事了？",
  ui_story_5053_50530102_97_dialog_content = "不，<color=#FFB400>只有回溯時間才需要這個世界的「永憶鏡晶」</color>——也就是媽媽設下的緊急避難裝置。",
  ui_story_5053_50530102_98_dialog_content = "離開這裡只算是正常程序，應該不需要它才對！",
  ui_story_5053_50530102_99_dialog_content = "還有沒有別的可能？",
  ui_story_5053_50530102_100_dialog_content = "除非是……我們的<color=#FFB400>人沒有到齊</color>。",
  ui_story_5053_50530102_101_dialog_content = "人沒有到齊？",
  ui_story_5053_50530102_102_dialog_content = "安全起見，進入「永憶鏡晶」需要由啟動者操作，而離開則需要內部的所有人到齊。",
  ui_story_5053_50530102_103_dialog_content = "雖然進來的時候我靠咒語意外打破了規矩……但出去的時候我就沒轍了！",
  ui_story_5053_50530102_104_dialog_content = "我們所有人都在這裡對吧？我沒眼花吧？",
  ui_story_5053_50530102_105_dialog_content = "難道除了我們幾個，還有別人也被牽連進來了？",
  ui_story_5053_50530102_106_dialog_content = "又或者……在大家進來之前，就已經有人透過某種方式進入「永憶鏡晶」了。",
  ui_story_5053_50530102_107_dialog_content = "不過啟動者早就離世了，應該不可能吧？",
  ui_story_5053_50530102_108_dialog_content = "……",
  ui_story_5053_50530102_109_dialog_content = "您、您竟然親自來了？！",
  ui_story_5053_50530102_110_dialog_content = "萬分抱歉，我們看守不力，打擾到您休息了。",
  ui_story_5053_50530102_111_dialog_content = "沒關係。告訴我，這裡發生什麼事了？",
  ui_story_5053_50530102_112_dialog_content = "好的。剛剛幾個身分不明的外來者忽然闖入花園，並與一隻怪物大打出手。",
  ui_story_5053_50530102_113_dialog_content = "其中一位闖入者無論面容、裝束，都和薇羅妮卡公主十分相似，但屬下不確定……",
  ui_story_5053_50530102_114_dialog_content = "薇羅妮卡？這樣啊，辛苦你們了。",
  ui_story_5053_50530201_1_dialog_content = "那個……你們真的不想嚐嚐這些點心嗎？不吃的話我要吃掉囉？",
  ui_story_5053_50530201_2_dialog_content = "虧妳還吃得下去……",
  ui_story_5053_50530201_3_dialog_content = "剛才我們在城主夫人的花園裡打打殺殺的，真不知道該怎麼跟她解釋。",
  ui_story_5053_50530201_4_dialog_content = "放輕鬆～放輕鬆～這種事急也沒用啊。",
  ui_story_5053_50530201_5_dialog_content = "哎，真羡慕妳，什麼時候都這麼悠哉。",
  ui_story_5053_50530201_6_dialog_content = "約書亞不是那種會嚴苛懲罰他人的人。",
  ui_story_5053_50530201_7_dialog_content = "既然她命人帶大家來到這裡，還送上點心，就表明她是想要以禮相待，不會刁難大家。",
  ui_story_5053_50530201_8_dialog_content = "哼，我們還是該慶幸啊。",
  ui_story_5053_50530201_9_dialog_content = "要是<color=#FFB400>另一個人</color>也在場，我們也許早就被關到白夜城的大牢裡了。",
  ui_story_5053_50530201_10_dialog_content = "另一個人？你說的是誰呀？",
  ui_story_5053_50530201_11_dialog_content = "……",
  ui_story_5053_50530201_12_dialog_content = "他說的另一個人，是過去的我。",
  ui_story_5053_50530201_13_dialog_content = "城主殿下，您原來還有自知之明啊。",
  ui_story_5053_50530201_14_dialog_content = "總、總之！這個世界的「約書亞」夫人出現了。",
  ui_story_5053_50530201_15_dialog_content = "這起碼證明，黑天使並不是這個世界的「約書亞」夫人。",
  ui_story_5053_50530201_16_dialog_content = "這些都不是現在值得擔心的事情。加晴，妳知道怎麼找出還有誰進入了「永憶鏡晶」嗎？",
  ui_story_5053_50530201_17_dialog_content = "辦法當然是有啦。",
  ui_story_5053_50530201_18_dialog_content = "只要有這個世界的「永憶鏡晶」就行了！",
  ui_story_5053_50530201_19_dialog_content = "除了能用它回朔時間，還可以用它<color=#FFB400>驗證誰是「永憶鏡晶」內的幻影，誰是真人</color>。",
  ui_story_5053_50530201_20_dialog_content = "雖然它還沒有方便到可以定位人就是了……",
  ui_story_5053_50530201_21_dialog_content = "不過這方法有個缺點，就是很花時間，需要一個人、一個人慢慢驗證。",
  ui_story_5053_50530201_22_dialog_content = "白夜城裡這麼多人，要花多少時間才驗證得完啊……",
  ui_story_5053_50530201_23_dialog_content = "沒關係～只要有緊急避難裝置，我們就可以一遍一遍倒轉時間！",
  ui_story_5053_50530201_24_dialog_content = "但是驅動它會消耗維持這個世界運轉的光能……也不能隨便亂來。",
  ui_story_5053_50530201_25_dialog_content = "那麼當務之急，就是把「永憶鏡晶」找來。「黑天使」的事情等出去再從長計議。",
  ui_story_5053_50530201_26_dialog_content = "你們找的是這個嗎？",
  ui_story_5053_50530201_27_dialog_content = "夫人手裡拿著的是……「永憶鏡晶」？！",
  ui_story_5053_50530201_28_dialog_content = "約書亞夫人，您是聽到我們的談話了嗎？您怎麼知道我們在找「永憶鏡晶」呀！",
  ui_story_5053_50530201_29_dialog_content = "呵呵，別急，親愛的孩子。妳先看看「永憶鏡晶」。",
  ui_story_5053_50530201_30_dialog_content = "這是……不不不不不會吧？！",
  ui_story_5053_50530201_31_dialog_content = "約書亞夫人……妳居然是<color=#FFB400>「真實存在的光靈」</color>！",
  ui_story_5053_50530201_32_dialog_content = "！！！",
  ui_story_5053_50530201_33_dialog_content = "姐姐……姐姐妳怎麼會……姐姐，真的是妳嗎？！",
  ui_story_5053_50530201_34_dialog_content = "不是我是誰啊，我親愛的小天才？",
  ui_story_5053_50530201_35_dialog_content = "………………",
  ui_story_5053_50530201_36_dialog_content = "加晴，妳確定嗎？",
  ui_story_5053_50530201_37_dialog_content = "錯不了！除非我眼睛出了問題！",
  ui_story_5053_50530201_38_dialog_content = "媽媽……這是真的嗎？",
  ui_story_5053_50530201_39_dialog_content = "當然是真的啦。",
  ui_story_5053_50530201_40_dialog_content = "你這副樣子和剛去騎士團報到的時候沒什麼變化，和我記憶中的一模一樣呢。",
  ui_story_5053_50530201_41_dialog_content = "嗚……那是、那是因為……",
  ui_story_5053_50530201_42_dialog_content = "是因為吞羅，那個女人改造了薇羅妮卡……蜜雅的身體，讓她的身體永遠停留在13歲。",
  ui_story_5053_50530201_43_dialog_content = "可是不對啊……姐姐，我親眼確認過妳……",
  ui_story_5053_50530201_44_dialog_content = "嗯？什麼意思？",
  ui_story_5053_50530201_45_dialog_content = "十二年前的「舒瓦茲家族日」，蜜雅……薇羅妮卡執行騎士團的任務時，被暗鬼植入了種子。",
  ui_story_5053_50530201_46_dialog_content = "因此被送到啟光實驗室進行「治療」。而那所謂的「治療」，根本就是暗鬼和叛徒設下的陷阱。",
  ui_story_5053_50530201_47_dialog_content = "約書亞為了救薇羅妮卡，孤身前去與敵人對峙。",
  ui_story_5053_50530201_48_dialog_content = "雖然最後成功救出了薇羅妮卡，但約書亞也因某種原因被植入了「種子」……",
  ui_story_5053_50530201_49_dialog_content = "最後，在病痛的折磨下……",
  ui_story_5053_50530201_50_dialog_content = "<color=#FFB400>她選擇了自殺</color>。",
  ui_story_5053_50530201_51_dialog_content = "但妳現在卻在「永憶鏡晶」之中，解釋一下吧。",
  ui_story_5053_50530201_52_dialog_content = "舒瓦茲，你就這麼對十二年未見的妻子說話嗎？！",
  ui_story_5053_50530201_53_dialog_content = "沒關係的，凱萊布。為了保護大家的安全，狄安理必須保持警惕，他沒做錯什麼。",
  ui_story_5053_50530201_54_dialog_content = "好吧……既然姐姐都這麼說了。",
  ui_story_5053_50530201_55_dialog_content = "那麼，我就接著狄安理說的故事說下去吧。",
  ui_story_5053_50530201_56_dialog_content = "沒錯，當時的我飽受病痛折磨……",
  ui_story_5053_50530201_57_dialog_content = "<color=#e8d9bb>若干年前·舒瓦茲宅邸</color>",
  ui_story_5053_50530201_58_dialog_content = "咳咳咳……狄安理，殺了我吧。",
  ui_story_5053_50530201_59_dialog_content = "不要這樣要求我，約書亞……",
  ui_story_5053_50530201_60_dialog_content = "越是抗拒「種子」的侵蝕，「種子」對我的折磨就越加劇。",
  ui_story_5053_50530201_61_dialog_content = "我可以清楚感覺到，「種子」想和我爭奪身體的控制權。",
  ui_story_5053_50530201_62_dialog_content = "……一定有辦法可以救妳的，相信我！",
  ui_story_5053_50530201_63_dialog_content = "你還記得若翰醫療隊嗎？對，可以請名醫若翰想想辦法。",
  ui_story_5053_50530201_64_dialog_content = "我馬上去派人尋找若翰的下落！",
  ui_story_5053_50530201_65_dialog_content = "好好休息，等我的好消息。",
  ui_story_5053_50530201_66_dialog_content = "沒用的，狄安理，沒用的……",
  ui_story_5053_50530201_67_dialog_content = "呃啊——",
  ui_story_5053_50530201_68_dialog_content = "別掙扎了，把身體乖乖交給我吧。",
  ui_story_5053_50530201_69_dialog_content = "休想！",
  ui_story_5053_50530201_70_dialog_content = "就算要用匕首刺進自己的心臟，我也不會把身體交給妳！",
  ui_story_5053_50530201_71_dialog_content = "妳……！把匕首給我拿開！",
  ui_story_5053_50530201_72_dialog_content = "不！",
  ui_story_5053_50530201_73_dialog_content = "給我拿開！！！",
  ui_story_5053_50530201_74_dialog_content = "呃嗚……",
  ui_story_5053_50530201_75_dialog_content = "<color=#e8d9bb>匡當！</color>",
  ui_story_5053_50530201_76_dialog_content = "「永憶鏡晶」……？",
  ui_story_5053_50530201_77_dialog_content = "妳想幹什麼？！不！！！",
  ui_story_5053_50530201_78_dialog_content = "讓我們走進，那段往日時光吧……",
  ui_story_5053_50530201_79_dialog_content = "<color=#e8d9bb>咚！</color>",
  ui_story_5053_50530201_80_dialog_content = "姐姐？妳沒事吧？剛才那聲巨響是怎麼了？",
  ui_story_5053_50530201_81_dialog_content = "怎麼沒有回應……別嚇我啊，那我進來了！",
  ui_story_5053_50530201_82_dialog_content = "姐、姐姐……？",
  ui_story_5053_50530201_83_dialog_content = "<size=50>姐姐！！</size>",
  ui_story_5053_50530201_84_dialog_content = "在種子的催化下，我的身體裡出現了<color=#FFB400>兩個人格</color>。",
  ui_story_5053_50530201_85_dialog_content = "一個是平日的我，但另一個卻如怪物般缺乏理性，極其瘋狂。",
  ui_story_5053_50530201_86_dialog_content = "隨著它不斷成長，它開始篡奪我的身體，傷害周遭的人。",
  ui_story_5053_50530201_87_dialog_content = "我絕不允許這樣的事發生，便開始與它爭鬥。",
  ui_story_5053_50530201_88_dialog_content = "兩個人格在一個軀體裡不斷拉扯，每天我的腦袋都如撕裂般疼痛。",
  ui_story_5053_50530201_89_dialog_content = "而那個怪物卻彷彿沒有感覺一般，絲毫不受影響，逐漸佔據了上風……",
  ui_story_5053_50530201_90_dialog_content = "我在這場爭鬥中越發衰弱，幾近崩潰。我知道，我就要輸了。",
  ui_story_5053_50530201_91_dialog_content = "所以我想出了一個雖然不算勝利，但卻能讓對方徹底失敗的辦法——",
  ui_story_5053_50530201_92_dialog_content = "<color=#FFB400>那就是將兩人一起關入「永憶鏡晶」中</color>。",
  ui_story_5053_50530201_93_dialog_content = "我抱著必死的信念，將自己與那個怪物送入了這個世界。",
  ui_story_5053_50530201_94_dialog_content = "我們兩位一體，只要我拒絕離開，牠就只能永遠陪我留在這裡。",
  ui_story_5053_50530201_95_dialog_content = "我們的戰鬥持續了很久、很久。",
  ui_story_5053_50530201_96_dialog_content = "夜半十二點的鐘聲敲響之後，打破規則的我們便一同化作這個世界的一部分。",
  ui_story_5053_50530201_97_dialog_content = "我們失去了記憶，合二為一，成為這個世界的「約書亞」，不斷重複著相同的一天又一天。",
  ui_story_5053_50530201_98_dialog_content = "直到你們來到這個世界。",
  ui_story_5053_50530201_99_dialog_content = "你們的到來喚醒了我們的記憶。",
  ui_story_5053_50530201_100_dialog_content = "甦醒後的怪物掙扎著與我分離開來。",
  ui_story_5053_50530201_101_dialog_content = "<color=#FFB400>她奪走我所有力量</color>逃之夭夭，再次企圖離開「永憶鏡晶」。",
  ui_story_5053_50530201_102_dialog_content = "雖然這樣的狀況令人絕望，但這一次……",
  ui_story_5053_50530201_103_dialog_content = "我不再是一個人了。",
  ui_story_5053_50530201_104_dialog_content = "……",
  ui_story_5053_50530201_105_dialog_content = "好、好離奇的故事……也就是說，襲擊我們的<color=#FFB400>「黑天使」是另一個約書亞夫人</color>囉？",
  ui_story_5053_50530201_106_dialog_content = "「黑天使」？你們居然還幫牠取了名字……嗯，可以這麼說。",
  ui_story_5053_50530201_107_dialog_content = "那段病床前的對話只有我和約書亞知道，其中的細節原委絲毫不差。",
  ui_story_5053_50530201_108_dialog_content = "約書亞，真的是妳……",
  ui_story_5053_50530201_109_dialog_content = "太好了，你終於肯相信我了。",
  ui_story_5053_50530201_110_dialog_content = "嗚……媽媽……真的是媽媽……",
  ui_story_5053_50530201_111_dialog_content = "瞧瞧你，小臉又哭花了。",
  ui_story_5053_50530201_112_dialog_content = "姐姐，沒想到妳居然在這裡，我找了那麼久……為什麼我一直沒發現呢……",
  ui_story_5053_50530201_113_dialog_content = "太好了，時隔十二年，我又可以跟妳說話了…………",
  ui_story_5053_50530201_114_dialog_content = "（「種子」、兩個人格……這些事情和蜜雅身上發生的非常相似。）",
  ui_story_5053_50530201_115_dialog_content = "（蜜雅的兩個人格是無話不談、互相扶持的朋友，但約書亞夫人的人格卻背道而馳，互相爭鬥。）",
  ui_story_5053_50530201_116_dialog_content = "（「種子」對不同個體的作用，居然有這麼大的差異。）",
  ui_story_5053_50530201_117_dialog_content = "話說回來，你們剛剛提到「十二年前」。",
  ui_story_5053_50530201_118_dialog_content = "難道我已經在這裡沉睡十二年了嗎？",
  ui_story_5053_50530201_119_dialog_content = "沒錯。",
  ui_story_5053_50530201_120_dialog_content = "怪不得你的樣子全變了，狄安理。",
  ui_story_5053_50530201_121_dialog_content = "要不是其他人叫出你的名字，我差點沒認出你來。",
  ui_story_5053_50530201_122_dialog_content = "你的眼睛、面龐為什麼成了這副模樣？",
  ui_story_5053_50530201_123_dialog_content = "這麼多年我經歷了太多的戰爭和局勢的動盪，早就不記得哪一道傷疤是什麼時候留下。",
  ui_story_5053_50530201_124_dialog_content = "但我始終記得妳離我而去的那天，還有妳胸口那把冰涼的匕首……",
  ui_story_5053_50530201_125_dialog_content = "狄安理……",
  ui_story_5053_50530201_126_dialog_content = "這麼說來，約書亞夫人的身體已經下葬了對吧……？",
  ui_story_5053_50530201_127_dialog_content = "那麼，她或是那個「黑天使」，還能離開「永憶鏡晶」嗎？",
  ui_story_5053_50530201_128_dialog_content = "可以。",
  ui_story_5053_50530201_129_dialog_content = "因為姐姐的身體<color=#FFB400>根本沒有下葬</color>。",
  ui_story_5053_50530201_130_dialog_content = "你這是什麼意思？",
  ui_story_5053_50530201_131_dialog_content = "哼……當時我發現姐姐的時候，她其實根本沒有死。",
  ui_story_5053_50530201_132_dialog_content = "我做了一些手腳，把她的身體偷偷帶回家治療了。",
  ui_story_5053_50530201_133_dialog_content = "什麼……但我聽說全城上下都見證了母親的葬禮，舅父你到底……",
  ui_story_5053_50530201_134_dialog_content = "約書亞的葬禮由我親自處理，全程不可能出任何紕漏。",
  ui_story_5053_50530201_135_dialog_content = "除非，你在她下葬後又掘開她的墓地。",
  ui_story_5053_50530201_136_dialog_content = "天啊……我的小天才，你快告訴我你到底做了什麼。",
  ui_story_5053_50530201_137_dialog_content = "既然姐姐問了……沒錯，我在事後掘開了姐姐的墳墓。",
  ui_story_5053_50530201_138_dialog_content = "為了避人耳目，我特地從遠處挖了一條地道通往墓穴，自然不會有人起疑。",
  ui_story_5053_50530201_139_dialog_content = "你親手挖的……？沒想到凱萊布外表文質彬彬，居然還會幹這種體力活啊！",
  ui_story_5053_50530201_140_dialog_content = "哼，為了姐姐這又算什麼。",
  ui_story_5053_50530201_141_dialog_content = "但是，舅父你是怎麼騙過入殮師和醫生的呢？難道你收買了他們嗎……？",
  ui_story_5053_50530201_142_dialog_content = "不，只是使用一些藥劑罷了。",
  ui_story_5053_50530201_143_dialog_content = "呵呵……當時我也很驚訝啊，你們高庭的醫生居然連這種「小聰明」都看不出來。",
  ui_story_5053_50530201_144_dialog_content = "也難怪治不好我的姐姐。",
  ui_story_5053_50530201_145_dialog_content = "凱萊布，你在黎明學院和老師吵架的時候，可從未如此謙虛過。",
  ui_story_5053_50530201_146_dialog_content = "身為「黎明學院不世出的天才」，我希望你能將智慧用在正確的地方。",
  ui_story_5053_50530201_147_dialog_content = "唉，凱萊布，你為什麼非要這樣一意孤行呢……",
  ui_story_5053_50530201_148_dialog_content = "因為姐姐一直不肯離開舒瓦茲跟孩子們身邊，他卻總是讓妳的生活越來越難過。",
  ui_story_5053_50530201_149_dialog_content = "我只是想保護妳。",
  ui_story_5053_50530201_150_dialog_content = "哎，對不起，都怪姐姐讓你操心了。",
  ui_story_5053_50530201_151_dialog_content = "就是因為你一直這麼寵著他，他才會一直改不掉這種頑童脾氣。",
  ui_story_5053_50530201_152_dialog_content = "凱萊布，這筆欺君之罪我們出去再算帳。",
  ui_story_5053_50530201_153_dialog_content = "……所以只要打敗「黑天使」就能順利離開，還能復活媽媽？",
  ui_story_5053_50530201_154_dialog_content = "從現在已知的情報來看，沒錯，就是這樣。",
  ui_story_5053_50530201_155_dialog_content = "那麼，約書亞的肉體現在狀況如何？可以承受突然的甦醒嗎？",
  ui_story_5053_50530201_156_dialog_content = "那當然是保存得完好無損。自從姐姐昏迷後，我就把所有的時間和精力都放在治療她身上。",
  ui_story_5053_50530201_157_dialog_content = "至於成果，<color=#FFB400>看看我就知道了</color>。",
  ui_story_5053_50530201_158_dialog_content = "看看你？看你什麼啊？",
  ui_story_5053_50530201_159_dialog_content = "……凱萊布，哪怕是為了約書亞，我也禁止你進行如此違背倫理的實驗。",
  ui_story_5053_50530201_160_dialog_content = "嘖，關你什麼事。",
  ui_story_5053_50530201_161_dialog_content = "等等，我頭暈了，到底什麼意思啊？？",
  ui_story_5053_50530201_162_dialog_content = "加晴，妳猜我今年幾歲？",
  ui_story_5053_50530201_163_dialog_content = "二十出頭？",
  ui_story_5053_50530201_164_dialog_content = "呵，就是這樣。",
  ui_story_5053_50530201_165_dialog_content = "那個，如果我沒記錯的話，舅父應該已經快四十歲了……",
  ui_story_5053_50530201_166_dialog_content = "哎——？！",
  ui_story_5053_50530201_167_dialog_content = "哎——？！",
  ui_story_5053_50530201_168_dialog_content = "我本來以為舅父只是天生麗質，或是很會打扮，沒想到居然是實驗的結果……",
  ui_story_5053_50530201_169_dialog_content = "我怎麼可能把未經實驗的藥劑用在姐姐身上。",
  ui_story_5053_50530201_170_dialog_content = "也不可能像那群貴族一樣恣意禍害他人，當然就只能用自己的身體試藥了。",
  ui_story_5053_50530201_171_dialog_content = "我的天啊……凱萊布你……",
  ui_story_5053_50530201_172_dialog_content = "媽、媽媽妳沒事吧？妳看起來臉色好差……",
  ui_story_5053_50530201_173_dialog_content = "沒事……媽媽已經習慣了，大概……",
  ui_story_5053_50530201_174_dialog_content = "<size=30>可是啊PlayerName，凱萊布的個性也很幼稚耶，難道他的研究還能讓人永保童心嗎？</size>",
  ui_story_5053_50530201_175_dialog_content = "加晴！我都聽到了！",
  ui_story_5053_50530201_176_dialog_content = "……雖然肉體沒有問題，但她體內的光能會經常暴走。",
  ui_story_5053_50530201_177_dialog_content = "我在這方面研究得還不夠透徹，一直找不到解決方法。",
  ui_story_5053_50530201_178_dialog_content = "光能？啊……你之前問我約書亞夫人的光能在哪裡，難道就是為了治療她？",
  ui_story_5053_50530201_179_dialog_content = "哼，沒錯。本來我只是想找到姐姐遺留的光能，用來做治療實驗。",
  ui_story_5053_50530201_180_dialog_content = "誰想得到姐姐本人一直就在「永憶鏡晶」裡面……而這才是她體內光能暴走的原因吧。",
  ui_story_5053_50530201_181_dialog_content = "我的假說完全錯了……",
  ui_story_5053_50530201_182_dialog_content = "凱萊布，你應該早點告訴我這些事情。",
  ui_story_5053_50530201_183_dialog_content = "告訴你？好讓你繼續折磨姐姐嗎？",
  ui_story_5053_50530201_184_dialog_content = "哎……怎麼說著說著又要吵起來啦？在大家面前不要吵架。",
  ui_story_5053_50530201_185_dialog_content = "抱歉，姐姐。",
  ui_story_5053_50530201_186_dialog_content = "既然約書亞的肉體狀況還不錯，我們就應該盡快帶她出去。",
  ui_story_5053_50530201_187_dialog_content = "回到正題，繼續討論對付「黑天使」的辦法吧。",
  ui_story_5053_50530201_188_dialog_content = "嗯，那我們繼續來聊聊我與「黑天使」的問題吧。",
  ui_story_5053_50530201_189_dialog_content = "對我來說，「黑天使」是無法戰勝的。",
  ui_story_5053_50530201_190_dialog_content = "因為我們屬於<color=#FFB400>同一個軀體，同生共死</color>。唯有第三者才能消滅牠。",
  ui_story_5053_50530201_191_dialog_content = "但你們要小心，「黑天使」也在狩獵你們。",
  ui_story_5053_50530201_192_dialog_content = "狩獵我們？",
  ui_story_5053_50530201_193_dialog_content = "是的。「黑天使」已經厭倦了與我之間的爭鬥。牠想擺脫我成為獨立的個體，獨佔那副軀體。",
  ui_story_5053_50530201_194_dialog_content = "在現實世界，這是很困難的事。",
  ui_story_5053_50530201_195_dialog_content = "但作為啟動者的一部分，在「永憶鏡晶」裡，牠可以<color=#FFB400>殺死其他活人來奪取光能，藉此變得完整</color>。",
  ui_story_5053_50530201_196_dialog_content = "加晴，這是真的嗎？",
  ui_story_5053_50530201_197_dialog_content = "嗯～雖然聽起來很玄，但這在「永憶鏡晶」裡確實有可能。",
  ui_story_5053_50530201_198_dialog_content = "「永憶鏡晶」表面只是個播放回憶的裝置，但其中的原理卻非常深奧。",
  ui_story_5053_50530201_199_dialog_content = "所以媽媽只在北境女王的吩咐下做了這麼一個，在那之後就將相關資料全部藏起來了……",
  ui_story_5053_50530201_200_dialog_content = "總結一下剛剛的情報。我們面臨的結局有兩種。",
  ui_story_5053_50530201_201_dialog_content = "一種是我們消滅「黑天使」，帶著約書亞夫人離開這裡。",
  ui_story_5053_50530201_202_dialog_content = "另一種是我們被「黑天使」殺死，放任她在現實世界復活？",
  ui_story_5053_50530201_203_dialog_content = "沒錯。聰明的孩子，你叫PlayerName對嗎？",
  ui_story_5053_50530201_204_dialog_content = "是的。說來您知道我和加晴的名字，還對「蜜雅」這個稱呼並不驚訝。",
  ui_story_5053_50530201_205_dialog_content = "難道您也有時間重設前的記憶嗎？",
  ui_story_5053_50530201_206_dialog_content = "嗯。因為時間回溯時，<color=#FFB400>我也與你們在一起啊</color>。",
  ui_story_5053_50530201_207_dialog_content = "而我……再也不想和家人分開了。",
  ui_story_5053_50530201_208_dialog_content = "我一定會消滅「黑天使」帶妳出去的，姐姐妳別難過。",
  ui_story_5053_50530201_209_dialog_content = "我也……！我也一定會救媽媽出去的！",
  ui_story_5053_50530201_210_dialog_content = "嗯，我相信你們。",
  ui_story_5053_50530201_211_dialog_content = "「黑天使」雖然是缺乏理性的怪物，但是牠非常狡猾。",
  ui_story_5053_50530201_212_dialog_content = "我們需要一個誘餌，引誘牠主動現身。",
  ui_story_5053_50530201_213_dialog_content = "狄安理，可以拜託你嗎？",
  ui_story_5053_50530201_214_dialog_content = "沒問題，如此重要又危險的角色，也最好由我來擔任。",
  ui_story_5053_50530201_215_dialog_content = "只是我該怎麼吸引牠呢？",
  ui_story_5053_50530201_216_dialog_content = "你什麼都不用做就好。畢竟那個怪物……<color=#FFB400>有點討厭你</color>。",
  ui_story_5053_50530201_217_dialog_content = "剛剛要不是你靠實力擊退牠，牠一定會當場把你撕碎。",
  ui_story_5053_50530201_218_dialog_content = "這一點也適用於這個世界中年輕的你，「黑天使」可能也會去慶典中襲擊他。",
  ui_story_5053_50530201_219_dialog_content = "哪怕殺死另一個你對牠沒有任何好處，牠還是會忍不住這麼做。",
  ui_story_5053_50530201_220_dialog_content = "……我明白了。既然如此，找到年輕的我，在他附近等待「黑天使」現身就可以了。",
  ui_story_5053_50530201_221_dialog_content = "等等，父親這會不會太危險了……萬一您受傷了該怎麼辦？",
  ui_story_5053_50530201_222_dialog_content = "小薇妳呀，還是這麼心疼家人。",
  ui_story_5053_50530201_223_dialog_content = "但是現在情況危及，我們應該以大局為重。",
  ui_story_5053_50530201_224_dialog_content = "相信妳父親，好嗎？",
  ui_story_5053_50530201_225_dialog_content = "嗯……",
  ui_story_5053_50530201_226_dialog_content = "花車遊行結束後，應該就是廣場上的開幕式了。",
  ui_story_5053_50530201_227_dialog_content = "我們去廣場附近埋伏？",
  ui_story_5053_50530201_228_dialog_content = "好主意。但是加晴，妳得跟我一起留下來。",
  ui_story_5053_50530201_229_dialog_content = "為什麼？別小看我啊，我比PlayerName能打多了！",
  ui_story_5053_50530201_230_dialog_content = "咳咳……",
  ui_story_5053_50530201_231_dialog_content = "嗯，我知道。但加晴妳是「永憶鏡晶」的操作者。",
  ui_story_5053_50530201_232_dialog_content = "其他人如果出了事，我們都可以透過回溯時間讓一切恢復原狀。",
  ui_story_5053_50530201_233_dialog_content = "但要是妳出了事，那可就真的無法挽回了……",
  ui_story_5053_50530201_234_dialog_content = "說、說得也對……",
  ui_story_5053_50530201_235_dialog_content = "那麼我、蜜雅、PlayerName，還有當誘餌的城主大人一起前往廣場，消滅「黑天使」。",
  ui_story_5053_50530201_236_dialog_content = "加晴和失去戰鬥能力的姐姐在這裡留守，等待我們的好消息。",
  ui_story_5053_50530201_237_dialog_content = "……加晴，妳一定要保護好我姐姐。",
  ui_story_5053_50530201_238_dialog_content = "知道啦知道啦！怎麼全都在懷疑我的實力啊……",
  ui_story_5053_50530201_239_dialog_content = "真難得啊，凱萊布。我還以為你一定會想留在姐姐身邊。",
  ui_story_5053_50530201_240_dialog_content = "眼下消滅「黑天使」幫助姐姐盡快離開這裡才最重要，你以為我連這都不懂嗎？",
  ui_story_5053_50530201_241_dialog_content = "那、那個，時間不多，我們趕緊出發吧。",
  ui_story_5053_50530201_242_dialog_content = "對！我們快走吧！",
  ui_story_5053_50530201_243_dialog_content = "你們兩個別推我！",
  ui_story_5053_50530201_244_dialog_content = "一路順風！注意安全喔～",
  ui_story_5053_50530201_245_dialog_content = "約書亞，這次我一定不會再失去妳了。我向妳保證。",
  ui_story_5053_50530201_246_dialog_content = "嗯，我相信你。",
  ui_story_5053_50530201_247_dialog_content = "沒問題的。",
  ui_story_5053_50530301_1_dialog_content = "遊行結束了，典禮馬上就要開始了。",
  ui_story_5053_50530301_2_dialog_content = "現在過去還能找到好位置觀禮嗎？",
  ui_story_5053_50530301_3_dialog_content = "快走，過去看看！",
  ui_story_5053_50530301_4_dialog_content = "不過是個形式上的典禮，有什麼好看的？",
  ui_story_5053_50530301_5_dialog_content = "到處都是人，視野這麼差，我們要怎麼監視「黑天使」啊！",
  ui_story_5053_50530301_6_dialog_content = "靠近看台，守株待兔。",
  ui_story_5053_50530301_7_dialog_content = "既然你和這個世界的你都能吸引「黑天使」，那你跟他一起站在看台上，效率不是比較高嗎？",
  ui_story_5053_50530301_8_dialog_content = "那個……還是我去看台上比較好，因為這個世界的人還認得我的模樣。",
  ui_story_5053_50530301_9_dialog_content = "如果父親去了，也許又要引發一些不必要的騷動……",
  ui_story_5053_50530301_10_dialog_content = "說得有理，但萬一「黑天使」真的去襲擊看台，蜜雅妳一個人能阻止牠嗎？",
  ui_story_5053_50530301_11_dialog_content = "我……我不是一個人。",
  ui_story_5053_50530301_12_dialog_content = "這個世界的「父親」也一定會保護我的。",
  ui_story_5053_50530301_13_dialog_content = "而且看台上的視野比較好，萬一我發現了「黑天使」的方位，就可以馬上告訴大家……",
  ui_story_5053_50530301_14_dialog_content = "唔……到時候，我會站在一個大家看得到的地方，向大家示意的！",
  ui_story_5053_50530301_15_dialog_content = "啊，對、對不起……父親，我的想法是不是太幼稚了？",
  ui_story_5053_50530301_16_dialog_content = "妳考慮得很周全，就照妳說的做吧。",
  ui_story_5053_50530301_17_dialog_content = "欸？真的嗎……",
  ui_story_5053_50530301_18_dialog_content = "謝謝父親，那、那我過去了，大家一定要等我的示意！",
  ui_story_5053_50530301_19_dialog_content = "才過了一天，蜜雅已經變得這麼勇敢又有主見了，真好啊。",
  ui_story_5053_50530301_20_dialog_content = "PlayerName，現在不是多愁善感的時候。睜大眼睛，不要放過那個毀了姐姐的惡魔！",
  ui_story_5053_50530301_21_dialog_content = "啊，我馬上就來！",
  ui_story_5053_50530301_22_dialog_content = "卡蓮，慶典就要開始了，快回到座位上來。",
  ui_story_5053_50530301_23_dialog_content = "好的，父親大人。",
  ui_story_5053_50530301_24_dialog_content = "……父親大人，卡蓮。",
  ui_story_5053_50530301_25_dialog_content = "姐姐？！是薇羅妮卡姐姐！",
  ui_story_5053_50530301_26_dialog_content = "薇羅妮卡？妳怎麼會在這裡？",
  ui_story_5053_50530301_27_dialog_content = "是、是媽媽要我回來參加家族日慶典的。",
  ui_story_5053_50530301_28_dialog_content = "妳回去看過妳母親了？",
  ui_story_5053_50530301_29_dialog_content = "嗯……她身體不適，但她說要我們不要擔心。",
  ui_story_5053_50530301_30_dialog_content = "這不是薇羅妮卡公主嗎？許久未見，公主別來無恙？",
  ui_story_5053_50530301_31_dialog_content = "不是說薇羅妮卡公主加入騎士隊，隨隊去影鎮了嗎？",
  ui_story_5053_50530301_32_dialog_content = "……我想回來參加典禮，所以申請了暫時離隊。",
  ui_story_5053_50530301_33_dialog_content = "原來如此，畢竟是「舒瓦茲」家族日，您應該參加。",
  ui_story_5053_50530301_34_dialog_content = "呵呵，可惜我的家人依舊在影鎮駐守，沒有這份福氣啊。",
  ui_story_5053_50530301_35_dialog_content = "薇羅妮卡姐姐是舒瓦茲家族的一員，她回來參加家族日慶典天經地義呀！",
  ui_story_5053_50530301_36_dialog_content = "卡蓮，退下。不得對赫密士公爵無禮。",
  ui_story_5053_50530301_37_dialog_content = "父親，這不怪卡蓮，只怪我出現得太過突然。",
  ui_story_5053_50530301_38_dialog_content = "但我也想問問赫密士公爵，夫人近來可好？",
  ui_story_5053_50530301_39_dialog_content = "我太太？她很好。",
  ui_story_5053_50530301_40_dialog_content = "我聽聞令孫在騎士隊請假的時候，總是說公爵夫人病危，所以有些擔心。",
  ui_story_5053_50530301_41_dialog_content = "既然沒事……我就放心了。",
  ui_story_5053_50530301_42_dialog_content = "……是，謝謝您的關心。",
  ui_story_5053_50530301_43_dialog_content = "赫密士公爵，有時間還是要多關心一下家人啊。",
  ui_story_5053_50530301_44_dialog_content = "薇羅妮卡公主這幾日變化不小，一定是在騎士團經受了許多歷練。",
  ui_story_5053_50530301_45_dialog_content = "或許吧，我只希望她不要因此自鳴得意。",
  ui_story_5053_50530301_46_dialog_content = "您瞧您說的，何必只對薇羅妮卡殿下這麼嚴格呢。",
  ui_story_5053_50530301_47_dialog_content = "謝謝您，特洛伊公爵。父親說得有理，我還應該繼續虛心學習。",
  ui_story_5053_50530301_48_dialog_content = "是嗎，薇羅妮卡公主……看來在騎士團的工作真的令您成長不少。",
  ui_story_5053_50530301_49_dialog_content = "典禮馬上就要開始，大家落座吧。",
  ui_story_5053_50530301_50_dialog_content = "姐姐，妳剛剛好帥啊！面對那些元老院的老頭，卻一點都不害怕！",
  ui_story_5053_50530301_51_dialog_content = "嘿嘿，是嗎？其實還是有點害怕啦……",
  ui_story_5053_50530301_52_dialog_content = "小卡蓮也很勇敢啊，居然敢一個人和父親參加遊行。",
  ui_story_5053_50530301_53_dialog_content = "不……卡蓮不想和母親大人分開……",
  ui_story_5053_50530301_54_dialog_content = "上車的時候，是父親大人說母親大人身體不舒服，要卡蓮獨自參加慶典……",
  ui_story_5053_50530301_55_dialog_content = "（原來如此，母親為了和我們見面，以身體不適為由支開了卡蓮和父親。）",
  ui_story_5053_50530301_56_dialog_content = "（雖然這讓小卡蓮傷透了心，但這裡的一切都不是真的。不重要。）",
  ui_story_5053_50530301_57_dialog_content = "（以大局為重，不要放在心上……不，我做不到。）",
  ui_story_5053_50530301_58_dialog_content = "小卡蓮，回去我們一起找媽媽玩好不好？",
  ui_story_5053_50530301_59_dialog_content = "可以嗎？不會打擾母親大人休息嗎？",
  ui_story_5053_50530301_60_dialog_content = "才不會呢，媽媽最喜歡小卡蓮了，看到妳她才會更有精神呀。",
  ui_story_5053_50530301_61_dialog_content = "卡蓮也最喜歡母親大人和姐姐了！也喜歡父親大人！",
  ui_story_5053_50530301_62_dialog_content = "回去之後，卡蓮要給切水果母親大人吃，跟她說遊行發生的事！",
  ui_story_5053_50530301_63_dialog_content = "嘿嘿，小卡蓮真乖。",
  ui_story_5053_50530301_64_dialog_content = "（太好啦，小卡蓮恢復精神了。）",
  ui_story_5053_50530301_65_dialog_content = "看到什麼了嗎？",
  ui_story_5053_50530301_66_dialog_content = "蜜雅已經上去了，但現在看不到她的身影……不過小舒瓦茲似乎準備致詞了。",
  ui_story_5053_50530301_67_dialog_content = "暫時還沒看到「黑天使」的影子。",
  ui_story_5053_50530301_68_dialog_content = "這個地方視野太差了，我們還是換個地方吧。",
  ui_story_5053_50530301_69_dialog_content = "<color=#e8d9bb>嗶嚓！嗶嚓！</color>",
  ui_story_5053_50530301_70_dialog_content = "這個動靜是……",
  ui_story_5053_50530301_71_dialog_content = "凱萊布，我想我們不用換地方了。",
  ui_story_5053_50530301_72_dialog_content = "你們兩個，快閃開！",
  ui_story_5053_50530301_73_dialog_content = "在……這裡！",
  ui_story_5053_50530302_1_dialog_content = "我宣布，「舒瓦茲家族日」慶典，正式開始！",
  ui_story_5053_50530302_2_dialog_content = "接下來舉行「決鬥之儀式」！",
  ui_story_5053_50530302_3_dialog_content = "（怎麼還沒有出現……）",
  ui_story_5053_50530302_4_dialog_content = "（他們原來應該是在那個方向，怎麼完全找不到他們的身影呢……）",
  ui_story_5053_50530302_5_dialog_content = "（難道……難道「黑天使」已經找上了PlayerName他們？）",
  ui_story_5053_50530302_6_dialog_content = "（怎麼辦？要找藉口到下面去嗎？）",
  ui_story_5053_50530302_7_dialog_content = "姐姐，妳在找什麼嗎？",
  ui_story_5053_50530302_8_dialog_content = "沒、沒有……卡蓮妳看，那邊的決鬥儀式已經開始了，感覺會很精彩呢。",
  ui_story_5053_50530302_9_dialog_content = "什麼時候才能讓卡蓮上台表演……明明卡蓮的劍術一點都不比他們差。",
  ui_story_5053_50530302_10_dialog_content = "嗯？好奇怪。正在決鬥的兩個衛兵為什麼停下來了？",
  ui_story_5053_50530302_11_dialog_content = "而且還朝著我們在的地方走過來了……",
  ui_story_5053_50530302_12_dialog_content = "是什麼額外的演出內容嗎？",
  ui_story_5053_50530302_13_dialog_content = "嗯？",
  ui_story_5053_50530302_14_dialog_content = "（父親一臉疑惑，似乎並不知情的樣子。）",
  ui_story_5053_50530302_15_dialog_content = "（當年我不在這裡，並不知道正常情況下會發生什麼事……但這顯然不對勁。）",
  ui_story_5053_50530302_16_dialog_content = "……",
  ui_story_5053_50530302_17_dialog_content = "（難道是……？！）",
  ui_story_5053_50530302_18_dialog_content = "……！父親！刺殺提前開始了！",
  ui_story_5053_50530302_19_dialog_content = "妳怎麼會知道刺殺的事情？而且還知道……提前了？",
  ui_story_5053_50530302_20_dialog_content = "這件事說來話長……",
  ui_story_5053_50530302_21_dialog_content = "你們走到看台上做什麼？！這是你們能來的地方嗎？",
  ui_story_5053_50530302_22_dialog_content = "……",
  ui_story_5053_50530302_23_dialog_content = "大膽！竟敢不回答公爵！",
  ui_story_5053_50530302_24_dialog_content = "來者不善……赫密士公爵，快退後！",
  ui_story_5053_50530302_25_dialog_content = "薇羅妮卡，保護好卡蓮！",
  ui_story_5053_50530302_26_dialog_content = "父親大人，小心！",
  ui_story_5053_50530302_27_dialog_content = "喝！",
  ui_story_5053_50530302_28_dialog_content = "就這麼點本事，還敢來我面前撒野？",
  ui_story_5053_50530302_29_dialog_content = "主宰一切！",
  ui_story_5053_50530302_30_dialog_content = "呃……",
  ui_story_5053_50530302_31_dialog_content = "怎麼，你也想過來試試嗎？",
  ui_story_5053_50530302_32_dialog_content = "喝！",
  ui_story_5053_50530302_33_dialog_content = "哈——！",
  ui_story_5053_50530302_34_dialog_content = "呃……",
  ui_story_5053_50530302_35_dialog_content = "居然能站著接住我的一劍？說，是誰派你來的！",
  ui_story_5053_50530302_36_dialog_content = "等……",
  ui_story_5053_50530302_37_dialog_content = "現在才求饒，太遲了！",
  ui_story_5053_50530302_38_dialog_content = "姐姐，父親大人為什麼在和壞蛋說悄悄話？",
  ui_story_5053_50530302_39_dialog_content = "不對……看那樣子，與其說父親在威脅他，不如說是他拉住了父親的武器……",
  ui_story_5053_50530302_40_dialog_content = "<color=#e8d9bb>喀嚓！</color>",
  ui_story_5053_50530302_41_dialog_content = "嗯？",
  ui_story_5053_50530302_42_dialog_content = "哈……哈哈！馬……上……",
  ui_story_5053_50530302_43_dialog_content = "他的臉，怎麼會這麼扭曲……",
  ui_story_5053_50530302_44_dialog_content = "為什麼他受傷了還在大笑？好奇怪……",
  ui_story_5053_50530302_45_dialog_content = "你這是……怎麼會有這麼大的力氣，<color=#FFB400>武器完全拔不出來</color>！",
  ui_story_5053_50530302_46_dialog_content = "既然如此，主宰……",
  ui_story_5053_50530302_47_dialog_content = "來……了……",
  ui_story_5053_50530302_48_dialog_content = "父親！快看天上！",
  ui_story_5053_50530302_49_dialog_content = "<size=45><color=#e8d9bb>吼——！</color></size>",
  ui_story_5053_50530302_50_dialog_content = "什麼？",
  ui_story_5053_50530302_51_dialog_content = "好、好大的風！卡蓮快要被風吹跑了！",
  ui_story_5053_50530302_52_dialog_content = "卡蓮，姐姐在這裡！",
  ui_story_5053_50530302_53_dialog_content = "龍……是<color=#FFB400>飛龍</color>？卡爾帝瑪……難道你們想連看台一起毀掉嗎？！",
  ui_story_5053_50530302_54_dialog_content = "<size=45><color=#e8d9bb>吼嗚——！</color></size>",
  ui_story_5053_50530302_55_dialog_content = "卡蓮、薇羅妮卡！",
  ui_story_5053_50530302_56_dialog_content = "跑！快跑啊！！！",
  ui_story_5053_50530302_57_dialog_content = "<size=45><color=#e8d9bb>轟——！！！</color></size>",
  ui_story_5053_50530401_1_dialog_content = "哈——！！",
  ui_story_5053_50530401_2_dialog_content = "哈，你也不過如此嘛！",
  ui_story_5053_50530401_3_dialog_content = "區區「種子」的產物，居然還敢模仿姐姐的聲音騙我……",
  ui_story_5053_50530401_4_dialog_content = "姐姐的痛苦，我要你血債血償！",
  ui_story_5053_50530401_5_dialog_content = "哈——啊！！！",
  ui_story_5053_50530401_6_dialog_content = "……",
  ui_story_5053_50530401_7_dialog_content = "凱萊布！不要冒進！",
  ui_story_5053_50530401_8_dialog_content = "受死吧！",
  ui_story_5053_50530401_9_dialog_content = "……哈！！",
  ui_story_5053_50530401_10_dialog_content = "什麼？！",
  ui_story_5053_50530401_11_dialog_content = "凱萊布！！！",
  ui_story_5053_50530401_12_dialog_content = "凱……萊……布……？",
  ui_story_5053_50530401_13_dialog_content = "不准用你的臭嘴喊我名字……",
  ui_story_5053_50530401_14_dialog_content = "就趁現在！",
  ui_story_5053_50530401_15_dialog_content = "我要、諸星都動搖——！！",
  ui_story_5053_50530401_16_dialog_content = "啊！！！",
  ui_story_5053_50530401_17_dialog_content = "舒……瓦茲……",
  ui_story_5053_50530401_18_dialog_content = "舒……",
  ui_story_5053_50530401_19_dialog_content = "周圍的街景又恢復如初了？",
  ui_story_5053_50530401_20_dialog_content = "消失了？牠這算是死了嗎……",
  ui_story_5053_50530401_21_dialog_content = "……情況不對，看那邊。",
  ui_story_5053_50530401_22_dialog_content = "呀啊——！",
  ui_story_5053_50530401_23_dialog_content = "快逃命啊！！！",
  ui_story_5053_50530401_24_dialog_content = "廣場上的群眾都在四處亂竄，難道是叛亂開始了？",
  ui_story_5053_50530401_25_dialog_content = "不對啊，沒有我們干涉的話，叛亂應該在刺殺之後才……",
  ui_story_5053_50530401_26_dialog_content = "不對……",
  ui_story_5053_50530401_27_dialog_content = "你們看天上！",
  ui_story_5053_50530401_28_dialog_content = "吼——！",
  ui_story_5053_50530401_29_dialog_content = "是卡爾帝瑪家族的那隻飛龍？！",
  ui_story_5053_50530401_30_dialog_content = "龍怎麼會出現在城裡？",
  ui_story_5053_50530401_31_dialog_content = "天啊？！怎麼會有那種東西進入白夜城……",
  ui_story_5053_50530401_32_dialog_content = "這種時候你們這些衛兵不是應該保護我們嗎？還愣著幹什麼！！",
  ui_story_5053_50530401_33_dialog_content = "……",
  ui_story_5053_50530401_34_dialog_content = "咦，你、你們要幹什麼？",
  ui_story_5053_50530401_35_dialog_content = "殺……殺……殺……",
  ui_story_5053_50530401_36_dialog_content = "喝啊——",
  ui_story_5053_50530401_37_dialog_content = "主宰之刃！",
  ui_story_5053_50530401_38_dialog_content = "戕害手無寸鐵的民眾，還算什麼騎士！卡爾帝瑪家族已經墮落到這種地步了嗎？！",
  ui_story_5053_50530401_39_dialog_content = "……呃…………",
  ui_story_5053_50530401_40_dialog_content = "這、這個人還活著！",
  ui_story_5053_50530401_41_dialog_content = "殺……",
  ui_story_5053_50530401_42_dialog_content = "殺……？妳說什麼？",
  ui_story_5053_50530401_43_dialog_content = "舒……瓦茲……",
  ui_story_5053_50530401_44_dialog_content = "殺……殺……殺死入侵者！",
  ui_story_5053_50530401_45_dialog_content = "PlayerName，快閃開！",
  ui_story_5053_50530401_46_dialog_content = "為什麼，她這是怎麼了……？",
  ui_story_5053_50530401_47_dialog_content = "<color=#e8d9bb><size=45>轟——！！！</size></color>",
  ui_story_5053_50530401_48_dialog_content = "好、好強的衝擊力，這又是怎麼回事？",
  ui_story_5053_50530401_49_dialog_content = "看台那邊爆炸了！",
  ui_story_5053_50530401_50_dialog_content = "城主遇襲！",
  ui_story_5053_50530401_51_dialog_content = "快逃命啊！！",
  ui_story_5053_50530401_52_dialog_content = "遇襲？……蜜雅！",
  ui_story_5053_50530401_53_dialog_content = "如果蜜雅還在看台上的話……不、不可能……",
  ui_story_5053_50530401_54_dialog_content = "姐姐還在宅邸裡，叛亂軍要是找上她的話……",
  ui_story_5053_50530401_55_dialog_content = "PlayerName，你先跟凱萊布一起回去！",
  ui_story_5053_50530401_56_dialog_content = "如果我最後沒能帶著蜜雅回去找你們……就叫加晴回溯時間，不要猶豫！",
  ui_story_5053_50530401_57_dialog_content = "城主大人！！！",
  ui_story_5053_50530401_58_dialog_content = "（這到底是怎麼回事？難道「永憶鏡晶」壞掉了嗎？）",
  ui_story_5053_50530401_59_dialog_content = "（還是說「黑天使」還活著，這些都是她做的……？）",
  ui_story_5053_50530401_60_dialog_content = "別發呆！先突出重圍再說！",
  ui_story_5053_50530401_61_dialog_content = "殺……殺……殺……",
  ui_story_5053_50530402_1_dialog_content = "喝！",
  ui_story_5053_50530402_2_dialog_content = "呃……",
  ui_story_5053_50530402_3_dialog_content = "可惡，這些倡狂的逆賊……老者，感謝你出手相助。",
  ui_story_5053_50530402_4_dialog_content = "兩位公主呢？",
  ui_story_5053_50530402_5_dialog_content = "兩位公主？與其關心死去的人，不如想想怎麼活下去吧。",
  ui_story_5053_50530402_6_dialog_content = "死去的人？你這話是什麼意思！",
  ui_story_5053_50530402_7_dialog_content = "卡蓮公主、薇羅妮卡公主還有城主大人遭到飛龍正面襲擊……<color=#FFB400>已經都死了</color>！",
  ui_story_5053_50530402_8_dialog_content = "……在哪裡？薇羅妮卡公主在哪裡？！",
  ui_story_5053_50530402_9_dialog_content = "還在看台上。怎麼，都這個節骨眼了，難不成你還想回收他們的遺骨？",
  ui_story_5053_50530402_10_dialog_content = "多謝。",
  ui_story_5053_50530402_11_dialog_content = "愚蠢……留戀於失去的東西，只會讓你為此喪命而已。",
  ui_story_5053_50530402_12_dialog_content = "姐姐！",
  ui_story_5053_50530402_13_dialog_content = "約書亞夫人！加晴！妳們在哪裡？",
  ui_story_5053_50530402_14_dialog_content = "為什麼沒有人回應我……姐姐！！！",
  ui_story_5053_50530402_15_dialog_content = "凱萊布，我在這裡。",
  ui_story_5053_50530402_16_dialog_content = "太好了，妳沒事……我還以為我又要失去妳了……",
  ui_story_5053_50530402_17_dialog_content = "叛亂提前開始了，我們得帶妳找個安全的地方。",
  ui_story_5053_50530402_18_dialog_content = "加晴呢？都這種時候了，她怎麼還是到處亂跑？",
  ui_story_5053_50530402_19_dialog_content = "凱萊布，別著急，事情一件一件說。",
  ui_story_5053_50530402_20_dialog_content = "你看你出了這麼多汗，連衣服領子都皺了。過來，我幫你整理一下。",
  ui_story_5053_50530402_21_dialog_content = "啊？呃，這種事我自己來就……",
  ui_story_5053_50530402_22_dialog_content = "謝、謝謝姐姐。",
  ui_story_5053_50530402_23_dialog_content = "看來約書亞夫人沒事，但加晴去哪了呢？",
  ui_story_5053_50530402_24_dialog_content = "加晴！妳在哪裡！！",
  ui_story_5053_50530402_25_dialog_content = "呃……",
  ui_story_5053_50530402_26_dialog_content = "姐……姐姐？",
  ui_story_5053_50530402_27_dialog_content = "怎麼了，凱萊布？",
  ui_story_5053_50530402_28_dialog_content = "這、這是……",
  ui_story_5053_50530402_29_dialog_content = "為……什麼？",
  ui_story_5053_50530402_30_dialog_content = "凱萊布，你的胸口……？！",
  ui_story_5053_50530402_31_dialog_content = "這是路上受的傷嗎？不、不對……",
  ui_story_5053_50530402_32_dialog_content = "都這麼大了，怎麼還是喜歡坐在地上呢。",
  ui_story_5053_50530402_33_dialog_content = "你還是這麼幼稚，凱萊布。",
  ui_story_5053_50530402_34_dialog_content = "真令人失望。",
  ui_story_5053_50530402_35_dialog_content = "為……什麼……",
  ui_story_5053_50530402_36_dialog_content = "姐……姐……",
  ui_story_5053_50530402_37_dialog_content = "蜜雅……",
  ui_story_5053_50530402_38_dialog_content = "<color=#e8d9bb>……</color>",
  ui_story_5053_50530402_39_dialog_content = "我知道，時間可以回溯……",
  ui_story_5053_50530402_40_dialog_content = "<color=#e8d9bb>............</color>",
  ui_story_5053_50530402_41_dialog_content = "但我唯獨不想讓妳經歷這些……",
  ui_story_5053_50530402_42_dialog_content = "即使將妳送離身邊、被妳討厭，只要妳能平安活著，我什麼都無所謂……",
  ui_story_5053_50530402_43_dialog_content = "<color=#e8d9bb>………………</color>",
  ui_story_5053_50530402_44_dialog_content = "<size=45>吼——！</size>",
  ui_story_5053_50530402_45_dialog_content = "殺死我的家人之後，還想殺死我嗎？",
  ui_story_5053_50530402_46_dialog_content = "我會把你帶給我家人的痛苦，加倍還給你……",
  ui_story_5053_50530402_47_dialog_content = "<size=45>吼嗚——！</size>",
  ui_story_5053_50530402_48_dialog_content = "<size=45>受死吧！！！</size>",
  ui_story_5053_50530402_49_dialog_content = "<color=#e8d9bb>噠、噠......</color>",
  ui_story_5053_50530402_50_dialog_content = "（為什麼？為什麼？為什麼？為什麼？！）",
  ui_story_5053_50530402_51_dialog_content = "（約書亞夫人為什麼會殺掉凱萊布？他可是她的親弟弟啊！）",
  ui_story_5053_50530402_52_dialog_content = "<color=#e8d9bb>噠、噠、噠……</color>",
  ui_story_5053_50530402_53_dialog_content = "（難道這個世界的人，真的都已經瘋掉了？）",
  ui_story_5053_50530402_54_dialog_content = "（還是我一直被困在噩夢裡醒不過來啊？！）",
  ui_story_5053_50530402_55_dialog_content = "<color=#e8d9bb>噠、噠、噠、噠……</color>",
  ui_story_5053_50530402_56_dialog_content = "（她走過去了？）",
  ui_story_5053_50530402_57_dialog_content = "（但我也不能一直藏在桌子底下……接下來怎麼辦？）",
  ui_story_5053_50530402_58_dialog_content = "<color=#e8d9bb>噠、噠。</color>",
  ui_story_5053_50530402_59_dialog_content = "（腳步聲，停下來了？）",
  ui_story_5053_50530402_60_dialog_content = "找、到、你、囉～",
  ui_story_5053_50530402_61_dialog_content = "啊？！",
  ui_story_5053_50530402_62_dialog_content = "哎呀，捉迷藏這種遊戲，連卡蓮都不玩了呢。",
  ui_story_5053_50530402_63_dialog_content = "PlayerName也不是小孩子了，你還要我陪你玩到什麼時候？",
  ui_story_5053_50530402_64_dialog_content = "呼哧......呼哧......",
  ui_story_5053_50530402_65_dialog_content = "別跑了，逃只會讓你死得更痛苦而已。",
  ui_story_5053_50530402_66_dialog_content = "蜜雅、凱萊布……他們的光能真不錯，我從未如此充實過。",
  ui_story_5053_50530402_67_dialog_content = "那麼，吸收了空裔的光能會不會不一樣？或許我也可以讀懂他人心思？",
  ui_story_5053_50530402_68_dialog_content = "我不會讓妳得逞的！",
  ui_story_5053_50530402_69_dialog_content = "說得也是，在這個世界我本身就可以控制別人。",
  ui_story_5053_50530402_70_dialog_content = "多麼純粹的關係啊，真舒服。",
  ui_story_5053_50530402_71_dialog_content = "呼哧......呼哧......",
  ui_story_5053_50530402_72_dialog_content = "（前面只有一扇門了，千萬別是死路啊！）",
  ui_story_5053_50530402_73_dialog_content = "那裡是……呵，這就是空之末裔的直覺嗎。",
  ui_story_5053_50530402_74_dialog_content = "真會挑。",
  ui_story_5053_50530402_75_dialog_content = "<color=#e8d9bb>吱呀——</color>",
  ui_story_5053_50530402_76_dialog_content = "<color=#e8d9bb>……</color>",
  ui_story_5053_50530402_77_dialog_content = "加晴……？！",
  ui_story_5053_50530402_78_dialog_content = "加晴……？身體好冰……沒有呼吸了……",
  ui_story_5053_50530402_79_dialog_content = "你還挺會挑地方的嘛，PlayerName。",
  ui_story_5053_50530402_80_dialog_content = "北境的占卜師懂得操作「永憶鏡晶」，第一個就被我殺死了。",
  ui_story_5053_50530402_81_dialog_content = "不然你以為，我為什麼特地把她留下來？",
  ui_story_5053_50530402_82_dialog_content = "……約書亞夫人，我不明白，妳究竟為什麼要這麼做？",
  ui_story_5053_50530402_83_dialog_content = "為什麼要殺死加晴、妳弟弟……還有我？",
  ui_story_5053_50530402_84_dialog_content = "很難理解嗎？我需要你們身上的力量。",
  ui_story_5053_50530402_85_dialog_content = "我與你們無冤無仇，但這一切都是必要的犧牲。",
  ui_story_5053_50530402_86_dialog_content = "……我不明白，妳真的是約書亞嗎？",
  ui_story_5053_50530402_87_dialog_content = "妳到底，是什麼東西？",
  ui_story_5053_50530402_88_dialog_content = "我就是約書亞！真正的約書亞！",
  ui_story_5053_50530402_89_dialog_content = "睜大你的眼睛，好好看清楚！在死去之前永遠記住我的模樣吧。",
  ui_story_5053_50530402_90_dialog_content = "<color=#e8d9bb>咻——！</color>",
  ui_story_5053_50530402_91_dialog_content = "嗯……？",
  ui_story_5053_50530402_92_dialog_content = "PlayerName……快、快過來我身邊……",
  ui_story_5053_50530402_93_dialog_content = "加晴？！",
  ui_story_5053_50530402_94_dialog_content = "原來妳還活著，我還以為妳已經……",
  ui_story_5053_50530402_95_dialog_content = "你忘了……？我可是從小就四處旅行的占卜師唷……",
  ui_story_5053_50530402_96_dialog_content = "在野獸面前裝死什麼的，對我來說只是小菜一碟……咳咳咳。",
  ui_story_5053_50530402_97_dialog_content = "加晴！",
  ui_story_5053_50530402_98_dialog_content = "……其他人呢？",
  ui_story_5053_50530402_99_dialog_content = "……",
  ui_story_5053_50530402_100_dialog_content = "大家……可惡啊……！",
  ui_story_5053_50530402_101_dialog_content = "利用北境占卜術製造以假亂真的幻覺……怪不得能製造出「永憶鏡晶」這樣的東西。",
  ui_story_5053_50530402_102_dialog_content = "真是令人噁心的小聰明。",
  ui_story_5053_50530402_103_dialog_content = "不好意思啦，我從小就不是個聽話的好孩子……！",
  ui_story_5053_50530402_104_dialog_content = "現在，就讓妳乖乖聽話！！！",
  ui_story_5053_50530402_105_dialog_content = "水晶球，防護！",
  ui_story_5053_50530402_106_dialog_content = "PlayerName，把「永憶鏡晶」拿出來吧。",
  ui_story_5053_50530402_107_dialog_content = "把手放在上面。哪怕我撐不到最後……",
  ui_story_5053_50530402_108_dialog_content = "你也絕不能放手。",
  ui_story_5053_50530402_109_dialog_content = "加晴……我知道了！",
  ui_story_5053_50530402_110_dialog_content = "里特羅，里特羅，里特羅！",
  ui_story_5053_50530402_111_dialog_content = "讓時光倒流回起點……",
  ui_story_5053_50530402_112_dialog_content = "阿布拉卡達布拉……唔呃……！",
  ui_story_5053_50530402_113_dialog_content = "啊……",
  ui_story_5053_50530402_114_dialog_content = "加晴！加晴——！！！",
  ui_story_5053_50530501_0X_dialog_content = "<color=#e8d9bb>——第二次回溯後——</color>",
  ui_story_5053_50530501_1_dialog_content = "城主殿下，一切準備就緒。",
  ui_story_5053_50530501_2_dialog_content = "遊行的馬車已經停在門外，隨時可以出發。",
  ui_story_5053_50530501_3_dialog_content = "……",
  ui_story_5053_50530501_4_dialog_content = "殿下，您還在擔心夫人嗎？",
  ui_story_5053_50530501_5_dialog_content = "約書亞一向健康，很少會說自己身體不適，尤其是在今天這樣的日子。",
  ui_story_5053_50530501_6_dialog_content = "夫人近來為了向各位貴族夫人宣傳城主的政策，的確費了不少精力。",
  ui_story_5053_50530501_7_dialog_content = "請您放心，我會照顧好夫人的。",
  ui_story_5053_50530501_8_dialog_content = "啊，唔……",
  ui_story_5053_50530501_9_dialog_content = "這裡是……？",
  ui_story_5053_50530501_10_dialog_content = "等等，這個地方……現在還是白天嗎？",
  ui_story_5053_50530501_11_dialog_content = "我被追著到處跑，在這裡發現了加晴，然後……",
  ui_story_5053_50530501_12_dialog_content = "（加晴，謝謝妳保護了我……）",
  ui_story_5053_50530501_13_dialog_content = "（但她現在不在這裡，難道又像我們進來時那樣，分散到其他地方去了嗎？）",
  ui_story_5053_50530501_14_dialog_content = "（約書亞夫人到底為什麼會襲擊我們？難道她真的不是約書亞？）",
  ui_story_5053_50530501_15_dialog_content = "（加晴用「永憶鏡晶」驗證過那個約書亞跟我們一樣，<color=#FFB400>不是幻影</color>。）",
  ui_story_5053_50530501_16_dialog_content = "我就是約書亞，真正的約書亞。",
  ui_story_5053_50530501_17_dialog_content = "（她特別強調自己是真正的約書亞，背後有什麼含義嗎？）",
  ui_story_5053_50530501_18_dialog_content = "（完全搞不懂。最重要的是，如果約書亞真的不對勁，我們要怎麼回去？）",
  ui_story_5053_50530501_19_dialog_content = "（啊啊……現在到底是什麼情況？為什麼只有我在這裡？！）",
  ui_story_5053_50530501_20_dialog_content = "<color=#e8d9bb>劈啪劈啪——</color>",
  ui_story_5053_50530501_21_dialog_content = "什麼聲音？那是……？！",
  ui_story_5053_50530501_22_dialog_content = "在……這裡？",
  ui_story_5053_50530501_23_dialog_content = "「黑天使」怎麼又追過來了啊？我們不是重設時間了嗎！",
  ui_story_5053_50530501_24_dialog_content = "是、是姐姐的聲音……",
  ui_story_5053_50530501_25_dialog_content = "這……裡！",
  ui_story_5053_50530501_26_dialog_content = "白夜！庇護！",
  ui_story_5053_50530501_27_dialog_content = "凱萊布，戰場上不要胡思亂想！",
  ui_story_5053_50530501_28_dialog_content = "呀啊——！",
  ui_story_5053_50530501_29_dialog_content = "主宰之刃！",
  ui_story_5053_50530501_30_dialog_content = "我……恨……",
  ui_story_5053_50530501_31_dialog_content = "呃！",
  ui_story_5053_50530501_32_dialog_content = "好快的攻勢……！城主大人，小心！",
  ui_story_5053_50530501_33_dialog_content = "妳就如此想與我一個人交手嗎？",
  ui_story_5053_50530501_34_dialog_content = "如妳所願。",
  ui_story_5053_50530501_35_dialog_content = "舒……瓦茲……！",
  ui_story_5053_50530501_36_dialog_content = "蜜雅他們又在和那個「黑天使」戰鬥……時間成功回溯到最初了！",
  ui_story_5053_50530501_37_dialog_content = "得先下去幫大家！",
  ui_story_5053_50530501_38_dialog_content = "……你，在這裡。",
  ui_story_5053_50530501_39_dialog_content = "是衛兵？來得正……",
  ui_story_5053_50530501_40_dialog_content = "可疑人員……消滅……",
  ui_story_5053_50530501_41_dialog_content = "（咦？這幾個人……怎麼有點不對勁？）",
  ui_story_5053_50530501_42_dialog_content = "你們在說什麼啊？",
  ui_story_5053_50530501_43_dialog_content = "約書亞夫人……什麼人……侵入？",
  ui_story_5053_50530501_44_dialog_content = "侵入者捉拿……殺死……捉拿……殺死！",
  ui_story_5053_50530501_45_dialog_content = "（他們看起來神智異常，簡直就和廣場上的那些人一樣？！）",
  ui_story_5053_50530501_46_dialog_content = "啊啊啊啊！！！",
  ui_story_5053_50530502_1_dialog_content = "<color=#e8d9bb>轟——！！</color>",
  ui_story_5053_50530502_2_dialog_content = "呃……咳咳……",
  ui_story_5053_50530502_3_dialog_content = "那個「黑天使」去哪裡了？",
  ui_story_5053_50530502_4_dialog_content = "好像是沿著外面的小路逃跑了……",
  ui_story_5053_50530502_5_dialog_content = "城主大人那一下，真的是天崩地裂！",
  ui_story_5053_50530502_6_dialog_content = "「黑天使」再厲害也一定傷得不輕，應該逃不了多遠吧？",
  ui_story_5053_50530502_7_dialog_content = "……",
  ui_story_5053_50530502_8_dialog_content = "舅父大人，您還是很在意那個「黑天使」嗎？",
  ui_story_5053_50530502_9_dialog_content = "畢竟牠的聲音……不，算了。姐姐怎麼可能變成怪物呢。",
  ui_story_5053_50530502_10_dialog_content = "不對啊，總覺得少了些什麼……啊，PlayerName到哪裡去了？",
  ui_story_5053_50530502_11_dialog_content = "對啊！PlayerName到哪裡去了啊？！",
  ui_story_5053_50530502_12_dialog_content = "哎呀，各位在這裡啊。",
  ui_story_5053_50530502_13_dialog_content = "呼、呼……甩掉了嗎？",
  ui_story_5053_50530502_14_dialog_content = "在那裡……在那裡！",
  ui_story_5053_50530502_15_dialog_content = "捉住、殺死、入侵者！",
  ui_story_5053_50530502_16_dialog_content = "（可惡！這些衛兵明明全都神智不清，怎麼這麼難纏！）",
  ui_story_5053_50530502_17_dialog_content = "不對，是，那裡……！",
  ui_story_5053_50530502_18_dialog_content = "（……啊，有了！）",
  ui_story_5053_50530502_19_dialog_content = "<color=#e8d9bb>咚——</color>",
  ui_story_5053_50530502_20_dialog_content = "（這是物資車嗎？應該是為了節日準備的……他們應該看不到這裡。）",
  ui_story_5053_50530502_21_dialog_content = "那裡，沒有，換……",
  ui_story_5053_50530502_22_dialog_content = "去，去那條街……",
  ui_story_5053_50530502_23_dialog_content = "哎呀，他們是在追人嗎？看起來怪怪的。",
  ui_story_5053_50530502_24_dialog_content = "不知道，應該不會有人在這種日子鬧事吧。況且遊行就快要開始了。",
  ui_story_5053_50530502_25_dialog_content = "好期待啊～",
  ui_story_5053_50530502_26_dialog_content = "（呼～姑且是躲過去了……）",
  ui_story_5053_50530502_27_dialog_content = "（剛剛從來往路人的說法來看，遊行還沒開始？）",
  ui_story_5053_50530502_28_dialog_content = "（看來我還有些時間，重新整理一下情況吧。）",
  ui_story_5053_50530502_29_dialog_content = "（目前有以下幾個問題需要思考……）",
  ui_story_5053_50530502_30_option_content = "當下的狀況",
  ui_story_5053_50530502_31_dialog_content = "（現在的時間是遊行之前，大家大概已經見到約書亞夫人了。）",
  ui_story_5053_50530502_32_dialog_content = "（可以預想的情況有兩種，關鍵在於，<color=#FFB400>大家是否記得第二次回溯前發生的事情</color>。）",
  ui_story_5053_50530502_33_dialog_content = "（如果記得的話，現在應該已經和約書亞夫人打起來，或是已經逃跑了吧。）",
  ui_story_5053_50530502_34_dialog_content = "（這種情況下，大家肯定會來找我，而我對白夜城不夠熟悉，最好不要輕舉妄動。）",
  ui_story_5053_50530502_35_dialog_content = "（如果不記得的話，應該已經再次中了約書亞的圈套……）",
  ui_story_5053_50530502_36_dialog_content = "（那麼事情會像上次回溯前那樣發展，加晴會被約書亞留下來，其他人前往廣場。）",
  ui_story_5053_50530502_37_dialog_content = "（我現在就在廣場附近，在這裡靜靜等待大家到來才是最好的做法。）",
  ui_story_5053_50530502_38_dialog_content = "（而加晴……可惡！只能先跟大家會合再去救加晴了！）",
  ui_story_5053_50530502_39_option_content = "關於「記憶」",
  ui_story_5053_50530502_40_dialog_content = "（按照加晴的說法，使用占卜術時，無論如何都必須<color=#FFB400>嚴格遵守規則</color>。）",
  ui_story_5053_50530502_41_dialog_content = "（第一次回溯的時候，加晴就提醒我們要<color=#FFB400>牽緊彼此的手</color>。）",
  ui_story_5053_50530502_42_dialog_content = "（而約書亞也說，由於她第一次回溯時跟我們在一起，所以才記得第一次回溯前發生的事。）",
  ui_story_5053_50530502_43_dialog_content = "（也就是說，第一次回溯的時候，她也有偷偷拉住我們的手，所以才保留了記憶？）",
  ui_story_5053_50530502_44_dialog_content = "（如果是這樣的話，第二次發動回溯的時候，只有我和加晴抓住「永憶鏡晶」。）",
  ui_story_5053_50530502_45_dialog_content = "（說不定，約書亞跟其他人根本不記得第二次回溯前的事情？）",
  ui_story_5053_50530502_46_dialog_content = "（而記得這一切的只有我和加晴……？）",
  ui_story_5053_50530502_47_dialog_content = "（希望如此……）",
  ui_story_5053_50530502_48_option_content = "追兵、飛龍、「黑天使」",
  ui_story_5053_50530502_49_dialog_content = "（這些來抓我的士兵又是怎麼回事？）",
  ui_story_5053_50530502_50_dialog_content = "（他們的神情和廣場上瘋狂的人群很像，彷彿是得了同一種疾病……或是被人控制了。）",
  ui_story_5053_50530502_51_dialog_content = "（這一路上，他們簡直就像故意要把我和大家隔開一樣，不斷在追殺我，想把我逼離宅邸。）",
  ui_story_5053_50530502_52_dialog_content = "（我在「永憶鏡晶」裡無法使用感應能力，大家在庭院戰鬥的時候也沒有察覺到樓上的異樣。）",
  ui_story_5053_50530502_53_dialog_content = "（導致我錯過跟大家會合的機會……）",
  ui_story_5053_50530502_54_dialog_content = "（如果約書亞有記憶，那麼這些追兵就是來殺我滅口的。）",
  ui_story_5053_50530502_55_dialog_content = "（如果約書亞沒有之前的記憶，那麼她就是在刻意追殺落單者。）",
  ui_story_5053_50530502_56_dialog_content = "（沒錯，就像她一開始把我們和加晴分開一樣。）",
  ui_story_5053_50530502_57_dialog_content = "（和「黑天使」戰鬥應該也是她設的局，就是為了將我們分開，提前殺死加晴。）",
  ui_story_5053_50530502_58_dialog_content = "（追逐我的衛兵是她的手下……）",
  ui_story_5053_50530502_59_dialog_content = "（那麼廣場上瘋狂的人群，還有那條黑色的飛龍或許也是她的手筆。）",
  ui_story_5053_50530502_60_dialog_content = "（這麼一看，我們第一次回溯後經歷的一切都是她設計好的……真是恐怖。）",
  ui_story_5053_50530502_61_dialog_content = "（但「黑天使」呢？牠和約書亞到底是什麼關係？）",
  ui_story_5053_50530502_62_dialog_content = "（這一切都是她們兩個演的一齣戲嗎？還是說，其中還有別的真相……）",
  ui_story_5053_50530502_63_dialog_content = "（關於這部分，知道的還是太少了。）",
  ui_story_5053_50530502_64_dialog_content = "（哎……想了這麼多，我能做的也就只有在這裡等待大家而已。）",
  ui_story_5053_50530502_65_dialog_content = "（先跟大家會合後，把真相告訴大家，帶著大家一起去救加晴……）",
  ui_story_5053_50530502_66_dialog_content = "（各位，拜託千萬不要有事啊！）",
  ui_story_5053_50530601_1_dialog_content = "也就是說……",
  ui_story_5053_50530601_2_dialog_content = "要嘛我們殺死「黑天使」，帶著約書亞夫人離開這裡。",
  ui_story_5053_50530601_3_dialog_content = "要嘛我們就被「黑天使」殺死，放任她在現實世界復活？",
  ui_story_5053_50530601_4_dialog_content = "是的，沒錯。",
  ui_story_5053_50530601_5_dialog_content = "……",
  ui_story_5053_50530601_6_dialog_content = "出去的計畫我是明白了，但……",
  ui_story_5053_50530601_7_dialog_content = "PlayerName去哪裡了啊？我很擔心他。",
  ui_story_5053_50530601_8_dialog_content = "和大家分散太久的話，不知道會不會發生什麼意外。",
  ui_story_5053_50530601_9_dialog_content = "PlayerName的事我不太清楚，但我可以派衛兵去找，不用太擔心。",
  ui_story_5053_50530601_10_dialog_content = "現在時間有限，為了讓大家平安出去，我認為應該優先處理掉那個怪物。",
  ui_story_5053_50530601_11_dialog_content = "那我們就快去收拾那個「黑天使」吧！",
  ui_story_5053_50530601_12_dialog_content = "不，加晴妳得跟我一起留下來。",
  ui_story_5053_50530601_13_dialog_content = "咦？為什麼？我的水晶球在戰鬥中可以發揮很多作用的！",
  ui_story_5053_50530601_14_dialog_content = "嗯，我知道。但加晴妳是「永憶鏡晶」的操作者。",
  ui_story_5053_50530601_15_dialog_content = "其他人如果出了事，我們都可以透過回溯時間讓一切恢復原狀。",
  ui_story_5053_50530601_16_dialog_content = "但要是妳出了事，那可就真的無法挽回了……",
  ui_story_5053_50530601_17_dialog_content = "說、說得也對……",
  ui_story_5053_50530601_18_dialog_content = "那、那如果媽媽和加晴都在這裡，就把卡蓮也叫回來吧。",
  ui_story_5053_50530601_19_dialog_content = "媽媽和我都不在，卡蓮和父親他們在一起也很寂寞吧，那樣有點太可憐了。",
  ui_story_5053_50530601_20_dialog_content = "好的，那等一下就派侍衛轉告她，讓她先回房間休息吧。",
  ui_story_5053_50530601_21_dialog_content = "不讓卡蓮和媽媽待在一起嗎？難得她期待這麼久的日子，只是讓她自己回房間？",
  ui_story_5053_50530601_22_dialog_content = "卡蓮從很久之前就在期待遊行了，這樣她會不會難過呢……",
  ui_story_5053_50530601_23_dialog_content = "小薇，「永憶鏡晶」中的一切都是幻影，不是真實的。",
  ui_story_5053_50530601_24_dialog_content = "我們應該以大局為重，不要被枝微末節的小事影響首要目標。",
  ui_story_5053_50530601_25_dialog_content = "唔......",
  ui_story_5053_50530601_26_dialog_content = "姐姐說得沒錯，這裡的一切都是幻象，是蜜雅妳太感情用事了。",
  ui_story_5053_50530601_27_dialog_content = "好、好吧，對不起……是我不夠成熟……",
  ui_story_5053_50530601_28_dialog_content = "……",
  ui_story_5053_50530601_29_dialog_content = "約書亞說得有理，我也認為大家應該以安全為重。既然如此，不如讓凱萊布也留下來吧。",
  ui_story_5053_50530601_30_dialog_content = "我親自去找PlayerName，先讓大家安全會合。",
  ui_story_5053_50530601_31_dialog_content = "沒有必要花這個時間。派衛兵去找PlayerName也是一樣的。",
  ui_story_5053_50530601_32_dialog_content = "但那個怪物唯有靠大家齊心協力才有可能戰勝。",
  ui_story_5053_50530601_33_dialog_content = "兩件事哪邊重要，相信你能夠判斷。理智一點吧。",
  ui_story_5053_50530601_34_dialog_content = "妳對利弊的權衡還是這麼精明。不得不說，這對話真令人懷念，彷彿回到了最早的時光呢。",
  ui_story_5053_50530601_35_dialog_content = "……",
  ui_story_5053_50530601_36_dialog_content = "現在不是夫妻拌嘴的時間吧？本來時間就不多了。",
  ui_story_5053_50530601_37_dialog_content = "總之我心中自有分寸，不需要旁人安排。",
  ui_story_5053_50530601_38_dialog_content = "蜜雅，我們走。",
  ui_story_5053_50530601_39_dialog_content = "好、好的，父親。",
  ui_story_5053_50530601_40_dialog_content = "怎麼回事啊這個人！突然怪怪的。",
  ui_story_5053_50530601_41_dialog_content = "……",
  ui_story_5053_50530601_42_dialog_content = "蜜雅，妳因為約書亞的事不開心嗎？",
  ui_story_5053_50530601_43_dialog_content = "啊，那個，我……確實是有一點……",
  ui_story_5053_50530601_44_dialog_content = "可能是我自己的問題吧……媽媽和我們分開太久了，總覺得有點陌生。",
  ui_story_5053_50530601_45_dialog_content = "那在妳印象中，母親約書亞是個怎麼樣的人？",
  ui_story_5053_50530601_46_dialog_content = "媽媽……媽媽是我見過最溫柔、最寬容，最疼孩子的人。",
  ui_story_5053_50530601_47_dialog_content = "嗯，我心中的約書亞，也是一位溫柔時如暖陽和煦，堅定時又真誠果敢的女性。",
  ui_story_5053_50530601_48_dialog_content = "父親……！",
  ui_story_5053_50530601_49_dialog_content = "蜜雅，多相信自己一點，也相信妳心裡那個溫柔堅定的媽媽。",
  ui_story_5053_50530601_50_dialog_content = "多相信自己？",
  ui_story_5053_50530601_51_dialog_content = "這次意外中，妳雖然仍有笨拙之處，但也展現了強大、勇敢的一面。",
  ui_story_5053_50530601_52_dialog_content = "我覺得，是時候該承認妳已經長大了。",
  ui_story_5053_50530601_53_dialog_content = "今後我會尊重妳的意見，不會輕易干涉。",
  ui_story_5053_50530601_54_dialog_content = "無論是關乎妳母親、卡蓮，還是其他事，都不必畏首畏尾。",
  ui_story_5053_50530601_55_dialog_content = "妳覺得正確的事，就勇敢去做吧，我相信妳。",
  ui_story_5053_50530601_56_dialog_content = "（父親……是在鼓勵我嗎？）",
  ui_story_5053_50530601_57_dialog_content = "（幾乎沒聽他對我說過這樣的話，但感覺……很開心。）",
  ui_story_5053_50530601_58_dialog_content = "謝謝，父親。我會努力變得更加勇敢的。",
  ui_story_5053_50530601_59_dialog_content = "那，按照剛才所說的計畫，我先去看台。一旦察覺到「黑天使」在附近，我就呼叫大家。",
  ui_story_5053_50530601_60_dialog_content = "嗯，蜜雅，萬事小心。",
  ui_story_5053_50530601_61_dialog_content = "（蜜雅那邊暫時不會有什麼問題。但PlayerName，這個時候會去哪裡？）",
  ui_story_5053_50530601_62_dialog_content = "（他的失蹤給我一種強烈的違和感，到底……）",
  ui_story_5053_50530601_63_dialog_content = "在……這……",
  ui_story_5053_50530601_64_dialog_content = "這……裡！",
  ui_story_5053_50530601_65_dialog_content = "這聲音是？",
  ui_story_5053_50530601_66_dialog_content = "舒……瓦……茲……！",
  ui_story_5053_50530601_67_dialog_content = "啊啊啊！！",
  ui_story_5053_50530601_68_dialog_content = "竟然出現在這種地方。",
  ui_story_5053_50530601_69_dialog_content = "也罷，至少不會傷及其他人。",
  ui_story_5053_50530601_70_dialog_content = "好痛……殺……殺……！",
  ui_story_5053_50530601_71_dialog_content = "休想用約書亞的聲音蠱惑我。",
  ui_story_5053_50530701_1_dialog_content = "呃……啊！",
  ui_story_5053_50530701_2_dialog_content = "（蜜雅跟凱萊布都不在，戰況幾乎勢均力敵。只是這裡有不少暗鬼在影響戰局。）",
  ui_story_5053_50530701_3_dialog_content = "「白夜！庇護！」",
  ui_story_5053_50530701_4_dialog_content = "妳我幾乎打成了平手，現在滿意了嗎？",
  ui_story_5053_50530701_5_dialog_content = "舒……瓦……茲……！",
  ui_story_5053_50530701_6_dialog_content = "我……恨……你……！",
  ui_story_5053_50530701_7_dialog_content = "為……什麼……",
  ui_story_5053_50530701_8_dialog_content = "好……痛……苦！為什麼……背叛……我！",
  ui_story_5053_50530701_9_dialog_content = "一起……創造……未來……你……說的！你……說……的……！",
  ui_story_5053_50530701_10_dialog_content = "為……什……麼……犧牲……家庭……家人……我……！",
  ui_story_5053_50530701_11_dialog_content = "我……好……痛！！",
  ui_story_5053_50530701_12_dialog_content = "妳在說什麼？",
  ui_story_5053_50530701_13_dialog_content = "早知……早知……這樣……",
  ui_story_5053_50530701_14_dialog_content = "我……何必……擁有……感情……",
  ui_story_5053_50530701_15_dialog_content = "何必……選……擇你！！！",
  ui_story_5053_50530701_16_dialog_content = "？！",
  ui_story_5053_50530701_17_dialog_content = "約書亞……？！",
  ui_story_5053_50530701_18_dialog_content = "這怎麼可能？",
  ui_story_5053_50530701_19_dialog_content = "……！！！",
  ui_story_5053_50530701_20_dialog_content = "啊……！蜜……雅……危險……",
  ui_story_5053_50530701_21_dialog_content = "你去哪裡？！",
  ui_story_5053_50530701_22_dialog_content = "嘎嗷——！",
  ui_story_5053_50530701_23_dialog_content = "可惡！真礙事！",
  ui_story_5053_50530701_24_dialog_content = "（小舒瓦茲的演講結束，決鬥儀式正式開始了。）",
  ui_story_5053_50530701_25_dialog_content = "（按照事情發生時間，接下來飛龍會出現，人群和士兵也會跟著一起變得瘋狂……）",
  ui_story_5053_50530701_26_dialog_content = "（我可以趁這場混亂跑到看台上！一定要和大家會合，把約書亞的事情告訴大家！）",
  ui_story_5053_50530701_27_dialog_content = "吼——！",
  ui_story_5053_50530701_28_dialog_content = "呀啊啊啊啊！！！",
  ui_story_5053_50530701_29_dialog_content = "那是、那是什麼啊！！",
  ui_story_5053_50530701_30_dialog_content = "救命啊！！快、快逃！！！",
  ui_story_5053_50530701_31_dialog_content = "好！就趁這個時候，一鼓作氣去找城主大人他們——",
  ui_story_5053_50530701_32_dialog_content = "<color=#e8d9bb>轟！！</color>",
  ui_story_5053_50530701_33_dialog_content = "什麼……！那、那是？！",
  ui_story_5053_50530701_34_dialog_content = "吼——！",
  ui_story_5053_50530701_35_dialog_content = "<color=#e8d9bb>轟隆！！！</color>",
  ui_story_5053_50530701_36_dialog_content = "啊……！！呃！！",
  ui_story_5053_50530701_37_dialog_content = "這是怎麼回事？那是「黑天使」嗎？！",
  ui_story_5053_50530701_38_dialog_content = "她在天上做什麼？阻擋飛龍的砲擊？",
  ui_story_5053_50530701_39_dialog_content = "是飛龍？！",
  ui_story_5053_50530701_40_dialog_content = "飛龍萬歲！飛龍萬歲！！",
  ui_story_5053_50530701_41_dialog_content = "反叛軍……是卡爾帝瑪家族？",
  ui_story_5053_50530701_42_dialog_content = "竟然在這時候現身，好大的膽子。",
  ui_story_5053_50530701_43_dialog_content = "（但空中那隻黑色怪物是怎麼回事……？）",
  ui_story_5053_50530701_44_dialog_content = "姐、姐姐，發生了什麼事？",
  ui_story_5053_50530701_45_dialog_content = "卡蓮，過來我身後！",
  ui_story_5053_50530701_46_dialog_content = "（那是「黑天使」，這是怎麼回事？）",
  ui_story_5053_50530701_47_dialog_content = "這到底是……？！",
  ui_story_5053_50530701_48_dialog_content = "薇羅妮卡、卡蓮，退後！",
  ui_story_5053_50530701_49_dialog_content = "<color=#e8d9bb>啪——</color>",
  ui_story_5053_50530701_50_dialog_content = "（她被飛龍的火焰擊中了？不，她擋下了飛龍的火焰……）",
  ui_story_5053_50530701_51_dialog_content = "但她為什麼……",
  ui_story_5053_50530701_52_dialog_content = "姐姐，她好像幫我們抵擋了飛龍的攻擊。",
  ui_story_5053_50530701_53_dialog_content = "她、她是昏過去了嗎？",
  ui_story_5053_50530701_54_dialog_content = "「黑天使」……？我不懂……",
  ui_story_5053_50530701_55_dialog_content = "蜜雅！！！",
  ui_story_5053_50530701_56_dialog_content = "蜜雅！妳沒受傷吧？！",
  ui_story_5053_50530701_57_dialog_content = "PlayerName？我沒事，別擔心。你怎麼會在這裡？",
  ui_story_5053_50530701_58_dialog_content = "在、在、在這裡……！",
  ui_story_5053_50530701_59_dialog_content = "殺……殺……入侵者！",
  ui_story_5053_50530701_60_dialog_content = "可惡！怎麼又是這些人！",
  ui_story_5053_50530701_61_dialog_content = "這些衛兵，怎麼看起來不太對勁？！",
  ui_story_5053_50530701_62_dialog_content = "飛龍萬歲！飛龍萬歲！！",
  ui_story_5053_50530701_63_dialog_content = "衝啊！",
  ui_story_5053_50530701_64_dialog_content = "PlayerName小心！那些反叛軍也要衝上來了！",
  ui_story_5053_50530701_65_dialog_content = "蜜雅，其他事情一會再說，戰況太混亂了，先迎戰吧！",
  ui_story_5053_50530701_66_dialog_content = "飛龍也好，黑色怪物也好，竟敢在這種日子挑戰舒瓦茲家的權威！",
  ui_story_5053_50530701_67_dialog_content = "吼！ ！ ！",
  ui_story_5053_50530701_68_dialog_content = "小心！先不要管那個「黑天使」了。",
  ui_story_5053_50530701_69_dialog_content = "這次的敵人和以往不同，你沒辦法再一擊幹掉牠了。",
  ui_story_5053_50530701_70_dialog_content = "你又是誰……？",
  ui_story_5053_50530701_71_dialog_content = "集中火力，和我一起對付飛龍！",
  ui_story_5053_50530701_72_dialog_content = "區區飛龍而已。",
  ui_story_5053_50530701_73_dialog_content = "白夜之光！",
  ui_story_5053_50530701_74_dialog_content = "嗷——吼！！！",
  ui_story_5053_50530701_75_dialog_content = "什麼？！刺穿牠咽喉的傷口，竟然立刻癒合了？！",
  ui_story_5053_50530701_76_dialog_content = "高速的癒合能力？難不成……是「不死性」？",
  ui_story_5053_50530701_77_dialog_content = "怎麼可能？誰會賦予牠如此強大的能力？難道是邁木？",
  ui_story_5053_50530701_78_dialog_content = "……",
  ui_story_5053_50530701_79_dialog_content = "當心，牠的下一波進攻要來了。",
  ui_story_5053_50530801_1_dialog_content = "唔……哈啊……哈啊……",
  ui_story_5053_50530801_2_dialog_content = "殺、殺、殺……入侵者……殺！",
  ui_story_5053_50530801_3_dialog_content = "啊啊啊！殺殺殺！！",
  ui_story_5053_50530801_4_dialog_content = "可惡！怎麼這些不正常的衛兵越來越多了？！蜜雅，還撐得住嗎？",
  ui_story_5053_50530801_5_dialog_content = "他們的樣子太恐怖了，每個人都白眼上翻，臉上的表情也非常詭異……",
  ui_story_5053_50530801_6_dialog_content = "我還好，但瘋狂的敵人越來越多了！",
  ui_story_5053_50530801_7_dialog_content = "上一秒還在逃跑的平民，下一秒就加入了他們……就連倒下的反叛軍也……",
  ui_story_5053_50530801_8_dialog_content = "簡直就像是傳染病一樣……",
  ui_story_5053_50530801_9_dialog_content = "似乎被他們傷到就會變成那樣。蜜雅，一定要跟他們保持距離！",
  ui_story_5053_50530801_10_dialog_content = "但這樣下去沒完沒了，我們會撐不下去的……！",
  ui_story_5053_50530801_11_dialog_content = "這也是她計畫的一環嗎……？！誰能來支援我們？！城主大人！",
  ui_story_5053_50530801_12_dialog_content = "父親正在對抗飛龍，分身乏術啊！",
  ui_story_5053_50530801_13_dialog_content = "（父親，我該怎麼辦……？）",
  ui_story_5053_50530801_14_dialog_content = "無論是關乎妳母親、卡蓮，還是其他事，都不必畏首畏尾。",
  ui_story_5053_50530801_15_dialog_content = "妳覺得正確的事，就勇敢去做吧，我相信妳。",
  ui_story_5053_50530801_16_dialog_content = "（相信自己的判斷。相信自己的判斷。）",
  ui_story_5053_50530801_17_dialog_content = "希頗喀——！",
  ui_story_5053_50530801_18_dialog_content = "<color=#e8d9bb>轟隆！！！</color>",
  ui_story_5053_50530801_19_dialog_content = "好、好強！",
  ui_story_5053_50530801_20_dialog_content = "希頗喀，謝謝你願意回應我，我再也不會丟下你了……！",
  ui_story_5053_50530801_21_dialog_content = "蜜雅也太厲害了，這些受感染的衛兵全都被牠解決掉了！",
  ui_story_5053_50530801_22_dialog_content = "有幫上忙就太好了，我們快去另一邊幫父親吧！",
  ui_story_5053_50530801_23_dialog_content = "蜜雅……等一下……",
  ui_story_5053_50530801_24_dialog_content = "……呼、呼、呼……",
  ui_story_5053_50530801_25_dialog_content = "姐……姐姐……",
  ui_story_5053_50530801_26_dialog_content = "卡、卡蓮？！妳的頭在流血……？！",
  ui_story_5053_50530801_27_dialog_content = "卡蓮被那些瘋狂的士兵擊傷了？！那她豈不是也要變成……",
  ui_story_5053_50530801_28_dialog_content = "蜜雅，別靠近她！她的眼睛已經變得和他們一樣了！！",
  ui_story_5053_50530801_29_dialog_content = "卡蓮，妳放下槍……到姐姐這裡來。",
  ui_story_5053_50530801_30_dialog_content = "好嗎？",
  ui_story_5053_50530801_31_dialog_content = "……",
  ui_story_5053_50530801_32_dialog_content = "姐姐，我……好痛……",
  ui_story_5053_50530801_33_dialog_content = "卡蓮別怕，姐姐幫妳處理傷口。放下武器，好嗎？",
  ui_story_5053_50530801_34_dialog_content = "不，我的頭……好痛……！",
  ui_story_5053_50530801_35_dialog_content = "好奇怪的聲音……叫我殺了姐姐……我不要！",
  ui_story_5053_50530801_36_dialog_content = "卡蓮，不會的！姐姐會保護妳！",
  ui_story_5053_50530801_37_dialog_content = "姐姐……別過來！！",
  ui_story_5053_50530801_38_dialog_content = "……我是，卡蓮·德·舒瓦茲……高潔的舒瓦茲家族之女，白夜城的守衛者……",
  ui_story_5053_50530801_39_dialog_content = "卡蓮絕不會做出傷害家人之舉！絕不！",
  ui_story_5053_50530801_40_dialog_content = "唔……呃！卡蓮不會傷害姐姐，所以……",
  ui_story_5053_50530801_41_dialog_content = "對不起，姐姐，卡蓮沒辦法繼續陪著妳了。",
  ui_story_5053_50530801_42_dialog_content = "不，放下武器！不！不要！！",
  ui_story_5053_50530801_43_dialog_content = "卡蓮！！",
  ui_story_5053_50530801_44_dialog_content = "<color=#e8d9bb>……</color>",
  ui_story_5053_50530801_45_dialog_content = "長槍貫穿了她的脖子……",
  ui_story_5053_50530801_46_dialog_content = "卡蓮………自盡了…………",
  ui_story_5053_50530801_47_dialog_content = "……",
  ui_story_5053_50530801_48_dialog_content = "啊……啊……",
  ui_story_5053_50530801_49_dialog_content = "啊啊啊啊啊啊！！！！",
  ui_story_5053_50530801_50_dialog_content = "不要！！不要啊啊啊啊啊！！！",
  ui_story_5053_50530801_51_dialog_content = "蜜雅！蜜雅妳冷靜一點，這一切都不是真的……這裡的卡蓮只是幻影！！！",
  ui_story_5053_50530801_52_dialog_content = "卡蓮！！我不要失去妳啊啊啊……不要啊……小卡蓮，不要丟下我一個人……小卡蓮……",
  ui_story_5053_50530801_53_dialog_content = "蜜雅，冷靜一點！妳有聽到我說話嗎？蜜雅！！",
  ui_story_5053_50530801_54_dialog_content = "（蜜雅完全聽不到我的聲音……難道她的病又要發作了嗎？！）",
  ui_story_5053_50530801_55_dialog_content = "嗚啊啊啊啊！！！",
  ui_story_5053_50530801_56_dialog_content = "好燙！",
  ui_story_5053_50530801_57_dialog_content = "蜜雅的力量開始暴走了？！",
  ui_story_5053_50530801_58_dialog_content = "……",
  ui_story_5053_50530801_59_dialog_content = "妳、妳要幹什麼……？！",
  ui_story_5053_50530801_60_dialog_content = "不哭……",
  ui_story_5053_50530801_61_dialog_content = "小薇……不哭……我的寶貝……",
  ui_story_5053_50530801_62_dialog_content = "不要傷心……不要難過……",
  ui_story_5053_50530801_63_dialog_content = "啊……",
  ui_story_5053_50530801_64_dialog_content = "摘一束玫瑰……送給我的寶貝……♪",
  ui_story_5053_50530801_65_dialog_content = "暖風吹拂面龐……妳的笑顏就是唯一的珍寶……♪",
  ui_story_5053_50530801_66_dialog_content = "摘一束玫瑰……送給親愛的爸爸媽媽……♪",
  ui_story_5053_50530801_67_dialog_content = "任由世事變化……我們永遠是彼此的最愛……♪",
  ui_story_5053_50530801_68_dialog_content = "小薇……看……是媽媽……",
  ui_story_5053_50530801_69_dialog_content = "媽媽……？媽媽……",
  ui_story_5053_50530801_70_dialog_content = "嗚哇哇啊啊啊啊啊！",
  ui_story_5053_50530801_71_dialog_content = "卡蓮她，小卡蓮她……",
  ui_story_5053_50530801_72_dialog_content = "小卡蓮的手……她的手明明那麼溫暖……她的血……",
  ui_story_5053_50530801_73_dialog_content = "媽媽……嗚哇啊啊……",
  ui_story_5053_50530801_74_dialog_content = "這是……噩夢……",
  ui_story_5053_50530801_75_dialog_content = "小薇……做了場……噩夢……",
  ui_story_5053_50530801_76_dialog_content = "想哭……就哭吧……",
  ui_story_5053_50530801_77_dialog_content = "媽媽……在這裡……",
  ui_story_5053_50530801_78_dialog_content = "……",
  ui_story_5053_50530801_79_dialog_content = "好溫暖的懷抱……那首搖籃曲……",
  ui_story_5053_50530801_80_dialog_content = "真的是媽媽……",
  ui_story_5053_50530801_81_dialog_content = "媽媽……我好想妳……",
  ui_story_5053_50530801_82_dialog_content = "我也……想妳……",
  ui_story_5053_50530801_83_dialog_content = "（黑天使溫柔地安撫起蜜雅……？？）",
  ui_story_5053_50530801_84_dialog_content = "（她不是個沒有理性的怪物嗎？！不……如果那個約書亞說的全是謊話……）",
  ui_story_5053_50530801_85_dialog_content = "……蜜雅，妳還好嗎？站得起來嗎？",
  ui_story_5053_50530801_86_dialog_content = "PlayerName……抱歉，我剛剛沒控制住自己。",
  ui_story_5053_50530801_87_dialog_content = "你沒被我傷到吧……？",
  ui_story_5053_50530801_88_dialog_content = "怎麼會呢，我一點事都沒有。妳沒事就好。",
  ui_story_5053_50530801_89_dialog_content = "但這位「黑天使」到底是怎麼一回事？我已經完全搞糊塗了。",
  ui_story_5053_50530801_90_dialog_content = "她才是媽媽，我現在非常確定。",
  ui_story_5053_50530801_91_dialog_content = "她是約書亞夫人……？！",
  ui_story_5053_50530801_92_dialog_content = "我知道這有點難以理解，但是直覺告訴我，她才是真正的媽媽……",
  ui_story_5053_50530801_93_dialog_content = "另一個媽媽說，「黑天使」是缺乏理性的怪物，但她的懷抱卻是那麼溫柔。",
  ui_story_5053_50530801_94_dialog_content = "而宅邸裡的那個媽媽，我總覺得有些陌生……",
  ui_story_5053_50530801_95_dialog_content = "……不，我能理解，不如說這樣一來很多問題都有答案了。",
  ui_story_5053_50530801_96_dialog_content = "哎？PlayerName這話是什麼意思？",
  ui_story_5053_50530801_97_dialog_content = "一句話很難解釋清楚，但現在加晴有危險，我們必須盡快回去。",
  ui_story_5053_50530801_98_dialog_content = "詳細情況我路上再告訴妳！",
  ui_story_5053_50530801_99_dialog_content = "加晴？那應該不用擔心，凱萊布舅父也在她身邊，會保護她的。",
  ui_story_5053_50530801_100_dialog_content = "凱萊布在加晴身邊？",
  ui_story_5053_50530801_101_dialog_content = "是的，父親請舅父也一起留下來，一開始我也不明白是為什麼。",
  ui_story_5053_50530801_102_dialog_content = "不，即使凱萊布留下也可能沒有意義。",
  ui_story_5053_50530801_103_dialog_content = "宅邸中的那個「約書亞」心狠手辣，不擇手段想殺死我們所有人。",
  ui_story_5053_50530801_104_dialog_content = "什……你在說什麼？！",
  ui_story_5053_50530801_105_dialog_content = "蜜雅，這些事情已經不是第一次發生了！",
  ui_story_5053_50530801_106_dialog_content = "！！",
  ui_story_5053_50530801_107_dialog_content = "凱萊布……危險……",
  ui_story_5053_50530801_108_dialog_content = "凱……萊布……弟……弟……",
  ui_story_5053_50530801_109_dialog_content = "弟弟……危險……",
  ui_story_5053_50530801_110_dialog_content = "你的意思是，時間已經又回溯過一次了……？",
  ui_story_5053_50530801_111_dialog_content = "我們必須馬上回去，快去找父親！！",
  ui_story_5053_50530801_112_dialog_content = "父親！",
  ui_story_5053_50530801_113_dialog_content = "城主大人，我們必須回去救凱萊布和加晴！詳細情況我路上再和您解釋！",
  ui_story_5053_50530801_114_dialog_content = "舒……瓦茲……",
  ui_story_5053_50530801_115_dialog_content = "……看來事情比我想的還複雜。",
  ui_story_5053_50530801_116_dialog_content = "不過我暫時無法抽身了。",
  ui_story_5053_50530801_117_dialog_content = "這飛龍受到任何傷害都會快速癒合，就算是致命傷也不怕。",
  ui_story_5053_50530801_118_dialog_content = "這種不祥的特性稱為「不死性」。",
  ui_story_5053_50530801_119_dialog_content = "這種傳說中的特性，也就只可能在「永憶鏡晶」中的幻影身上出現了。",
  ui_story_5053_50530801_120_dialog_content = "怎麼會這樣......",
  ui_story_5053_50530801_121_dialog_content = "這恐怕也是「約書亞」夫人搞的鬼。城主大人，能麻煩您在這裡拖住飛龍嗎？",
  ui_story_5053_50530801_122_dialog_content = "「約書亞」……沒問題，宅邸那邊就交給你們了。",
  ui_story_5053_50530801_123_dialog_content = "薇羅妮卡，妳為什麼還沒有去避難？還有妳身邊那是……",
  ui_story_5053_50530801_124_dialog_content = "……",
  ui_story_5053_50530801_125_dialog_content = "父親……我有要緊事必須回宅邸一趟，希望您不要阻攔我。",
  ui_story_5053_50530801_126_dialog_content = "沒有什麼比當下的情況更加緊急。",
  ui_story_5053_50530801_127_dialog_content = "而且我也不允許妳和這些來歷不明的人混在一起。",
  ui_story_5053_50530801_128_dialog_content = "城主殿下，您已經和我這名來歷不明的老人並肩作戰許久。",
  ui_story_5053_50530801_129_dialog_content = "何必現在才開始在意這些呢。",
  ui_story_5053_50530801_130_dialog_content = "……",
  ui_story_5053_50530801_131_dialog_content = "不用擔心，我和PlayerName都是薇羅妮卡的夥伴，你的家人就交給我們保護吧。",
  ui_story_5053_50530801_132_dialog_content = "你身上還有保護白夜城所有人民的責任，你要保護所有人。",
  ui_story_5053_50530801_133_dialog_content = "那倒不必。白夜城中有善戰的「紅女士」，我的妻子也不是等閒之輩，不需要勞煩諸位。",
  ui_story_5053_50530801_134_dialog_content = "況且還有這個看起來像怪物一樣的東西，我並不信任牠。",
  ui_story_5053_50530801_135_dialog_content = "……",
  ui_story_5053_50530801_136_dialog_content = "那你可以放心，這位是我妻子。",
  ui_story_5053_50530801_137_dialog_content = "什……？！",
  ui_story_5053_50530801_138_dialog_content = "……！",
  ui_story_5053_50530801_139_dialog_content = "（父親，果然你也覺得她才是真正的媽媽！）",
  ui_story_5053_50530801_140_dialog_content = "咳，不得不說，你選伴侶的眼光還真是獨特。",
  ui_story_5053_50530801_141_dialog_content = "彼此彼此。",
  ui_story_5053_50530801_142_dialog_content = "快去吧，蜜雅、PlayerName。時間不多了。",
  ui_story_5053_50530801_143_dialog_content = "好！",
  ui_story_5053_50530801_144_dialog_content = "凱萊布……",
  ui_story_5053_50530801_145_dialog_content = "媽媽，妳也要來嗎？",
  ui_story_5053_50530801_146_dialog_content = "保護……凱萊布……",
  ui_story_5053_50530801_147_dialog_content = "嗯，我們一起保護舅父，走吧！",
  ui_story_5053_50530901_1_dialog_content = "凱萊布，外面怎麼樣了？",
  ui_story_5053_50530901_2_dialog_content = "剛才震耳欲聾的巨響，我總覺得不太妙。",
  ui_story_5053_50530901_3_dialog_content = "嗯，不知道為什麼，飛龍比預料的更早出現了。",
  ui_story_5053_50530901_4_dialog_content = "現在廣場那裡應該亂成一團了吧。",
  ui_story_5053_50530901_5_dialog_content = "如果是這樣的話，大家豈不是很危險？",
  ui_story_5053_50530901_6_dialog_content = "城主大人、蜜雅，還有下落不明的PlayerName……",
  ui_story_5053_50530901_7_dialog_content = "不用擔心，狄安理自有辦法應付這一切。",
  ui_story_5053_50530901_8_dialog_content = "至於宅邸這邊……不錯，你們也按時來了。",
  ui_story_5053_50530901_9_dialog_content = "……",
  ui_story_5053_50530901_10_dialog_content = "不愧是姐姐，一切都提前計畫好了。",
  ui_story_5053_50530901_11_dialog_content = "加晴，妳就別瞎操心了。",
  ui_story_5053_50530901_12_dialog_content = "好吧……",
  ui_story_5053_50530901_13_dialog_content = "說到這個，加晴，能麻煩妳把房間的門鎖上嗎？",
  ui_story_5053_50530901_14_dialog_content = "喔對！門還是鎖上比較安全，沒問題～",
  ui_story_5053_50530901_15_dialog_content = "凱萊布，我想問你一個問題。為什麼你會想要救我呢？",
  ui_story_5053_50530901_16_dialog_content = "嗯？妳是我的親姐姐，我救妳天經地義啊。",
  ui_story_5053_50530901_17_dialog_content = "……因為「親情」是嗎？",
  ui_story_5053_50530901_18_dialog_content = "那當然。對我來說，世上的所有東西都充滿了變數，但唯獨妳、我、父親……",
  ui_story_5053_50530901_19_dialog_content = "我們一家人的情感是不會變的。哪怕經過多少歲月，我都堅信不疑。",
  ui_story_5053_50530901_20_dialog_content = "是嗎。不論動機如何，至少拯救了我的軀體這件事，我得感謝你。",
  ui_story_5053_50530901_21_dialog_content = "做得好，凱萊布。",
  ui_story_5053_50530901_22_dialog_content = "（姐姐……）",
  ui_story_5053_50530901_23_dialog_content = "世界充滿了變數，但有的東西也許連時間也改變不了……",
  ui_story_5053_50530901_24_dialog_content = "十二年過去了，現在的白夜城又變成了何種模樣？",
  ui_story_5053_50530901_25_dialog_content = "還是老樣子。那些貴族蛀蟲依舊固步自封、冥頑不化。",
  ui_story_5053_50530901_26_dialog_content = "在他們的啃食下，所謂的白夜城也不過只是一副輝煌的空殼，從內而外地腐爛罷了。",
  ui_story_5053_50530901_27_dialog_content = "果然如此嗎……那麼，舒瓦茲家族呢？",
  ui_story_5053_50530901_28_dialog_content = "舒瓦茲？比白夜城還令人不齒。",
  ui_story_5053_50530901_29_dialog_content = "當年他信誓旦旦對妳許下那麼多承諾，到頭來有幾條能實現？",
  ui_story_5053_50530901_30_dialog_content = "還說什麼「徹底改變白夜城，把這裡變成最公正自由的地方」……",
  ui_story_5053_50530901_31_dialog_content = "現在光是對抗那些迂腐貴族就耗盡了他的全力，更別說改變什麼了。",
  ui_story_5053_50530901_32_dialog_content = "家庭也因為他的軟弱而四分五裂，讓姐姐，甚至蜜雅和卡蓮都受牽連。我看不起他。",
  ui_story_5053_50530901_33_dialog_content = "政治的事情我不是很懂，但是凱萊布，你的說法有點偏激呀。",
  ui_story_5053_50530901_34_dialog_content = "能一邊和各種煩人的貴族老頭周旋，一邊在民眾面前樹立偉大可靠的形象，這不是很厲害嗎？",
  ui_story_5053_50530901_35_dialog_content = "加晴，你們外人看到的始終是那個光鮮亮麗的外殼，實際又懂白夜城多少？",
  ui_story_5053_50530901_36_dialog_content = "但是就連伯利恆陛下也覺得……好啦好啦！我去找衛兵聊天行了吧！",
  ui_story_5053_50530901_37_dialog_content = "那，我呢？你覺得選擇了舒瓦茲的我很失敗嗎？",
  ui_story_5053_50530901_38_dialog_content = "姐、姐姐當然不失敗了！是舒瓦茲用花言巧語矇騙了妳，妳才是受害者！",
  ui_story_5053_50530901_39_dialog_content = "但如果……我只是說如果，妳想離開他的話，家裡大門永遠為妳敞開。",
  ui_story_5053_50530901_40_dialog_content = "甚至即使妳厭倦了白夜城，我們也可以到別的地方去生活！",
  ui_story_5053_50530901_41_dialog_content = "沒有那個必要，凱萊布。我無法放任白夜城腐朽下去，今生一定會改變這個地方。",
  ui_story_5053_50530901_42_dialog_content = "……",
  ui_story_5053_50530901_43_dialog_content = "但是你說得對，舒瓦茲無可救藥，我已經對他失望透頂了。",
  ui_story_5053_50530901_44_dialog_content = "姐姐……！妳終於打算和他離婚了嗎？！",
  ui_story_5053_50530901_45_dialog_content = "凱萊布，像你這樣敢公然反對舒瓦茲的人已經很少了。",
  ui_story_5053_50530901_46_dialog_content = "看來我和那個男人對你的教育沒有白費。",
  ui_story_5053_50530901_47_dialog_content = "那個男人？難道妳是說父親？為什麼突然用這麼生疏的叫法稱呼父親……",
  ui_story_5053_50530901_48_dialog_content = "也是時候告訴你一切的真相了。衛兵們，動手。",
  ui_story_5053_50530901_49_dialog_content = "……",
  ui_story_5053_50530901_50_dialog_content = "唔啊！！好、好痛，你們這是幹什麼呀！",
  ui_story_5053_50530901_51_dialog_content = "什麼真相？……姐姐妳要對加晴做什麼？",
  ui_story_5053_50530901_52_dialog_content = "凱萊布，<color=#FFB400>我不是你的親生姐姐</color>。",
  ui_story_5053_50530901_53_dialog_content = "啊……？",
  ui_story_5053_50530901_54_dialog_content = "多年前，我的家族因為不贊成舒瓦茲家族的統治，被前任城主，也就是狄安理的父親肅清。",
  ui_story_5053_50530901_55_dialog_content = "同時受害的還有其他數個家族，只有年幼的我和少數人倖存。",
  ui_story_5053_50530901_56_dialog_content = "所有人都恨透了舒瓦茲一族，團結一心誓要為親人復仇。",
  ui_story_5053_50530901_57_dialog_content = "於是我便進入一名遺族的家中，頂替他們被舒瓦茲家族所害的女兒進入高庭。",
  ui_story_5053_50530901_58_dialog_content = "等等……遺族的家中……頂替<color=#FFB400>其被舒瓦茲一族所害的女兒</color>…………",
  ui_story_5053_50530901_59_dialog_content = "沒錯，那就是你的姐姐「<color=#FFB400>約書亞</color>」。你的親生姐姐和母親早就遇害了。",
  ui_story_5053_50530901_60_dialog_content = "她們甚至對舒瓦茲家族毫無意見，只是當天不巧去了那個被清算的宅邸探望朋友而已。",
  ui_story_5053_50530901_61_dialog_content = "……父親他……知道這件事嗎……？",
  ui_story_5053_50530901_62_dialog_content = "當然了，主動提出這個偷天換日計畫的人就是他。",
  ui_story_5053_50530901_63_dialog_content = "開、開玩笑吧，那個老實憨厚的父親怎麼可能……",
  ui_story_5053_50530901_64_dialog_content = "這就是仇恨的力量，凱萊布。",
  ui_story_5053_50530901_65_dialog_content = "支撐我們一同努力，養育你長大的才不是什麼「親情」，是復仇的渴望。",
  ui_story_5053_50530901_66_dialog_content = "你父親因為暗殺計畫失敗而主動選擇自盡，是為了保護你和我，保護復仇的火苗。",
  ui_story_5053_50530901_67_dialog_content = "當年我看在狄安理再三祈求的份上，才給了他一次改變舒瓦茲家族的機會。",
  ui_story_5053_50530901_68_dialog_content = "並扶持他，讓他競選成功，獲任為新一任城主。",
  ui_story_5053_50530901_69_dialog_content = "——畢竟我不會像他父親那樣，做一個濫殺無辜的劊子手。",
  ui_story_5053_50530901_70_dialog_content = "但我錯了。這一切都因為狄安理的無能變得毫無意義。該讓舒瓦茲家族嘗嘗我們的怒火了。",
  ui_story_5053_50530901_71_dialog_content = "凱萊布，幹掉<color=#FFB400>加晴</color>。",
  ui_story_5053_50530901_72_dialog_content = "……什麼？姐姐妳說……什麼？",
  ui_story_5053_50530901_73_dialog_content = "我需要外來者的光能才能離開這裡。我在外面還有未盡的使命。",
  ui_story_5053_50530901_74_dialog_content = "不……姐姐，再怎麼說，加晴跟這一切毫無關係啊！妳不是也不想濫殺無辜嗎？！",
  ui_story_5053_50530901_75_dialog_content = "這是「必要的犧牲」。",
  ui_story_5053_50530901_76_dialog_content = "喂……妳瘋了吧！那個溫柔的約書亞夫人去哪裡了啊？！",
  ui_story_5053_50530901_77_dialog_content = "我還想問呢……不是親人？沒有親情？開什麼玩笑……加晴，眼前的這個人真的不是幻影嗎？！",
  ui_story_5053_50530901_78_dialog_content = "不是幻影！我也沒對她用過改變外貌的占卜術！",
  ui_story_5053_50530901_79_dialog_content = "凱萊布，你打算在知道真相後繼續視而不見……辜負你父親、母親以及姐姐的犧牲嗎？",
  ui_story_5053_50530901_80_dialog_content = "…………",
  ui_story_5053_50530901_81_dialog_content = "算了，看來我們對你的教育還不夠徹底，加晴就由我來處理。",
  ui_story_5053_50530901_82_dialog_content = "之後你必須親手解決舒瓦茲和其他人，來表明你的決心。這是我給你最後的機會。",
  ui_story_5053_50530901_83_dialog_content = "妳還要除掉大家嗎？！可惡，放開我！妳休想！！",
  ui_story_5053_50530901_84_dialog_content = "要恨就恨舒瓦茲吧。再見了，北境使者。",
  ui_story_5053_50530901_85_dialog_content = "<color=#e8d9bb>唰——</color>",
  ui_story_5053_50530901_86_dialog_content = "……姐姐，妳說得對。雖然妳變得這麼陌生，但我本能知道，妳就是我最愛的姐姐。",
  ui_story_5053_50530901_87_dialog_content = "所以我一定要阻止妳！我絕不會讓妳做出會令自己後悔的事！",
  ui_story_5053_50530901_88_dialog_content = "後悔？扮演溫柔的姐姐，替你那膽小的父親照顧你，就是為了讓你能成為出色的繼承人。",
  ui_story_5053_50530901_89_dialog_content = "唔……！",
  ui_story_5053_50530901_90_dialog_content = "但你卻背叛了我……你也背叛了我！！",
  ui_story_5053_50530901_91_dialog_content = "不……我從不會背叛妳！",
  ui_story_5053_50530901_92_dialog_content = "嘖，手好麻……你居然會繳械的技巧，就知道耍小聰明！！",
  ui_story_5053_50530901_93_dialog_content = "既然如此，我也告訴妳一個真相吧。我總說舒瓦茲配不上妳，但其實我一直都明白……",
  ui_story_5053_50530901_94_dialog_content = "我只是單純討厭妳丈夫！討厭妳的孩子們！因為他們奪走了我僅剩的親人！",
  ui_story_5053_50530901_95_dialog_content = "哪怕妳和我沒有血源關係……我也深愛把我撫養長大的妳！",
  ui_story_5053_50530901_96_dialog_content = "再有天賦才智，你也不過是個離不開姐姐的巨嬰罷了！別礙事！",
  ui_story_5053_50530901_97_dialog_content = "沒錯！我就是長不大，妳想笑就笑吧！",
  ui_story_5053_50530901_98_dialog_content = "但是……就連我也知道妳有多愛孩子和丈夫，這是我再怎麼掙扎都無法改變的事實！",
  ui_story_5053_50530901_99_dialog_content = "都說了那只是偽裝而已！！",
  ui_story_5053_50530901_100_dialog_content = "呃……抱歉姐姐，這次我沒法相信妳。",
  ui_story_5053_50530901_101_dialog_content = "為了不讓妳難過，我一定會替妳守護好妳重要的家人，哪怕要拼上性命！",
  ui_story_5053_50530901_102_dialog_content = "好啊，那我就收下你的性命和光能吧。",
  ui_story_5053_50530901_103_dialog_content = "呃……？",
  ui_story_5053_50530901_104_dialog_content = "不……不要啊！凱萊布！！！",
  ui_story_5053_50530901_105_dialog_content = "……這可是你自己選的。",
  ui_story_5053_50530901_130_dialog_content = "凱萊布！！",
  ui_story_5053_50530901_131_dialog_content = "<color=#e8d9bb>啪——</color>",
  ui_story_5053_50530901_132_dialog_content = "<size=45>啊啊啊————！</size>",
  ui_story_5053_50530901_133_dialog_content = "唔！！",
  ui_story_5053_50530901_134_dialog_content = "呃——！",
  ui_story_5053_50530901_135_dialog_content = "？！",
  ui_story_5053_50530901_136_dialog_content = "可惡，你這噁心的東西怎麼在這個時候……！嘖！",
  ui_story_5053_50530901_138_dialog_content = "凱萊布撐住啊！凱萊布！！",
  ui_story_5053_50530901_139_dialog_content = "凱……萊……布……！！",
  ui_story_5053_50530901_140_dialog_content = "呵……明明能一劍了結我，果然妳還是心軟啊……",
  ui_story_5053_50530901_141_dialog_content = "糟糕……傷口太深了，血止不住……",
  ui_story_5053_50530901_143_dialog_content = "好黑……什麼都看不見了。",
  ui_story_5053_50530901_145_dialog_content = "不......不......",
  ui_story_5053_50530901_146_dialog_content = "姐姐……是妳…………？",
  ui_story_5053_50530901_147_dialog_content = "凱……萊……布……",
  ui_story_5053_50530901_148_dialog_content = "姐姐……在……這裡……",
  ui_story_5053_50530901_149_dialog_content = "是……是嗎……咳咳！！！",
  ui_story_5053_50530901_150_dialog_content = "姐姐……妳放下武器了……？",
  ui_story_5053_50530901_151_dialog_content = "太好……了……",
  ui_story_5053_50530901_152_dialog_content = "……",
  ui_story_5053_50530901_153_dialog_content = "凱萊布！！凱萊布！！",
  ui_story_5053_50530901_155_dialog_content = "凱萊……布……！！！！",
  ui_story_5053_50530901_156_dialog_content = "不……不……！！",
  ui_story_5053_50530901_157_dialog_content = "<size=50>嗚啊啊啊啊！！！！！！</size>",
  ui_story_5053_50531001_1_dialog_content = "呼……呼……",
  ui_story_5053_50531001_2_dialog_content = "PlayerName，還好嗎？如果走不動了就休息一下。",
  ui_story_5053_50531001_3_dialog_content = "我沒事，只是剛剛追「黑天使」追得太急了，她飛得也太快了吧？！",
  ui_story_5053_50531001_4_dialog_content = "一開始還和我們走在一起，突然就像感覺到什麼一樣飛起來了……",
  ui_story_5053_50531001_5_dialog_content = "其實她之前去救妳也是這樣的狀態，我很擔心加晴他們的安危。",
  ui_story_5053_50531001_6_dialog_content = "唔，馬上就到了！希望他們平安無事……",
  ui_story_5053_50531001_7_dialog_content = "蜜雅，妳真的確定加晴完全記不得第二次回溯前的事情了嗎？",
  ui_story_5053_50531001_8_dialog_content = "嗯，是的。我們和加晴都不記得了……大家都信了那個「媽媽」說的話。",
  ui_story_5053_50531001_9_dialog_content = "坦白說，就算聽了PlayerName你說的話，我還是有點無法相信……",
  ui_story_5053_50531001_10_dialog_content = "我一定要親眼確認真相……！",
  ui_story_5053_50531001_11_dialog_content = "（連加晴都不記得了，為什麼我還記得？這到底是……）",
  ui_story_5053_50531001_12_dialog_content = "宅邸裡的氣氛有些奇怪，守門的衛兵去哪裡了？",
  ui_story_5053_50531001_13_dialog_content = "地面在微微震動……蜜雅小心！！",
  ui_story_5053_50531001_14_dialog_content = "？！",
  ui_story_5053_50531001_15_dialog_content = "啊——！入侵者，反抗者，殺——！",
  ui_story_5053_50531001_16_dialog_content = "唔啊啊——！！",
  ui_story_5053_50531001_17_dialog_content = "殺——！殺——！殺——！",
  ui_story_5053_50531001_18_dialog_content = "又是那些發瘋的衛兵！",
  ui_story_5053_50531001_19_dialog_content = "咿呀！！！！救命啊！！",
  ui_story_5053_50531001_20_dialog_content = "那是……加晴？！",
  ui_story_5053_50531001_21_dialog_content = "有衛兵在追她！蜜雅，我們快擊退這些人！",
  ui_story_5053_50531001_22_dialog_content = "人太多了！希頗……",
  ui_story_5053_50531001_23_dialog_content = "薇羅妮卡殿下，快讓開——！",
  ui_story_5053_50531001_24_dialog_content = "？ ！ ！",
  ui_story_5053_50531001_25_dialog_content = "<color=#e8d9bb>匡——！</color>",
  ui_story_5053_50531001_26_dialog_content = "唔……！！",
  ui_story_5053_50531001_27_dialog_content = "啊啊啊啊！！",
  ui_story_5053_50531001_28_dialog_content = "（白蘭女士？！好強！幾乎像是在跳舞一樣解決了那些衛兵！）",
  ui_story_5053_50531001_29_dialog_content = "紅女士！當心身後！",
  ui_story_5053_50531001_30_dialog_content = "請不必擔心，薇羅妮卡殿下。",
  ui_story_5053_50531001_31_dialog_content = "這是「守夜人」的職責，白夜城不是任人放肆踐踏之地。",
  ui_story_5053_50531001_32_dialog_content = "在我眼皮下，不允許有人破壞白夜城的秩序。",
  ui_story_5053_50531001_33_dialog_content = "「白夜至上——」",
  ui_story_5053_50531001_34_dialog_content = "嗚——！！",
  ui_story_5053_50531001_35_dialog_content = "咿呀！！",
  ui_story_5053_50531001_36_dialog_content = "薇羅妮卡殿下、加晴小姐，妳們都沒受傷吧？",
  ui_story_5053_50531001_37_dialog_content = "沒……我還好。",
  ui_story_5053_50531001_38_dialog_content = "幸虧妳來了，不然我們很難對付這麼多人。",
  ui_story_5053_50531001_39_dialog_content = "殿下，到底是怎麼回事？這些人的樣子不像是反叛軍。",
  ui_story_5053_50531001_40_dialog_content = "不不，不是反叛軍，現在大事不妙，這些人全都是約書亞……",
  ui_story_5053_50531001_41_dialog_content = "哎呀，真是做賊喊捉賊。紅女士，妳來得正好。",
  ui_story_5053_50531001_42_dialog_content = "這些不速之客都是PlayerName和加晴這些人一手謀劃的，他們還花言巧語蠱惑了小薇。",
  ui_story_5053_50531001_43_dialog_content = "薇羅妮卡已經被他們哄得團團轉，真是無可救藥。身為母親我很失望。",
  ui_story_5053_50531001_44_dialog_content = "已經沒有辦法了，紅女士，我命令妳，剷除他們三人。",
  ui_story_5053_50531001_45_dialog_content = "……",
  ui_story_5053_50531001_46_dialog_content = "媽媽，你在說什麼？！果然如PlayerName所說……",
  ui_story_5053_50531001_47_dialog_content = "紅女士，妳眼前的「約書亞」不是真正的「約書亞」！雖然我自己也還沒弄明白……",
  ui_story_5053_50531001_48_dialog_content = "但是請相信我，妳眼前的人，不是妳認識的那個約書亞夫人！",
  ui_story_5053_50531001_49_dialog_content = "我以舒瓦茲家族的榮耀擔保，PlayerName說的是真的。",
  ui_story_5053_50531001_50_dialog_content = "妳最瞭解媽媽，她怎麼可能說出這種話？！",
  ui_story_5053_50531001_51_dialog_content = "……",
  ui_story_5053_50531001_52_dialog_content = "妳在猶豫什麼？忘記我以前是怎麼教導妳的了嗎？",
  ui_story_5053_50531001_53_dialog_content = "殺手，是主人理想的認同者。為了貫徹理想和大義，可以付出一切代價。",
  ui_story_5053_50531001_54_dialog_content = "為了白夜的未來，多餘的情感不過是執行路上的障礙。妳不會留戀這些東西的，對吧？",
  ui_story_5053_50531001_55_dialog_content = "（什麼，白蘭女士是約書亞的學生？）",
  ui_story_5053_50531001_56_dialog_content = "……是啊，老師，一切都為了「白夜城的未來」。",
  ui_story_5053_50531001_57_dialog_content = "什麼……？！",
  ui_story_5053_50531001_58_dialog_content = "為了實現那個所有孩子都可以平等歡笑的世界，我會剷除一切障礙，哪怕那個障礙是您。",
  ui_story_5053_50531001_59_dialog_content = "……",
  ui_story_5053_50531001_60_dialog_content = "不愧是我的學生，竟敢對我拔刀相向，真是勇氣可嘉。",
  ui_story_5053_50531001_61_dialog_content = "好啊，那妳今天就和他們一起葬身於此吧！",
  ui_story_5053_50531001_62_dialog_content = "<color=#e8d9bb>當——</color>",
  ui_story_5053_50531001_63_dialog_content = "呃——！",
  ui_story_5053_50531001_64_dialog_content = "（糟糕，老師的劍太快了……！）",
  ui_story_5053_50531001_65_dialog_content = "紅女士？！",
  ui_story_5053_50531001_66_dialog_content = "PlayerName，帶薇羅妮卡殿下和加晴小姐快逃！！",
  ui_story_5053_50531001_67_dialog_content = "我也沒有信心能打贏，你們快離開！！",
  ui_story_5053_50531001_68_dialog_content = "可......可是……",
  ui_story_5053_50531001_69_dialog_content = "多說無益，現在你們的安全最重要！快走！",
  ui_story_5053_50531001_70_dialog_content = "……沒辦法了！蜜雅、加晴，快逃！！",
  ui_story_5053_50531001_71_dialog_content = "（紅女士，要平安無事啊……！）",
  ui_story_5053_50531002_1_dialog_content = "嘿咻！還有其他可以堵門的東西嗎？",
  ui_story_5053_50531002_2_dialog_content = "沒有了，剛剛的椅子就是最後一個了。",
  ui_story_5053_50531002_3_dialog_content = "嗯～太奇怪了！太奇怪了！！",
  ui_story_5053_50531002_4_dialog_content = "如果PlayerName說的沒錯，時間已經又回溯過一次。",
  ui_story_5053_50531002_5_dialog_content = "第一次回溯的時候大家都牽著手，我的操作也完全正確，所以我們保留了記憶。",
  ui_story_5053_50531002_6_dialog_content = "第二次我也在，但我的記憶卻也沒保留下來……",
  ui_story_5053_50531002_7_dialog_content = "對啊，這是什麼原因呢？",
  ui_story_5053_50531002_8_dialog_content = "……我好像知道原因了。",
  ui_story_5053_50531002_9_dialog_content = "「永憶鏡晶」裡的光能已經所剩無幾了！",
  ui_story_5053_50531002_10_dialog_content = "哎？ ！",
  ui_story_5053_50531002_11_dialog_content = "唔……看來我們和敵人都做得太過火了。",
  ui_story_5053_50531002_12_dialog_content = "這點光能已經不足以讓「永憶鏡晶」維持所有功能了。",
  ui_story_5053_50531002_13_dialog_content = "但是為何只有PlayerName還記得這一切呢？",
  ui_story_5053_50531002_14_dialog_content = "還有兩個約書亞，我越來越想不通了。",
  ui_story_5053_50531002_15_dialog_content = "難道宅邸裡的「約書亞」真的是別人假扮的嗎？",
  ui_story_5053_50531002_16_dialog_content = "我現在也完全搞不懂。但父親還在廣場和飛龍纏鬥，我很擔心……",
  ui_story_5053_50531002_17_dialog_content = "我們別無選擇了，重新回溯一次時間吧。",
  ui_story_5053_50531002_18_dialog_content = "不行不行！如果我們都沒能保留記憶，只有你一個人面對約書亞太危險了！",
  ui_story_5053_50531002_19_dialog_content = "是啊，那個「媽媽」的實力，你一個人應付不來。",
  ui_story_5053_50531002_20_dialog_content = "我們在門口堵了這麼多東西，應該能爭取一點時間，讓我來查查書……",
  ui_story_5053_50531002_21_dialog_content = "「北境占卜術起源於古代光靈的聚落」，古代光靈……古代光靈……",
  ui_story_5053_50531002_22_dialog_content = "啊！這套占卜術是光靈製作的，也是給光靈使用的！但PlayerName是空裔啊！",
  ui_story_5053_50531002_23_dialog_content = "或許是因為種族不同導致的差異？畢竟書裡並沒有任何非光靈的使用記載。",
  ui_story_5053_50531002_24_dialog_content = "原來如此……我的感應能力被大幅削弱，是不是也和這個有關呢？",
  ui_story_5053_50531002_25_dialog_content = "嗯～PlayerName，你玩過啟光的遊戲機嗎？",
  ui_story_5053_50531002_26_dialog_content = "重開遊戲的時候，「角色」會失去記憶，但「玩家」不會。",
  ui_story_5053_50531002_27_dialog_content = "如果真是這樣的話，那我就是「玩家」？",
  ui_story_5053_50531002_28_dialog_content = "沒錯！你是那個不受規則限制的玩家！",
  ui_story_5053_50531002_29_dialog_content = "正因如此，在你再次回溯之前，我們應該縝密計畫好你應該怎麼行動。",
  ui_story_5053_50531002_30_dialog_content = "對，如果你又毫無準備就進入下一次時間重設，那太危險了。",
  ui_story_5053_50531002_31_dialog_content = "說得對……讓我們從長計議吧。",
  ui_story_5053_50531002_32_dialog_content = "眼前最大的危險來自於「約書亞」。",
  ui_story_5053_50531002_33_dialog_content = "可是兩個約書亞到底是怎麼回事，我現在也沒搞明白。",
  ui_story_5053_50531002_34_dialog_content = "兩個約書亞叫起來太混亂了，既然其中一個叫「黑天使」……",
  ui_story_5053_50531002_35_dialog_content = "另一個就叫「白惡魔」好了！",
  ui_story_5053_50531002_37_dialog_content = "「白惡魔」……雖然我不想這麼稱呼媽媽，但這個稱呼的確很適合那樣的她。",
  ui_story_5053_50531002_38_dialog_content = "從「白惡魔」的舉手投足還有目前已知的情報來看，她並不像是冒牌貨。",
  ui_story_5053_50531002_39_dialog_content = "「種子」會使植入者產生分裂的人格……我或許能從自己的角度理解她。",
  ui_story_5053_50531002_40_dialog_content = "就好像我和芭芭雅嘎，只是一心兩面，我們兩人並不能分出誰好誰壞。",
  ui_story_5053_50531002_41_dialog_content = "即使她偶爾會有些極端，但她並不壞，PlayerName是知道的。",
  ui_story_5053_50531002_42_dialog_content = "「黑天使」和「白惡魔」有沒有可能也一樣？",
  ui_story_5053_50531002_43_dialog_content = "好比說「黑天使」雖然行為怪異，但也在廣場救了我們。",
  ui_story_5053_50531002_44_dialog_content = "或許她也只是在某些地方有些失控而已。",
  ui_story_5053_50531002_45_dialog_content = "唔，就算「黑天使」類似芭芭雅嘎，但「白惡魔」也和蜜雅妳不一樣啊。",
  ui_story_5053_50531002_46_dialog_content = "她完全就是個沒有感情的冷酷殺手，難道約書亞夫人有這樣的一面？",
  ui_story_5053_50531002_47_dialog_content = "我也很困惑，媽媽一直是溫暖善良的人，從未有過這樣的一面啊……",
  ui_story_5053_50531002_48_dialog_content = "呃，關於這一點，我要很煞風景地插句話。",
  ui_story_5053_50531002_49_dialog_content = "約書亞夫人自己親口承認過，她確實曾經是個冷面殺手……",
  ui_story_5053_50531002_50_dialog_content = "多年前，我的家族因為不贊成舒瓦茲家族的統治，被前任城主，也就是狄安理的父親肅清。",
  ui_story_5053_50531002_51_dialog_content = "同時受害的還有其他數個家族，只有年幼的我和少數人倖存。",
  ui_story_5053_50531002_52_dialog_content = "所有人都恨透了舒瓦茲一族，團結一心誓要為親人復仇。",
  ui_story_5053_50531002_53_dialog_content = "於是我便進入一名遺族的家中，頂替他們被舒瓦茲家族所害的女兒進入高庭。",
  ui_story_5053_50531002_54_dialog_content = "什……？！怎麼可能有這種事！她、她可是城主夫人啊！",
  ui_story_5053_50531002_55_dialog_content = "這說不定又是她的謊言呢！",
  ui_story_5053_50531002_56_dialog_content = "我也很難相信就是了……",
  ui_story_5053_50531002_57_dialog_content = "……",
  ui_story_5053_50531002_58_dialog_content = "蜜雅，你也不信吧？！",
  ui_story_5053_50531002_59_dialog_content = "不。其實我覺得這樣的話，有些事情就說得通了。",
  ui_story_5053_50531002_60_dialog_content = "媽媽是個非常厲害，甚至可以說偉大的人。",
  ui_story_5053_50531002_61_dialog_content = "她在白夜城城主夫人這個位置上，還能保持著初心、善良、理智的思維……",
  ui_story_5053_50531002_62_dialog_content = "對內照顧著父親和我們的生活，對外又要展現出城主夫人強大堅定的意志。",
  ui_story_5053_50531002_63_dialog_content = "而她從不貪戀任何名譽或財富。在很多需要抉擇的場合，她永遠選擇犧牲自己。",
  ui_story_5053_50531002_64_dialog_content = "這不是普通富家千金能做到的事。",
  ui_story_5053_50531002_65_dialog_content = "悲痛的過往經歷，長年累月的犧牲和壓抑自己的需求，也不被理解……",
  ui_story_5053_50531002_66_dialog_content = "媽媽的痛苦，比我要痛成千上萬倍吧。",
  ui_story_5053_50531002_67_dialog_content = "所以，她心中如果住著一個充滿怨恨的「白惡魔」，我也能理解。",
  ui_story_5053_50531002_68_dialog_content = "原來是這樣……",
  ui_story_5053_50531002_69_dialog_content = "約書亞夫人好厲害……但也好可憐啊。",
  ui_story_5053_50531002_70_dialog_content = "不過，如果這個推論沒錯，為什麼芭芭雅嘎就沒從我的身體裡分裂出來呢？",
  ui_story_5053_50531002_71_dialog_content = "對了，這就是妳和約書亞夫人不同之處啊。",
  ui_story_5053_50531002_72_dialog_content = "蜜雅和芭芭雅嘎是朋友，她總是在保護你。",
  ui_story_5053_50531002_73_dialog_content = "或許她就是不希望你在這個世界裡分裂，才故意不出現。",
  ui_story_5053_50531002_74_dialog_content = "約書亞的情況則相反，她的兩面互相對立。",
  ui_story_5053_50531002_75_dialog_content = "原、原來是這樣嗎，那太好了……我還以為是我擅自換了身裙子，惹她生氣了呢。",
  ui_story_5053_50531002_76_dialog_content = "芭芭雅嘎這麼貼心，我回去要好好感謝她……",
  ui_story_5053_50531002_77_dialog_content = "總之根據「白惡魔」剛剛說出的真相來看。",
  ui_story_5053_50531002_78_dialog_content = "我們如果想離開，又不傷害任何人的話，就只能把她們兩個一起帶出去了。",
  ui_story_5053_50531002_79_dialog_content = "「白惡魔」這次應該沒有撒謊了吧……？",
  ui_story_5053_50531002_80_dialog_content = "我覺得沒有，畢竟這個說法和她上次回溯前的行動邏輯對得上。",
  ui_story_5053_50531002_81_dialog_content = "只是我們還得提防她有沒有藏起來的底牌……",
  ui_story_5053_50531002_82_dialog_content = "……",
  ui_story_5053_50531002_83_dialog_content = "蜜雅？",
  ui_story_5053_50531002_84_dialog_content = "我在想這樣的媽媽就算出去了，在現實裡會是什麼狀態呢……",
  ui_story_5053_50531002_85_dialog_content = "會不會繼續感到生不如死，還是會變成暗鬼……？",
  ui_story_5053_50531002_86_dialog_content = "這……只能往樂觀的方向去想了。",
  ui_story_5053_50531002_87_dialog_content = "至少現在城主大人、凱萊布，還有我和加晴都在。",
  ui_story_5053_50531002_88_dialog_content = "大家群策群力，情況一定會比之前更好。",
  ui_story_5053_50531002_89_dialog_content = "但這一切都要從出去開始！",
  ui_story_5053_50531002_90_dialog_content = "……嗯！你說得對。",
  ui_story_5053_50531002_91_dialog_content = "但是要同時帶走兩個人可不容易，「白惡魔」不可能乖乖聽話。",
  ui_story_5053_50531002_92_dialog_content = "她還說另一個自己很噁心，不可能和她合而為一……",
  ui_story_5053_50531002_93_dialog_content = "是啊，所以她打算殺死我們所有人。",
  ui_story_5053_50531002_94_dialog_content = "眼下最好的方法或許只有動用武力，強行把她帶出去這條路了。",
  ui_story_5053_50531002_95_dialog_content = "但是那些飛龍和瘋狂的士兵會成為我們的阻礙……",
  ui_story_5053_50531002_96_dialog_content = "加晴，妳知道這些異變都是怎麼回事嗎？",
  ui_story_5053_50531002_97_dialog_content = "我看看……有了，「『永憶鏡晶』的啟動者可以對內部進行有限度的干涉」。",
  ui_story_5053_50531002_98_dialog_content = "媽媽真是的，怎麼寫得這麼模糊！",
  ui_story_5053_50531002_99_dialog_content = "這種時候，就只能靠我腦袋裡的知識了！我想想……",
  ui_story_5053_50531002_100_dialog_content = "「永憶鏡晶」是靠<color=#FFB400>鏡湖之水</color>和<color=#FFB400>啟動者的光能</color>驅動來構成內部世界的。",
  ui_story_5053_50531002_101_dialog_content = "<color=#FFB400>啟動者的光能</color>……也就是約書亞的光能啊！這一切的幻影都是約書亞光能的產物。",
  ui_story_5053_50531002_102_dialog_content = "她之前不是提到力量被分走之類的？！",
  ui_story_5053_50531002_103_dialog_content = "是的……",
  ui_story_5053_50531002_104_dialog_content = "她還說過，吸收了大家的光能讓她變得更強大了。",
  ui_story_5053_50531002_105_dialog_content = "沒錯！就是這樣！",
  ui_story_5053_50531002_106_dialog_content = "「白惡魔」的力量被「黑天使」分走了一半。",
  ui_story_5053_50531002_107_dialog_content = "而剩下的一半，她或許並沒有失去，而是拿去支配「永憶鏡晶」中的幻影了！",
  ui_story_5053_50531002_108_dialog_content = "畢竟那些幻影本質上也是約書亞光能的產物。",
  ui_story_5053_50531002_109_dialog_content = "她可以靠自己的光能去干涉……或說「污染」那些幻影！",
  ui_story_5053_50531002_110_dialog_content = "這麼一看，「白惡魔」向我們撒的謊可真不少耶？！她好會騙人啊！",
  ui_story_5053_50531002_111_dialog_content = "這麼離譜的事情也做得到嗎？！那外面的紅女士……！",
  ui_story_5053_50531002_112_dialog_content = "……或許也凶多吉少了吧。",
  ui_story_5053_50531002_113_dialog_content = "好恐怖，怎麼會有這麼心思縝密還心狠手辣的人……",
  ui_story_5053_50531002_114_dialog_content = "媽媽從未讓我感受過恐懼，如果那份溫柔從媽媽身上剝離開來……",
  ui_story_5053_50531002_115_dialog_content = "媽媽就會變成這樣可怕的人嗎？",
  ui_story_5053_50531002_116_dialog_content = "飛龍、發瘋的人群都是「白惡魔」的棋子，除了扳倒牠們，削弱白惡魔以外。",
  ui_story_5053_50531002_117_dialog_content = "有什麼讓我們獲得優勢的方法呢……對了。",
  ui_story_5053_50531002_118_dialog_content = "這次「黑天使」展現出對城主以外的家人的善意，而且「白惡魔」也殺不死她。",
  ui_story_5053_50531002_119_dialog_content = "如果能說服「黑天使」和我們站在同一陣線，勝算應該會大很多。",
  ui_story_5053_50531002_120_dialog_content = "你的想法蠻大膽的嘛！我喜歡你的行事風格喔～",
  ui_story_5053_50531002_121_dialog_content = "但是PlayerName，有件事我必須提醒你。",
  ui_story_5053_50531002_122_dialog_content = "「永憶鏡晶」的光能，只夠進行最後一次的回溯了。",
  ui_story_5053_50531002_123_dialog_content = "所以這次沒有別的選擇，你一定要成功！",
  ui_story_5053_50531002_124_dialog_content = "只、只能成功……好……",
  ui_story_5053_50531002_125_dialog_content = "PlayerName，如果回溯後你躲開那些追兵，直接當面拆穿「白惡魔」呢？",
  ui_story_5053_50531002_126_dialog_content = "哇……沒想到蜜雅比PlayerName還大膽，我對蜜雅要改觀囉。",
  ui_story_5053_50531002_127_dialog_content = "是......是嗎？",
  ui_story_5053_50531002_128_dialog_content = "嗯，我也覺得風險太大了。",
  ui_story_5053_50531002_129_dialog_content = "我沒有自保的能力，「白惡魔」想要消滅我易如反掌。",
  ui_story_5053_50531002_130_dialog_content = "而且你們也都沒有記憶，這些爆炸性的資訊。大家很難一下就接受。",
  ui_story_5053_50531002_131_dialog_content = "的確……尤其是舅父，他肯定不會輕易相信這些事情的。",
  ui_story_5053_50531002_132_dialog_content = "不過說到這個，我覺得PlayerName也不用太擔心我們。",
  ui_story_5053_50531002_133_dialog_content = "父親他很敏銳，這次在第一次和「白惡魔」交談的時候他就有些懷疑了。",
  ui_story_5053_50531002_134_dialog_content = "他要舅父留下來盯著「白惡魔」，也是為了讓舅父親眼看到真相吧……",
  ui_story_5053_50531002_135_dialog_content = "所以，你只要專注在「黑天使」身上就好。",
  ui_story_5053_50531002_136_dialog_content = "不愧是城主大人……",
  ui_story_5053_50531002_137_dialog_content = "<color=#e8d9bb>咚咚咚咚！！！！！！</color>",
  ui_story_5053_50531002_138_dialog_content = "嗚啊！什麼聲音？！",
  ui_story_5053_50531002_139_dialog_content = "糟糕，那些衛兵追過來了！",
  ui_story_5053_50531002_140_dialog_content = "我去頂住門，加晴你們趁機去回溯時……",
  ui_story_5053_50531002_141_dialog_content = "<color=#e8d9bb>砰！！！</color>",
  ui_story_5053_50531002_142_dialog_content = "蜜雅！小心！",
  ui_story_5053_50531002_143_dialog_content = "那是？！",
  ui_story_5053_50531002_144_dialog_content = "……",
  ui_story_5053_50531002_145_dialog_content = "紅女士，妳……？！",
  ui_story_5053_50531002_146_dialog_content = "蜜雅，快退後！",
  ui_story_5053_50531002_147_dialog_content = "……不。",
  ui_story_5053_50531002_148_dialog_content = "紅女士……一定很痛苦，就像小卡蓮那樣，靠自己最後的理智掙扎。",
  ui_story_5053_50531002_149_dialog_content = "……這次我不會再迷茫了。卡蓮的痛苦，我不會再讓妳重蹈覆轍。",
  ui_story_5053_50531002_150_dialog_content = "我來親手讓妳解脫吧。",
  ui_story_5053_50531002_151_dialog_content = "來吧！",
  ui_story_5053_50531002_152_dialog_content = "——！",
  ui_story_5053_50531002_153_dialog_content = "蜜雅……",
  ui_story_5053_50531002_154_dialog_content = "趁她幫我們爭取時間，加晴，我們……回溯吧。",
  ui_story_5053_50531002_155_dialog_content = "醒了以後先去找「黑天使」，然後躲開那些衛兵，然後……",
  ui_story_5053_50531002_156_dialog_content = "PlayerName，你的手在發抖。",
  ui_story_5053_50531002_157_dialog_content = "……",
  ui_story_5053_50531002_158_dialog_content = "我知道你一個人肩負這麼重大的任務一定很緊張，但是別害怕。",
  ui_story_5053_50531002_159_dialog_content = "我們無條件相信你！一定沒問題的！",
  ui_story_5053_50531002_160_dialog_content = "加晴……！",
  ui_story_5053_50531002_161_dialog_content = "好！那就一鼓作氣吧！",
  ui_story_5053_50531002_162_dialog_content = "里特羅，里特羅，里特羅！讓時光倒流回起點……",
  ui_story_5053_50531002_163_dialog_content = "阿布拉卡達布拉！",
  ui_story_5053_50531101_0X_dialog_content = "<color=#e8d9bb>——第三次回溯後——</color>",
  ui_story_5053_50531101_1_dialog_content = "城主殿下，一切準備就緒。",
  ui_story_5053_50531101_2_dialog_content = "遊行的馬車已經停在門外，隨時可以出發。",
  ui_story_5053_50531101_3_dialog_content = "嗯，我知道了。",
  ui_story_5053_50531101_4_dialog_content = "卡蓮，妳先上車吧。",
  ui_story_5053_50531101_5_dialog_content = "卡蓮……卡蓮想留下來陪母親大人！",
  ui_story_5053_50531101_6_dialog_content = "加晴……蜜雅……我一定……",
  ui_story_5053_50531101_7_dialog_content = "嗯……這裡是……？",
  ui_story_5053_50531101_8_dialog_content = "啊！加晴幫我回溯了時間！",
  ui_story_5053_50531101_9_dialog_content = "窗外……小舒瓦茲正在帶著卡蓮出門。",
  ui_story_5053_50531101_10_dialog_content = "時間沒錯，我成功回來了！",
  ui_story_5053_50531101_11_dialog_content = "那麼首先要做的就是……",
  ui_story_5053_50531101_12_dialog_content = "可疑人員……夫人下令……消滅……",
  ui_story_5053_50531101_13_dialog_content = "可疑人員……不在這裡……",
  ui_story_5053_50531101_14_dialog_content = "呼～第一步，躲開追兵，順利完成。",
  ui_story_5053_50531101_15_dialog_content = "（從之前和蜜雅、加晴制定的計畫來看，需要完成的事情有三件。）",
  ui_story_5053_50531101_16_dialog_content = "（第一，提前找到並說服「黑天使」協助我們。）",
  ui_story_5053_50531101_17_dialog_content = "（第二，阻止巨龍和被污染者的襲擊，掃除障礙。）",
  ui_story_5053_50531101_18_dialog_content = "（第三，在無人犧牲的前提下，制服「白惡魔」。）",
  ui_story_5053_50531101_19_dialog_content = "（蜜雅、加晴……）",
  ui_story_5053_50531101_20_dialog_content = "（這已經是最後的回溯了，只許成功，不能失敗。）",
  ui_story_5053_50531101_21_dialog_content = "可疑人員……尋找……消滅…………",
  ui_story_5053_50531101_22_dialog_content = "！！",
  ui_story_5053_50531101_23_dialog_content = "這裡……沒有……",
  ui_story_5053_50531101_24_dialog_content = "（好險……從之前的經歷來看，這些被「白惡魔」控制的士兵會一直追蹤我。）",
  ui_story_5053_50531101_25_dialog_content = "（時間有限、能力有限、行動有限，我必須同時推進那三件事情。）",
  ui_story_5053_50531101_26_dialog_content = "（只能賭一把了！）",
  ui_story_5053_50531102_1_dialog_content = "<color=#e8d9bb>轟——！！</color>",
  ui_story_5053_50531102_2_dialog_content = "呃……咳咳……",
  ui_story_5053_50531102_3_dialog_content = "「黑天使」，去哪裡了？",
  ui_story_5053_50531102_4_dialog_content = "沿著外面的小路逃跑了？",
  ui_story_5053_50531102_5_dialog_content = "城主大人那一下，真的是天崩地裂！",
  ui_story_5053_50531102_6_dialog_content = "總之大家沒受傷就……",
  ui_story_5053_50531102_7_dialog_content = "哎呀，各位在這裡啊。",
  ui_story_5053_50531102_8_dialog_content = "媽媽……現在怎麼會在這裡？妳不是該去參加遊行了嗎？",
  ui_story_5053_50531102_9_dialog_content = "……",
  ui_story_5053_50531102_10_dialog_content = "……看來有不速之客闖入了庭院。",
  ui_story_5053_50531102_11_dialog_content = "大家沒事吧？",
  ui_story_5053_50531102_12_dialog_content = "姐姐？可是，剛剛逃走的那個「黑天使」又是……",
  ui_story_5053_50531102_13_dialog_content = "呵呵，看來我的小天才也有頭昏的時候呢。",
  ui_story_5053_50531102_14_dialog_content = "沒關係，剛戰鬥完一定很累吧，先進屋坐坐。",
  ui_story_5053_50531102_15_dialog_content = "至於那個怪物，我會派人去追緝牠的。",
  ui_story_5053_50531102_16_dialog_content = "請稍等，媽媽。呃，不太對勁……",
  ui_story_5053_50531102_17_dialog_content = "有人看到PlayerName嗎？",
  ui_story_5053_50531102_18_dialog_content = "對喔，PlayerName人呢？怎麼不見了。",
  ui_story_5053_50531102_19_dialog_content = "他從一開始就不在這裡。",
  ui_story_5053_50531102_20_dialog_content = "這......",
  ui_story_5053_50531102_21_dialog_content = "抱歉，媽媽。我們得先去找PlayerName，我怕他遇到危險……",
  ui_story_5053_50531102_22_dialog_content = "嗯，小薇懂得關心朋友，真貼心。但是媽媽有更重要的事情要告訴大家。",
  ui_story_5053_50531102_23_dialog_content = "我也會派人去找PlayerName的，所以先進屋好不好？",
  ui_story_5053_50531102_24_dialog_content = "哎？嗯……好、好吧……",
  ui_story_5053_50531102_25_dialog_content = "……是嗎？",
  ui_story_5053_50531102_26_dialog_content = "面對一個年輕人的生死安危還能如此雲淡風輕，可真不像妳。",
  ui_story_5053_50531102_27_dialog_content = "哎呀，我在你心中就這麼懦弱嗎？「狄安理」？",
  ui_story_5053_50531102_28_dialog_content = "……",
  ui_story_5053_50531102_29_dialog_content = "狄安理？姐姐妳是怎麼認出……難道？！",
  ui_story_5053_50531201_1_dialog_content = "哈、哈……",
  ui_story_5053_50531201_2_dialog_content = "剛、剛剛她的確是往這邊轉了，怎麼又不見了？",
  ui_story_5053_50531201_3_dialog_content = "……可惡……舒……瓦茲…………",
  ui_story_5053_50531201_4_dialog_content = "有了！在木箱後面！",
  ui_story_5053_50531201_5_dialog_content = "......！！",
  ui_story_5053_50531201_6_dialog_content = "等一下，我不是來和妳戰鬥的！凱萊布和蜜雅有危險，他們需要妳的幫助！",
  ui_story_5053_50531201_7_dialog_content = "凱……萊布……？蜜雅……？",
  ui_story_5053_50531201_8_dialog_content = "對，妳的弟弟凱萊布，和妳的女兒薇羅妮卡。",
  ui_story_5053_50531201_9_dialog_content = "他們是妳親愛的家人，對嗎？",
  ui_story_5053_50531201_10_dialog_content = "親愛的……家人……",
  ui_story_5053_50531201_11_dialog_content = "妳的家人現在身陷險境，他們需要妳。",
  ui_story_5053_50531201_12_dialog_content = "家人……危險……",
  ui_story_5053_50531201_13_dialog_content = "妳怎麼了......？",
  ui_story_5053_50531201_14_dialog_content = "<size=50>……家……人……舒瓦茲！！！</size>",
  ui_story_5053_50531201_15_dialog_content = "哎？！妳冷靜一點，聲音太大會把追兵引過來的！",
  ui_story_5053_50531201_16_dialog_content = "（上一次聽到凱萊布遇險，「黑天使」就願意幫忙，為什麼現在反而變得更狂暴了？）",
  ui_story_5053_50531201_17_dialog_content = "（難道是只有身為家人的蜜雅她們才能令「黑天使」平靜嗎？！）",
  ui_story_5053_50531201_18_dialog_content = "痛……！好痛……！",
  ui_story_5053_50531201_19_dialog_content = "怎麼辦……快想想，怎麼辦！沒有時間了！",
  ui_story_5053_50531201_20_dialog_content = "不哭……",
  ui_story_5053_50531201_21_dialog_content = "小薇……不哭……我的寶貝……",
  ui_story_5053_50531201_22_dialog_content = "不要傷心……不要難過……",
  ui_story_5053_50531201_23_dialog_content = "啊……",
  ui_story_5053_50531201_24_dialog_content = "（沒有感應能力的光靈們互相安慰的方法，對「黑天使」來說代表安寧的東西……）",
  ui_story_5053_50531201_25_dialog_content = "（只能試試了！）",
  ui_story_5053_50531201_26_dialog_content = "摘一束……玫瑰？送給我的寶貝～♪",
  ui_story_5053_50531201_27_dialog_content = "暖風吹拂……妳的笑顏？就是唯一～♪",
  ui_story_5053_50531201_28_dialog_content = "......？",
  ui_story_5053_50531201_29_dialog_content = "…………",
  ui_story_5053_50531201_30_dialog_content = "摘一束……玫瑰？送給親愛的爸爸媽媽～♪",
  ui_story_5053_50531201_31_dialog_content = "閉嘴。",
  ui_story_5053_50531201_32_dialog_content = "抱歉，我是不是唱得太爛了？",
  ui_story_5053_50531201_33_dialog_content = "這首歌是我偶然在街上聽到的曲子，我覺得它朗朗上口，就記住了一部分。",
  ui_story_5053_50531201_34_dialog_content = "旋律和歌詞都記得不是很全，獻醜了。",
  ui_story_5053_50531201_35_dialog_content = "舒瓦茲之人，沒有資格唱下城區的歌。",
  ui_story_5053_50531201_36_dialog_content = "……妳為什麼這麼恨舒瓦茲一族呢？",
  ui_story_5053_50531201_37_dialog_content = "恨到不惜偽裝自己、犧牲自己，接近我，和我成為戀人。",
  ui_story_5053_50531201_38_dialog_content = "然後以我為跳板，刺殺我的父親。",
  ui_story_5053_50531201_39_dialog_content = "……",
  ui_story_5053_50531201_40_dialog_content = "妳的演技天衣無縫，戰鬥能力和學識也是萬中選一。",
  ui_story_5053_50531201_41_dialog_content = "我甚至無法想像，妳到底花了多少時間來磨練這些能力。",
  ui_story_5053_50531201_42_dialog_content = "五年、十年、還是……迄今為止的一生？",
  ui_story_5053_50531201_43_dialog_content = "而這一切，都只是為了一場刺殺，一場不成功便成仁的刺殺？",
  ui_story_5053_50531201_44_dialog_content = "我的父親，就這麼值得妳和妳背後的人怨恨嗎？",
  ui_story_5053_50531201_45_dialog_content = "如果這其中有什麼誤會，我一定會替他澄清。",
  ui_story_5053_50531201_46_dialog_content = "這不僅是為了我父親的名譽，更是……我不願看到妳繼續為仇恨而活了。",
  ui_story_5053_50531201_47_dialog_content = "「舒瓦茲」就是強權和暴政的化身。",
  ui_story_5053_50531201_48_dialog_content = "你們吃的每一塊肉，穿的每一件衣服，都沾著受害者們的鮮血。",
  ui_story_5053_50531201_49_dialog_content = "這個「受害者」，包括凱萊布的「親生姐姐」還有妳「真正的家人」嗎？",
  ui_story_5053_50531201_50_dialog_content = "……",
  ui_story_5053_50531201_51_dialog_content = "別緊張，這只是我的推測而已。",
  ui_story_5053_50531201_52_dialog_content = "七年前，凱萊布的母親被捲入一場針對反叛者的追捕活動，不幸離世。",
  ui_story_5053_50531201_53_dialog_content = "當時，他的姐姐「約書亞」也在現場。",
  ui_story_5053_50531201_54_dialog_content = "而她卻成為唯一倖存者，奇蹟似地活了下來……不，是「不自然地活了下來」。",
  ui_story_5053_50531201_55_dialog_content = "於是就有了現在的妳，這位全新的「約書亞」，我說得對嗎？",
  ui_story_5053_50531201_56_dialog_content = "……",
  ui_story_5053_50531201_57_dialog_content = "我沒把這個推測告訴任何人，更沒告訴任何人妳在這裡。",
  ui_story_5053_50531201_58_dialog_content = "所有人都以為妳已經回家了，就連妳養父那邊我也是如此交代的。",
  ui_story_5053_50531201_59_dialog_content = "但實際上，妳並沒有回去，而妳的養父也沒對任何人提起妳失蹤的事。",
  ui_story_5053_50531201_60_dialog_content = "顯然，他知道妳有來無回的原因。",
  ui_story_5053_50531201_61_dialog_content = "……",
  ui_story_5053_50531201_62_dialog_content = "可是他非但沒有逃跑，反而在上課的時候試探性地問我和妳最近相處得如何。",
  ui_story_5053_50531201_63_dialog_content = "弑君之罪，千刀萬剮。但他啊，卻更擔心妳此時的安危。",
  ui_story_5053_50531201_64_dialog_content = "比起仇恨和恐懼，那個溫和的老學者選擇了妳。",
  ui_story_5053_50531201_65_dialog_content = "就算是為了他，也請妳打消刺殺我父親的念頭吧。",
  ui_story_5053_50531201_66_dialog_content = "如果妳願意放棄，我會當做一切沒有發生，並立即放妳回到家人身邊。",
  ui_story_5053_50531201_67_dialog_content = "收起你那蹩腳的苦情戲。我不在乎，那個男人也不會在乎。",
  ui_story_5053_50531201_68_dialog_content = "我們是因仇恨「舒瓦茲」而集結的同志，能為理想犧牲是無上的榮譽。",
  ui_story_5053_50531201_69_dialog_content = "喔，我剛剛說的那些只是猜測，毫無證據。",
  ui_story_5053_50531201_70_dialog_content = "而妳卻直接承認妳與凱萊布父親的合作關係。",
  ui_story_5053_50531201_71_dialog_content = "哈哈哈，這次終於讓我贏到一子！",
  ui_story_5053_50531201_72_dialog_content = "…………",
  ui_story_5053_50531201_73_dialog_content = "咳咳，開玩笑而已，我只是想緩和一下氣氛……",
  ui_story_5053_50531201_74_dialog_content = "我能理解妳的不信任。",
  ui_story_5053_50531201_75_dialog_content = "父親向來雷厲風行，對反叛者趕盡殺絕。甚至……寧願濫殺也不願錯放。",
  ui_story_5053_50531201_76_dialog_content = "他說這一切都是為了建立一種一致對外的風氣。",
  ui_story_5053_50531201_77_dialog_content = "所有人都推崇舒瓦茲家族，遵從唯一的領導者。",
  ui_story_5053_50531201_78_dialog_content = "當人們都信仰唯一正確的領袖時，貪婪自私之人便無處遁形。",
  ui_story_5053_50531201_79_dialog_content = "所有污垢清除後，白夜城就會成為世上最乾淨純粹的地方。",
  ui_story_5053_50531201_80_dialog_content = "父親的理想很偉大，我很崇拜我的父親。",
  ui_story_5053_50531201_81_dialog_content = "只是……父親的偉業還在建立途中，他的理想還無法被完全接受。",
  ui_story_5053_50531201_82_dialog_content = "不知道妳來我家的時候，有沒有注意到周圍人的表情。",
  ui_story_5053_50531201_83_dialog_content = "每當我在的時候，大家都會露出一張緊張而諂媚的臉。",
  ui_story_5053_50531201_84_dialog_content = "我曾遠遠見過大家私下露出的笑容，我知道那才是大家真心高興的樣子。",
  ui_story_5053_50531201_85_dialog_content = "於是我問父親，為什麼大家面對我時會如此不同。",
  ui_story_5053_50531201_86_dialog_content = "父親說，那是因為人們習慣了骯髒狡猾的生活方式。",
  ui_story_5053_50531201_87_dialog_content = "所以無法直視象徵絕對正義的舒瓦茲一族。",
  ui_story_5053_50531201_88_dialog_content = "這是人們無法根除的劣根，因此他們才需要我們的指引。",
  ui_story_5053_50531201_89_dialog_content = "背負和糾正這一切，就是舒瓦茲一族的使命。",
  ui_story_5053_50531201_90_dialog_content = "……可是，我還是無法承受這種令人窒息的感覺。",
  ui_story_5053_50531201_91_dialog_content = "所以才會經常翻牆跑到外面，隱藏身分感受片刻的放鬆。",
  ui_story_5053_50531201_92_dialog_content = "約書亞，我本來以為妳不一樣，只有妳會和我一起真心大笑。",
  ui_story_5053_50531201_93_dialog_content = "但到頭來，一切不過是我的一廂情願……我還是什麼都不懂。",
  ui_story_5053_50531201_94_dialog_content = "活該。",
  ui_story_5053_50531201_95_dialog_content = "哈哈……妳說得對，誰叫我是「舒瓦茲」呢。",
  ui_story_5053_50531201_96_dialog_content = "所以，我才更該正視妳的仇恨。",
  ui_story_5053_50531201_97_dialog_content = "這場幾近完美的暗殺，不會是寥寥幾人的手筆。",
  ui_story_5053_50531201_98_dialog_content = "身分的替換，常年的訓練，相關人員的協助……",
  ui_story_5053_50531201_99_dialog_content = "這是有多少人參與其中，才能讓每個環節都配合得如此天衣無縫。",
  ui_story_5053_50531201_100_dialog_content = "「舒瓦茲」的壓迫並沒有根除貪婪，反而令我們成為了無數民眾的敵人。",
  ui_story_5053_50531201_101_dialog_content = "父親所期望的，不該是這樣的結果啊……",
  ui_story_5053_50531201_102_dialog_content = "既然你知道錯了，那就該拉著你父親一起去死。而不是在這裡假惺惺地拉攏我。",
  ui_story_5053_50531201_103_dialog_content = "犯了錯就去死，那不是贖罪，是逃避。",
  ui_story_5053_50531201_104_dialog_content = "父親的理想並非全盤皆錯，他的政策也有好的一面。",
  ui_story_5053_50531201_105_dialog_content = "而那最好的證據，恰恰就是這場刺殺。",
  ui_story_5053_50531201_106_dialog_content = "......？",
  ui_story_5053_50531201_107_dialog_content = "以前在白夜城裡，階級和血統就是一切。",
  ui_story_5053_50531201_108_dialog_content = "有權者受賄貪污，法律只是統治者單向的工具，要職只會被有勢者霸佔……",
  ui_story_5053_50531201_109_dialog_content = "但在父親施予壓力下，下城的居民也有了伸張正義的權力。",
  ui_story_5053_50531201_110_dialog_content = "貴族們開始人人自危，主動坦露自己的罪行，祈求寬恕。",
  ui_story_5053_50531201_111_dialog_content = "有能之人開始跨越階級，透過考試獲得應有的評價。",
  ui_story_5053_50531201_112_dialog_content = "這就是父親想要的，不論出身，只看能力與努力的世界。",
  ui_story_5053_50531201_113_dialog_content = "凱萊布的父親不就是一位典型的平民學者嗎？",
  ui_story_5053_50531201_114_dialog_content = "如果我所說的一切有半點虛假，那麼非富非貴的他根本不可能靠才學來到高庭。",
  ui_story_5053_50531201_115_dialog_content = "而妳更不可能藉助家庭教師之女的身分接近我。",
  ui_story_5053_50531201_116_dialog_content = "制定這場暗殺計畫的人，就是深信這點的真實性，才會將如此重大的計畫立足於此。",
  ui_story_5053_50531201_117_dialog_content = "……",
  ui_story_5053_50531201_118_dialog_content = "所以，可以告訴我嗎？父親的政策究竟是哪裡沒有做到位。",
  ui_story_5053_50531201_119_dialog_content = "是下城區依舊被黑惡勢力佔據？還是過於決絕的清算造成了冤假錯案？",
  ui_story_5053_50531201_120_dialog_content = "如果有這樣的事情，我一定會追查到底。",
  ui_story_5053_50531201_121_dialog_content = "或許現在亡羊補牢已經無法彌補妳的傷痛……",
  ui_story_5053_50531201_122_dialog_content = "但至少為了更多人，我們需要及時糾正這些錯誤。",
  ui_story_5053_50531201_123_dialog_content = "……果然，你根本什麼都不懂。",
  ui_story_5053_50531201_124_dialog_content = "人們不需要正確的統治，人們需要真正的自由。",
  ui_story_5053_50531201_125_dialog_content = "真正的……自由？",
  ui_story_5053_50531201_126_dialog_content = "可以選擇自己喜歡的生活方式，而不會被烙上三六九等的標籤。",
  ui_story_5053_50531201_127_dialog_content = "可以說出自己心中的喜惡，而不會有身家性命的擔憂。",
  ui_story_5053_50531201_128_dialog_content = "這就是自由。",
  ui_story_5053_50531201_129_dialog_content = "那些僕從害怕你，是因為一聲時機不對的嘆息就能奪走他們的身家性命。",
  ui_story_5053_50531201_130_dialog_content = "不論出身，只看能力與努力？開什麼玩笑！",
  ui_story_5053_50531201_131_dialog_content = "你們「舒瓦茲」想要的，不過是看你們臉色而活的牲畜而已！！",
  ui_story_5053_50531201_132_dialog_content = "……",
  ui_story_5053_50531201_133_dialog_content = "……",
  ui_story_5053_50531201_134_dialog_content = "所以，妳希望殺死我的父親，消滅「舒瓦茲」。",
  ui_story_5053_50531201_135_dialog_content = "然後在那個沒有「舒瓦茲」的世界裡，過上真正自由的生活？",
  ui_story_5053_50531201_136_dialog_content = "這就是妳期望的幸福嗎？「約書亞」？",
  ui_story_5053_50531201_137_dialog_content = "我不期望幸福。",
  ui_story_5053_50531201_138_dialog_content = "刺殺行動結束之時，就是我生命終結之時。",
  ui_story_5053_50531201_139_dialog_content = "也就是說，無論成功與否，妳都會選擇死亡？",
  ui_story_5053_50531201_140_dialog_content = "是為了保護妳的同伴嗎？",
  ui_story_5053_50531201_141_dialog_content = "不，因為我的使命完成了，沒有繼續苟且偷生的理由了。",
  ui_story_5053_50531201_142_dialog_content = "沒有……理由……？",
  ui_story_5053_50531201_143_dialog_content = "貴族只會為了自身的利益而行動，而我們只為了理想而活。",
  ui_story_5053_50531201_144_dialog_content = "不求富貴，不問英名，一切都只為了讓新星升起，照耀所有人民。",
  ui_story_5053_50531201_145_dialog_content = "我們燃燒自己，擊落舊的太陽，僅此而已。不要用你們那種腐臭的功利思想衡量我們。",
  ui_story_5053_50531201_146_dialog_content = "呃，雖然我高興妳肯和我說這麼多，但怎麼全是這麼晦澀的內容。",
  ui_story_5053_50531201_147_dialog_content = "原來妳喜歡這樣說話嗎……？",
  ui_story_5053_50531201_148_dialog_content = "如果「舊的太陽」指的是父親的統治……那與之對應的「新星」，就是另一位新的統治者？",
  ui_story_5053_50531201_149_dialog_content = "這一切，都是為了讓妳背後的組織者取代父親成為新統治者嗎？",
  ui_story_5053_50531201_150_dialog_content = "……",
  ui_story_5053_50531201_151_dialog_content = "……我無法接受。",
  ui_story_5053_50531201_152_dialog_content = "我能理解為了保護同伴、家人，因此和敵人玉石俱焚。但是，什麼叫做「沒有苟且偷生的理由」？",
  ui_story_5053_50531201_153_dialog_content = "那個因為我搶走了妳的愛，就天天和我唱反調的妳弟弟。",
  ui_story_5053_50531201_154_dialog_content = "那個擔心妳安危，盼著妳回家的妳父親。",
  ui_story_5053_50531201_155_dialog_content = "他們難道不是妳活下去的理由嗎……？",
  ui_story_5053_50531201_156_dialog_content = "如果妳覺得舒瓦茲一族剝奪了大家的自由，那就毀滅「舒瓦茲」，自由的活下去好了！",
  ui_story_5053_50531201_157_dialog_content = "但是為什麼沒有了「舒瓦茲」，妳還是不能獲得自由？",
  ui_story_5053_50531201_158_dialog_content = "倘若我的父親意外猝死在家中，難道妳也要結束自己的生命嗎？！",
  ui_story_5053_50531201_159_dialog_content = "你不都已經證實過了嗎？我和那個男人，以及他兒子的關係只是虛假的偽裝。",
  ui_story_5053_50531201_160_dialog_content = "我是一把為了結束「舒瓦茲」統治而打造出來的武器。",
  ui_story_5053_50531201_161_dialog_content = "沒有了「舒瓦茲」，我就沒有存在意義。自由屬於人民，與我無關。",
  ui_story_5053_50531201_162_dialog_content = "…………太虛偽了。",
  ui_story_5053_50531201_163_dialog_content = "那個所謂的「新星」都沒能教會妳什麼是自由和愛。",
  ui_story_5053_50531201_164_dialog_content = "又要怎麼把這些帶給更多的人呢。",
  ui_story_5053_50531201_165_dialog_content = "……",
  ui_story_5053_50531201_166_dialog_content = "…………我明白了。",
  ui_story_5053_50531201_167_dialog_content = "我沒有身處過妳的世界，所以無法理解人們對高壓政策的恨。",
  ui_story_5053_50531201_168_dialog_content = "妳也沒有身處過我的世界，所以無法理解愛與自由的形狀。",
  ui_story_5053_50531201_169_dialog_content = "這是我們自身無法逾越的橫溝。",
  ui_story_5053_50531201_170_dialog_content = "沒錯，所以你最好放棄……",
  ui_story_5053_50531201_171_dialog_content = "所以我們應該合作，互相彌補彼此的缺失！",
  ui_story_5053_50531201_172_dialog_content = "你瘋了。",
  ui_story_5053_50531201_173_dialog_content = "我也好，妳也好，父親也好，那個「新星」也好……",
  ui_story_5053_50531201_174_dialog_content = "或許，一個人想要設身處地的為所有人考慮，是不可能的。",
  ui_story_5053_50531201_175_dialog_content = "但我們可以試試放下成見，一起努力。",
  ui_story_5053_50531201_176_dialog_content = "然後創造一個，每個人的聲音都可以被聽到的，真正自由的世界！",
  ui_story_5053_50531201_177_dialog_content = "這也應該是妳的理想，對吧？",
  ui_story_5053_50531201_178_dialog_content = "……",
  ui_story_5053_50531201_179_dialog_content = "自從我阻止了妳那天起，我就開始不斷思考。",
  ui_story_5053_50531201_180_dialog_content = "我們這樣把夢想寄託於他人，是不是個錯誤的選擇。",
  ui_story_5053_50531201_181_dialog_content = "不論是單純遵從父親的理想，還是用死亡給那個「新星」鋪路。",
  ui_story_5053_50531201_182_dialog_content = "或許都不如把命運掌握在自己手中來得真切。",
  ui_story_5053_50531201_183_dialog_content = "雖然，我現在很無知，也很迷茫。",
  ui_story_5053_50531201_184_dialog_content = "但我有種預感，和妳在一起，一切一定會變得有所不同。",
  ui_story_5053_50531201_185_dialog_content = "首先，第一步。",
  ui_story_5053_50531201_186_dialog_content = "妳來幫助我拓寬眼界，瞭解高庭之外的世界究竟是什麼模樣。",
  ui_story_5053_50531201_187_dialog_content = "這樣我才能明白父親的做法究竟哪裡出了問題。",
  ui_story_5053_50531201_188_dialog_content = "而我會帶妳去盡情的感受生活，讓妳能夠發自內心的歡笑。",
  ui_story_5053_50531201_189_dialog_content = "然後妳再把這樣的笑容傳遞給更多的人！",
  ui_story_5053_50531201_190_dialog_content = "……無聊。",
  ui_story_5053_50531201_191_dialog_content = "宮廷裡多得是願意陪你演戲的人，何必在我身上浪費時間。",
  ui_story_5053_50531201_192_dialog_content = "呃……畢竟……",
  ui_story_5053_50531201_193_dialog_content = "很少有人敢違抗我父親，而且高庭的居民大多都無法理解外面的世界……",
  ui_story_5053_50531201_194_dialog_content = "以及，咳咳，就像我第一次見到妳時說的那樣——",
  ui_story_5053_50531201_195_dialog_content = "我對妳一見鍾情了！",
  ui_story_5053_50531201_196_dialog_content = "…………",
  ui_story_5053_50531201_197_dialog_content = "（「黑天使」已經呆住不動很久了，她這算是平靜下來了吧……？）",
  ui_story_5053_50531201_198_dialog_content = "喂～妳現在能冷靜聽我講話了嗎？",
  ui_story_5053_50531201_199_dialog_content = "妳聽我說，那個「白惡魔」……也就是另一個妳，她想要殺死凱萊布和蜜雅他們。",
  ui_story_5053_50531201_200_dialog_content = "他們需要妳的幫……",
  ui_story_5053_50531201_201_dialog_content = "狄……安理…………",
  ui_story_5053_50531201_202_dialog_content = "咦？",
  ui_story_5053_50531201_203_dialog_content = "狄安理……為什麼……背叛……！",
  ui_story_5053_50531201_204_dialog_content = "<size=45>狄安理！！！</size>",
  ui_story_5053_50531201_205_dialog_content = "為什麼？！她怎麼變得更加狂暴了！我不是城主大人啊，妳清醒一點！",
  ui_story_5053_50531201_206_dialog_content = "<size=45>狄安理！狄安理！</size>",
  ui_story_5053_50531201_207_dialog_content = "（沒時間了！至少我成功吸引了她的注意力，先把她引去中央廣場再說吧！）",
  ui_story_5053_50531201_208_dialog_content = "<size=45>狄安理————</size>",
  ui_story_5053_50531301_1_dialog_content = "感謝所有白夜城子民今日在此相聚，歡慶這個特殊的節日。",
  ui_story_5053_50531301_2_dialog_content = "舒瓦茲家族，既是白夜城的頂上之冠，也是其立命根基。",
  ui_story_5053_50531301_3_dialog_content = "我們舉臂托起眾人，而我們的利劍也由眾人鑄造。",
  ui_story_5053_50531301_4_dialog_content = "今日，我們在此稱頌「舒瓦茲」的美德，也稱頌白夜城百姓萬眾的美德！",
  ui_story_5053_50531301_5_dialog_content = "我宣布，「舒瓦茲家族日」慶典，正式開始！",
  ui_story_5053_50531301_6_dialog_content = "慶典照常開始了，看來黑天使也沒有在看台那邊現身。",
  ui_story_5053_50531301_7_dialog_content = "清除……妨礙……",
  ui_story_5053_50531301_8_dialog_content = "那麼，這些士兵又是什麼？",
  ui_story_5053_50531301_9_dialog_content = "照理來說，永憶鏡晶中的人物不過是光能化成的幻影。",
  ui_story_5053_50531301_10_dialog_content = "為何會突然喪失神志，變成無法溝通的喪屍……",
  ui_story_5053_50531301_11_dialog_content = "那，按照剛才所說的計畫，我先去看台。一旦察覺到「黑天使」在附近，我就呼叫大家。",
  ui_story_5053_50531301_12_dialog_content = "嗯，蜜雅，萬事小心。",
  ui_story_5053_50531301_13_dialog_content = "（蜜雅那邊暫時不會有什麼問題。但PlayerName這個時候會去哪裡？）",
  ui_story_5053_50531301_14_dialog_content = "嗯？",
  ui_story_5053_50531301_15_dialog_content = "PlayerName......",
  ui_story_5053_50531301_16_dialog_content = "搜尋……PlayerName……",
  ui_story_5053_50531301_17_dialog_content = "且慢，你們這身裝扮，顯然並非卡爾帝瑪家族的騎士。",
  ui_story_5053_50531301_18_dialog_content = "慶典期間，護衛街道乃卡爾帝瑪之責，你們為何遊蕩此處？",
  ui_story_5053_50531301_19_dialog_content = "（這些士兵步伐不穩，口中喃喃不斷，難道是飲酒了嗎？）",
  ui_story_5053_50531301_20_dialog_content = "（而且，為何他們口中會冒出PlayerName的名字？）",
  ui_story_5053_50531301_21_dialog_content = "搜尋……PlayerName……",
  ui_story_5053_50531301_22_dialog_content = "消滅……PlayerName……",
  ui_story_5053_50531301_23_dialog_content = "這話我可不能當做耳邊風。",
  ui_story_5053_50531301_24_dialog_content = "麻煩你們好好交代一下事情原委吧。",
  ui_story_5053_50531301_25_dialog_content = "清除……妨礙……！",
  ui_story_5053_50531301_26_dialog_content = "別說問出幕後指使，就連正常溝通都沒辦法，這些士兵到底是怎麼回事？",
  ui_story_5053_50531301_27_dialog_content = "（時間重設後，「永憶鏡晶」中應該無人認識PlayerName。）",
  ui_story_5053_50531301_28_dialog_content = "（別說對他有血海深仇，就連知道他存在的人都寥寥無幾。）",
  ui_story_5053_50531301_29_dialog_content = "沒有必要花這個時間。派衛兵去找PlayerName也是一樣的。",
  ui_story_5053_50531301_30_dialog_content = "但那個怪物唯有靠大家齊心協力才有可能戰勝。",
  ui_story_5053_50531301_31_dialog_content = "兩件事哪邊重要，相信你能夠判斷。理智一點吧。",
  ui_story_5053_50531301_32_dialog_content = "（……除了我們這一行人，約書亞是唯一知道PlayerName存在的人。）",
  ui_story_5053_50531301_33_dialog_content = "（也是除我們之外，「永憶鏡晶」中唯一的活人。）",
  ui_story_5053_50531301_34_dialog_content = "（但是，妳又有什麼理由追殺這個與妳毫無關係的年輕人呢？）",
  ui_story_5053_50531301_35_dialog_content = "（至少我已將凱萊布藉故留在她身旁了。）",
  ui_story_5053_50531301_36_dialog_content = "（希望那個機靈的小子能替我看清一切，可千萬別重逢的喜悅沖昏了頭。）",
  ui_story_5053_50531301_37_dialog_content = "呼、呼……城主大人！太好了，你居然在這裡！",
  ui_story_5053_50531301_38_dialog_content = "PlayerName……？",
  ui_story_5053_50531301_39_dialog_content = "啊啊啊————！！！",
  ui_story_5053_50531301_40_dialog_content = "PlayerName，趴下！",
  ui_story_5053_50531301_41_dialog_content = "別管「黑天使」了，快去看台！蜜雅有危險！！",
  ui_story_5053_50531301_42_dialog_content = "什麼意思？",
  ui_story_5053_50531301_43_dialog_content = "相信我！趕快去看台！！",
  ui_story_5053_50531301_44_dialog_content = "好吧……",
  ui_story_5053_50531301_45_dialog_content = "哇？！您、您這是幹什麼啊！",
  ui_story_5053_50531301_46_dialog_content = "別亂動，我帶你去看台。",
  ui_story_5053_50531301_47_dialog_content = "？！",
  ui_story_5053_50531301_48_dialog_content = "狄……安理……？狄安理！！！",
  ui_story_5053_50531301_49_dialog_content = "呀！別推我啊！",
  ui_story_5053_50531301_50_dialog_content = "發、發生什麼事了？",
  ui_story_5053_50531301_51_dialog_content = "怪物，有怪物啊！！",
  ui_story_5053_50531301_52_dialog_content = "下面的人群有些吵鬧，發生什麼事了？",
  ui_story_5053_50531301_53_dialog_content = "<size=30>那是……父親和PlayerName，還有「黑天使」……？！</size>",
  ui_story_5053_50531301_54_dialog_content = "薇羅妮卡，妳說什麼？",
  ui_story_5053_50531301_55_dialog_content = "不，沒什麼......",
  ui_story_5053_50531301_56_dialog_content = "他們衝出人群向著看台來了！",
  ui_story_5053_50531301_57_dialog_content = "侍衛，還不攔住他們！！",
  ui_story_5053_50531301_58_dialog_content = "（黑天使真的來追殺父親了，和媽媽說的一樣。）",
  ui_story_5053_50531301_59_dialog_content = "（雖然不知道他們為什麼要跑到看台這邊來，但是我必須保護他。）",
  ui_story_5053_50531301_60_dialog_content = "（拜託了，我的力量，一定要聽我的話呀……！）",
  ui_story_5053_50531301_61_dialog_content = "姐姐，發生什麼事了？廣場上橫衝直撞的那些人是誰呀？",
  ui_story_5053_50531301_62_dialog_content = "沒、沒什麼，卡蓮妳千萬不要亂跑喔。",
  ui_story_5053_50531301_63_dialog_content = "那個跑在前面的男人是怎麼回事。",
  ui_story_5053_50531301_64_dialog_content = "明明還扛著一個人，卻能輕易躲過所有衛兵的攔截。",
  ui_story_5053_50531301_65_dialog_content = "那身姿，簡直就像是……",
  ui_story_5053_50531301_66_dialog_content = "喂，那個老頭踩著被他絆倒的士兵一躍而起……直接朝著看台飛過來了！！",
  ui_story_5053_50531301_67_dialog_content = "侍衛，保護其他人，我來對付他們。",
  ui_story_5053_50531301_68_dialog_content = "……",
  ui_story_5053_50531301_69_dialog_content = "來者何人？",
  ui_story_5053_50531301_70_dialog_content = "PlayerName，你說的危險在哪裡？",
  ui_story_5053_50531301_71_dialog_content = "老者，回答我的問題！",
  ui_story_5053_50531301_72_dialog_content = "在天上，很快就會來！",
  ui_story_5053_50531301_73_dialog_content = "這怪物又是怎麼回事？！侍衛！侍衛！保護我！侍衛！",
  ui_story_5053_50531301_74_dialog_content = "狄安……理？狄安理……？狄安理…………",
  ui_story_5053_50531301_75_dialog_content = "啊啊啊——狄安理——！！！",
  ui_story_5053_50531301_76_dialog_content = "休想傷害父親！",
  ui_story_5053_50531301_77_dialog_content = "……來了！飛龍來了！！",
  ui_story_5053_50531301_78_dialog_content = "<size=50>吼嗚——！！！</size>",
  ui_story_5053_50531301_79_dialog_content = "龍……是飛龍？",
  ui_story_5053_50531301_80_dialog_content = "刻在卡爾帝瑪家族血脈中的契約……可是，為什麼這麼早？",
  ui_story_5053_50531301_81_dialog_content = "年輕人，別賣弄小聰明了，專注於眼前的危機。",
  ui_story_5053_50531301_82_dialog_content = "卡爾帝瑪的逆賊，這裡還輪不到你發號施令！",
  ui_story_5053_50531301_83_dialog_content = "專心！搞清楚妳的敵人是誰！牠要來了！！",
  ui_story_5053_50531301_84_dialog_content = "……",
  ui_story_5053_50531301_85_dialog_content = "飛、飛龍！我記得飛龍不應該現在就出現啊……",
  ui_story_5053_50531301_86_dialog_content = "姐姐別怕！卡蓮保護妳！",
  ui_story_5053_50531301_87_dialog_content = "不……叛亂提前開始了，卡蓮妳快躲起來！",
  ui_story_5053_50531301_88_dialog_content = "卡……蓮……？蜜……雅……？",
  ui_story_5053_50531301_89_dialog_content = "吼！！！！！！",
  ui_story_5053_50531301_90_dialog_content = "飛龍開始攻擊了！！",
  ui_story_5053_50531301_91_dialog_content = "——————！！！",
  ui_story_5053_50531301_92_dialog_content = "這是哪裡來的飛龍啊！？",
  ui_story_5053_50531301_93_dialog_content = "哇——爸爸你在哪——",
  ui_story_5053_50531301_94_dialog_content = "牠噴火了，快逃啊！！",
  ui_story_5053_50531301_95_dialog_content = "兒子！兒子！你去哪裡了？！",
  ui_story_5053_50531301_96_dialog_content = "……",
  ui_story_5053_50531301_97_dialog_content = "衛兵大哥，你有沒有看到一個小男孩，大概這麼高……",
  ui_story_5053_50531301_98_dialog_content = "……增加……消滅……",
  ui_story_5053_50531301_99_dialog_content = "啊？你說什麼？",
  ui_story_5053_50531301_100_dialog_content = "增加同伴……消滅他們……",
  ui_story_5053_50531301_101_dialog_content = "咕啊？！你幹什麼……",
  ui_story_5053_50531301_102_dialog_content = "增加同伴……消滅他們……",
  ui_story_5053_50531301_103_dialog_content = "咳咳咳……姐姐，父親！你們在哪裡？",
  ui_story_5053_50531301_104_dialog_content = "卡蓮妳沒事吧！",
  ui_story_5053_50531301_105_dialog_content = "嗯，卡蓮只是被嗆到了，卡蓮沒事。",
  ui_story_5053_50531301_106_dialog_content = "太好了……",
  ui_story_5053_50531301_107_dialog_content = "蜜雅……卡蓮……",
  ui_story_5053_50531301_108_dialog_content = "成功了！四個人成功阻止飛龍的襲擊了！！",
  ui_story_5053_50531301_109_dialog_content = "（果然只有親人才能令「黑天使」平靜下來。雖然過程有點驚險，但是我賭贏了！）",
  ui_story_5053_50531301_110_dialog_content = "別高興得太早。",
  ui_story_5053_50531301_111_dialog_content = "飛龍需要積蓄再次噴火的能量，所以才暫時回到空中盤旋。",
  ui_story_5053_50531301_112_dialog_content = "下一次攻擊馬上就會到來。",
  ui_story_5053_50531301_113_dialog_content = "那麼，只要在牠攻擊之前，將牠一刀斬下即可。",
  ui_story_5053_50531301_114_dialog_content = "妳最好第一招就擊中龍的弱點。",
  ui_story_5053_50531301_115_dialog_content = "牠的弱點是……",
  ui_story_5053_50531301_116_dialog_content = "我當然知道。",
  ui_story_5053_50531301_117_dialog_content = "沒用的，那條飛龍具有「不死性」，傷口很快就會復原。",
  ui_story_5053_50531301_118_dialog_content = "什麼？",
  ui_story_5053_50531301_119_dialog_content = "報告城主大人，暴動開始了！",
  ui_story_5053_50531301_120_dialog_content = "按照原計劃，調度人馬，圍剿反賊。",
  ui_story_5053_50531301_121_dialog_content = "廣場上的飛龍交給我處理，其餘人負責疏散民眾。",
  ui_story_5053_50531301_122_dialog_content = "可是……不只是反叛軍，周圍的民眾，甚至還有我們的士兵，都開始加入暴動了！",
  ui_story_5053_50531301_123_dialog_content = "什麼……？！",
  ui_story_5053_50531301_124_dialog_content = "參與暴動者的神情非常奇怪。他們神智不清、不分敵我地攻擊一切活物。",
  ui_story_5053_50531301_125_dialog_content = "最詭異的是，被他們擊傷的人也會加入他們！簡直就像是……",
  ui_story_5053_50531301_126_dialog_content = "就像會傳染的喪屍，對嗎？",
  ui_story_5053_50531301_127_dialog_content = "是的。",
  ui_story_5053_50531301_128_dialog_content = "看來你知道不少內幕。",
  ui_story_5053_50531301_129_dialog_content = "時間不多了，告訴我這一切是什麼回事。",
  ui_story_5053_50531301_130_dialog_content = "這……",
  ui_story_5053_50531301_131_dialog_content = "（小舒瓦茲也正盯著我看……）",
  ui_story_5053_50531301_132_dialog_content = "（如果不能拿出令他滿意的說法，他肯定不會輕易放過我。）",
  ui_story_5053_50531301_133_dialog_content = "（但是把真相告訴他只會招來他的不信任，我得編一套漂亮的說詞……呃……）",
  ui_story_5053_50531301_134_dialog_content = "就這麼忌憚在我面前吐露真相嗎？",
  ui_story_5053_50531301_135_dialog_content = "或者說，這一切的罪魁禍首就在你們這群不速之客當中——",
  ui_story_5053_50531301_136_dialog_content = "比如說那個頭生羽翼的怪物。",
  ui_story_5053_50531301_137_dialog_content = "請別這麼說她！她不是怪物，她是……",
  ui_story_5053_50531301_138_dialog_content = "天上，飛龍馬上就要展開第二次攻勢了。",
  ui_story_5053_50531301_139_dialog_content = "地上，喪屍潮正在包圍看台。",
  ui_story_5053_50531301_140_dialog_content = "你應該明白當務之急是什麼。",
  ui_story_5053_50531301_141_dialog_content = "……我當然明白。",
  ui_story_5053_50531301_142_dialog_content = "侍衛，通知拉瓊和奧托，我將廣場士兵的指揮權暫時交給他們。",
  ui_story_5053_50531301_143_dialog_content = "要他們以看台為中心布陣防守，並收留群眾避難，我來牽制飛龍。",
  ui_story_5053_50531301_144_dialog_content = "遵命！",
  ui_story_5053_50531301_145_dialog_content = "（幸虧有老舒瓦茲幫我解圍，看來他也察覺到我的難言之隱了。）",
  ui_story_5053_50531301_146_dialog_content = "（好不容易爭取到的時間可不能浪費，得趕緊返回舒瓦茲宅邸！）",
  ui_story_5053_50531301_147_dialog_content = "姐姐，牠為什麼在叫我的名字？",
  ui_story_5053_50531301_148_dialog_content = "卡蓮，千萬別靠近牠。",
  ui_story_5053_50531301_149_dialog_content = "蜜雅……卡蓮……有沒有……受傷……？",
  ui_story_5053_50531301_150_dialog_content = "哪裡……痛嗎……？",
  ui_story_5053_50531301_151_dialog_content = "痛……媽媽……抱……唱歌……",
  ui_story_5053_50531301_152_dialog_content = "哎？我、我沒事，卡蓮我剛剛檢查過了，她也沒事。",
  ui_story_5053_50531301_153_dialog_content = "原來妳可以溝通啊……妳也是媽媽的一部分，對嗎？",
  ui_story_5053_50531301_154_dialog_content = "媽媽……是……媽媽……",
  ui_story_5053_50531301_155_dialog_content = "那可不可以請妳別再攻擊我們了，包括父親。",
  ui_story_5053_50531301_156_dialog_content = "蜜雅……父親……狄安理……狄安理……！！！",
  ui_story_5053_50531301_157_dialog_content = "媽、媽媽不喜歡當著我們的面和爸爸吵架！",
  ui_story_5053_50531301_158_dialog_content = "對不對？",
  ui_story_5053_50531301_159_dialog_content = "…………",
  ui_story_5053_50531301_160_dialog_content = "不吵架……嚇到孩子……不吵架……",
  ui_story_5053_50531301_161_dialog_content = "蜜雅……不怕……媽媽……不吵架……",
  ui_story_5053_50531301_162_dialog_content = "嗯，謝謝妳，媽媽。",
  ui_story_5053_50531301_163_dialog_content = "（媽媽說「黑天使」是種子的產物，是個沒有理性的瘋子。）",
  ui_story_5053_50531301_164_dialog_content = "（但實際上我可以跟她溝通，甚至覺得她有一點……溫柔。）",
  ui_story_5053_50531301_165_dialog_content = "（而宅邸裡的媽媽卻有一點冷漠，這到底是為什麼呢……）",
  ui_story_5053_50531301_166_dialog_content = "<size=30>喂，蜜雅，這邊！</size>",
  ui_story_5053_50531301_167_dialog_content = "PlayerName、父親！你們沒事吧！",
  ui_story_5053_50531301_168_dialog_content = "噓，，小聲點。",
  ui_story_5053_50531301_169_dialog_content = "趁著小舒瓦茲忙著對付飛龍，我們帶「黑天使」一起走吧。",
  ui_story_5053_50531301_170_dialog_content = "帶「黑天使」……？去哪裡啊？",
  ui_story_5053_50531301_171_dialog_content = "回舒瓦茲宅邸，凱萊布和加晴有危險。",
  ui_story_5053_50531301_172_dialog_content = "哎？等等，我有點混亂，這到底……",
  ui_story_5053_50531301_173_dialog_content = "PlayerName承諾會在路上解釋一切，姑且跟他走一趟吧。",
  ui_story_5053_50531301_174_dialog_content = "嗯......嗯，好的。",
  ui_story_5053_50531301_175_dialog_content = "狄安理………………",
  ui_story_5053_50531301_176_dialog_content = "PlayerName，你確定她不會再次攻擊我嗎？",
  ui_story_5053_50531301_177_dialog_content = "呃，按理說不會了……",
  ui_story_5053_50531301_178_dialog_content = "不會了，媽媽已經和我約好了，對不對？",
  ui_story_5053_50531301_179_dialog_content = "約……好了……",
  ui_story_5053_50531301_180_dialog_content = "……好吧。",
  ui_story_5053_50531301_181_dialog_content = "我們走看台後面，那邊沒有圍觀群眾，趁著守軍布防還沒結束，趕快。",
  ui_story_5053_50531301_182_dialog_content = "姐姐，妳要去哪裡？",
  ui_story_5053_50531301_183_dialog_content = "父親說待會紅女士會來接我們，叫我們倆待在一起不要亂跑。",
  ui_story_5053_50531301_184_dialog_content = "卡蓮，姐姐有點事要辦，沒法繼續陪著妳了。",
  ui_story_5053_50531301_185_dialog_content = "妳是個勇敢的孩子，可以一個人在這裡等紅女士嗎？",
  ui_story_5053_50531301_186_dialog_content = "卡蓮沒問題，可是卡蓮擔心妳。",
  ui_story_5053_50531301_187_dialog_content = "卡蓮知道，姐姐常常一個人偷哭……",
  ui_story_5053_50531301_188_dialog_content = "但是姐姐別怕，卡蓮已經變得很強了，卡蓮可以保護姐姐！",
  ui_story_5053_50531301_189_dialog_content = "嘿嘿，真不愧是成熟懂事的小卡蓮。",
  ui_story_5053_50531301_190_dialog_content = "放心吧，姐姐已經不再像以前那樣軟弱了。",
  ui_story_5053_50531301_191_dialog_content = "所以不用總是擔心姐姐。",
  ui_story_5053_50531301_192_dialog_content = "雖然過去我總是比妳慢半拍，總是給大家添麻煩……",
  ui_story_5053_50531301_193_dialog_content = "但從現在開始，我會努力做個可靠的姐姐，替妳分擔身上的重擔。",
  ui_story_5053_50531301_194_dialog_content = "姐姐……？",
  ui_story_5053_50531301_195_dialog_content = "所以，相信我吧。",
  ui_story_5053_50531301_196_dialog_content = "嗯，我相信。",
  ui_story_5053_50531301_197_dialog_content = "嘿嘿，謝謝妳。",
  ui_story_5053_50531301_198_dialog_content = "那麼，再見了，我心愛的小卡蓮。",
  ui_story_5053_50531302_1_dialog_content = "……以上就是中央廣場的狀況。",
  ui_story_5053_50531302_2_dialog_content = "目前通往廣場的所有閘門都已關閉。",
  ui_story_5053_50531302_3_dialog_content = "在城主殿下的帶領下，暴動已經得到控制，還請您放心。",
  ui_story_5053_50531302_4_dialog_content = "……我明白了，你可以退下了。",
  ui_story_5053_50531302_5_dialog_content = "明白。",
  ui_story_5053_50531302_6_dialog_content = "說到這個，加晴，能麻煩妳把房間的門鎖上嗎？",
  ui_story_5053_50531302_7_dialog_content = "喔對！門還是鎖上比較安全，沒問題～",
  ui_story_5053_50531302_8_dialog_content = "凱萊布，我想問你一個問題。為什麼你會想要救我呢？",
  ui_story_5053_50531302_9_dialog_content = "咦？",
  ui_story_5053_50531302_10_dialog_content = "嗯？妳是我的親姐姐，我救妳天經地義啊。",
  ui_story_5053_50531302_11_dialog_content = "<color=#e8d9bb>咚咚咚——</color>",
  ui_story_5053_50531302_12_dialog_content = "夫人，是我，我來接您了。現在方便我進來嗎？",
  ui_story_5053_50531302_13_dialog_content = "方便方便，快進來吧！",
  ui_story_5053_50531302_14_dialog_content = "加晴，妳就沒有點身為客人的自覺嗎？姐姐還沒說話呢。",
  ui_story_5053_50531302_15_dialog_content = "……",
  ui_story_5053_50531302_16_dialog_content = "那麼就打擾了……",
  ui_story_5053_50531302_17_dialog_content = "紅女士，妳有什麼事嗎？",
  ui_story_5053_50531302_18_dialog_content = "您今天身體不適，城主殿下特地要我留下來保護您的安全。",
  ui_story_5053_50531302_19_dialog_content = "現在有緊急情況，還請您隨我去安全的地方避難。",
  ui_story_5053_50531302_20_dialog_content = "之後我也會去廣場接卡蓮公主，請您不必擔心。",
  ui_story_5053_50531302_21_dialog_content = "這樣啊，勞妳費心了。",
  ui_story_5053_50531302_22_dialog_content = "不過我和客人們在這裡很安全，妳不用管我，去接卡蓮就好。",
  ui_story_5053_50531302_23_dialog_content = "那怎麼行。",
  ui_story_5053_50531302_24_dialog_content = "還是說……我在這裡，您不方便殺害這兩位年輕的客人呢？",
  ui_story_5053_50531302_25_dialog_content = "殺、殺害？！",
  ui_story_5053_50531302_26_dialog_content = "紅女士，妳胡說什麼！姐姐怎麼可能……",
  ui_story_5053_50531302_27_dialog_content = "姐姐……？",
  ui_story_5053_50531302_28_dialog_content = "是啊，我怎麼可能做出這種事呢。",
  ui_story_5053_50531302_29_dialog_content = "我完全搞不懂妳在說什麼，紅女士。",
  ui_story_5053_50531302_30_dialog_content = "您不用再裝了。",
  ui_story_5053_50531302_31_dialog_content = "刀就藏在您的腿上，對吧？真是經典的暗殺方法啊。",
  ui_story_5053_50531302_32_dialog_content = "您藏匿武器的技巧很高明，但那迫不及待伸向刀柄的手還是暴露了您的意圖。",
  ui_story_5053_50531302_33_dialog_content = "……",
  ui_story_5053_50531302_34_dialog_content = "您是一位高明的刺客。",
  ui_story_5053_50531302_35_dialog_content = "是一個很像我老師，卻又似是而非的假貨。",
  ui_story_5053_50531302_36_dialog_content = "假貨？可是姐姐……她的聲音、樣貌，我不可能認錯的……！",
  ui_story_5053_50531302_37_dialog_content = "對啊對啊，而且永憶鏡晶也顯示她是個真實的活人啊！",
  ui_story_5053_50531302_38_dialog_content = "難不成，是別的活人偽裝成約書亞夫人嗎？？",
  ui_story_5053_50531302_39_dialog_content = "不知道兩位與這位殺手是什麼關係，但為了您們的安全，我建議暫時不要靠近她。",
  ui_story_5053_50531302_40_dialog_content = "我猜，您或許是「那個組織」的殘黨，由他們培養出的另一個殺手。",
  ui_story_5053_50531302_41_dialog_content = "畢竟您這個樣子，太像過去的老師了。",
  ui_story_5053_50531302_42_dialog_content = "只是正因如此，您才無法模仿現在的她，那個身為妻子、身為母親、身為姐姐的約書亞夫人。",
  ui_story_5053_50531302_43_dialog_content = "我說得對嗎？",
  ui_story_5053_50531302_44_dialog_content = "…………",
  ui_story_5053_50531302_45_dialog_content = "約、約書亞夫人手上拿著刀！她是從哪變出那種東西來的啊……",
  ui_story_5053_50531302_46_dialog_content = "哎呀，管不了這麼多了！小占卜球！",
  ui_story_5053_50531302_47_dialog_content = "這怎麼可能，她就是姐姐啊，不論怎麼看就是姐姐啊……",
  ui_story_5053_50531302_48_dialog_content = "凱萊布你別愣在那裡，不想戰鬥的話就躲開！",
  ui_story_5053_50531302_49_dialog_content = "<size=45>啊啊啊————！</size>",
  ui_story_5053_50531302_50_dialog_content = "妳……妳是——！！",
  ui_story_5053_50531302_51_dialog_content = "是那個「黑天使」！",
  ui_story_5053_50531302_52_dialog_content = "「黑天使」……？",
  ui_story_5053_50531302_53_dialog_content = "離……凱萊布……遠點……",
  ui_story_5053_50531302_54_dialog_content = "<size=45>離……凱萊布……遠點……！！</size>",
  ui_story_5053_50531302_55_dialog_content = "為什麼妳會在這裡？！",
  ui_story_5053_50531302_56_dialog_content = "別過來，妳這噁心、骯髒的東西！",
  ui_story_5053_50531302_57_dialog_content = "休想逃！",
  ui_story_5053_50531302_58_dialog_content = "約書亞夫人要殺我們，「黑天使」趕跑了約書亞夫人……",
  ui_story_5053_50531302_59_dialog_content = "這這這這都是怎麼回事啦！誰來解釋一下！",
  ui_story_5053_50531302_60_dialog_content = "停、停下來！希頗喀停下來……！！",
  ui_story_5053_50531302_61_dialog_content = "嗚哇？！怎麼又從窗戶飛出一頭好大的蜘蛛馬？？",
  ui_story_5053_50531302_62_dialog_content = "……PlayerName？！還有蜜雅和城主大人！",
  ui_story_5053_50531302_63_dialog_content = "蜜雅，幹得不錯，看來妳在駕馭光能召喚物這方面有很強的天賦。",
  ui_story_5053_50531302_64_dialog_content = "哈、哈……我還是第一次知道希頗喀可以這樣用……",
  ui_story_5053_50531302_65_dialog_content = "呃……坐著蜘蛛馬在建築物上跳來跳去……我快吐了…………",
  ui_story_5053_50531302_66_dialog_content = "你們這到底是……",
  ui_story_5053_50531302_67_dialog_content = "凱萊布、加晴！你們看起來沒事……",
  ui_story_5053_50531302_68_dialog_content = "太好了，我們趕上了……嘔……！",
  ui_story_5053_50531401_1_dialog_content = "所以說……我們一直被那個「白惡魔」騙了。",
  ui_story_5053_50531401_2_dialog_content = "「黑天使」和「白惡魔」，都是約書亞的一部分，但她們無法和解。",
  ui_story_5053_50531401_3_dialog_content = "所以打算殺死我們，吸收光能，才能獲得自由……",
  ui_story_5053_50531401_4_dialog_content = "雖然聽起來有點不可思議，但我能理解。",
  ui_story_5053_50531401_5_dialog_content = "那種腦袋像是要裂開一般的痛苦，畏懼另一個自己的感覺……",
  ui_story_5053_50531401_6_dialog_content = "但是就像我和芭芭雅嘎一樣，兩個人格都是「我」的一部分。",
  ui_story_5053_50531401_7_dialog_content = "我們可以彼此接納，媽媽她也一定……",
  ui_story_5053_50531401_8_dialog_content = "PlayerName，你覺得我們還有機會說服「白惡魔」嗎？",
  ui_story_5053_50531401_9_dialog_content = "哎……這大概只有約書亞夫人本人才能知道了。",
  ui_story_5053_50531401_10_dialog_content = "我只知道，永憶鏡晶內的光能即將耗盡。",
  ui_story_5053_50531401_11_dialog_content = "這是我們最後的機會，容不得我們多想了。",
  ui_story_5053_50531401_12_dialog_content = "萬分抱歉，我沒能捉住另一位夫人。",
  ui_story_5053_50531401_13_dialog_content = "剛剛衛兵傳來消息，廣場那邊已經進入了穩定的防守階段。",
  ui_story_5053_50531401_14_dialog_content = "只是面對飛龍不間斷的進攻，不知守軍還能支撐多久。",
  ui_story_5053_50531401_15_dialog_content = "辛苦妳了紅女士，之後的事情就交給我們吧。妳可以去休息了。",
  ui_story_5053_50531401_16_dialog_content = "那怎麼行呢？",
  ui_story_5053_50531401_17_dialog_content = "我的職責就是保護白夜城以及舒瓦茲一家。",
  ui_story_5053_50531401_18_dialog_content = "哪怕我只是幻境中的一縷幻影，只要我還是「紅女士」，這點就不會變。",
  ui_story_5053_50531401_19_dialog_content = "居然連自己只是幻影的事實都能立即接受，妳的泰然自若真是令我佩服。",
  ui_story_5053_50531401_20_dialog_content = "呵呵，在知道這件事之後，我反而有種釋然的感覺呢。",
  ui_story_5053_50531401_21_dialog_content = "看來，當一個沒有未來的幻影，要比做一個時刻擔憂未來的人輕鬆不少。",
  ui_story_5053_50531401_22_dialog_content = "比起我，剛得知真相的凱萊布先生要難受得多吧。",
  ui_story_5053_50531401_23_dialog_content = "約書亞她……不希望任何人知道她的過去。",
  ui_story_5053_50531401_24_dialog_content = "一方面，她的過去會引起許多非議。",
  ui_story_5053_50531401_25_dialog_content = "另一方面，她或許也沒有勇氣向弟弟揭露這個真相。",
  ui_story_5053_50531401_26_dialog_content = "這麼多年來，她變得開朗了許多，但心中也滋生了懦弱。",
  ui_story_5053_50531401_27_dialog_content = "我知道您的意思是「夫人的情感比以前更加豐富了，這是件好事」。",
  ui_story_5053_50531401_28_dialog_content = "「但有時，真誠而勇敢的交流才能解決問題。」",
  ui_story_5053_50531401_29_dialog_content = "希望等夫人在現實世界醒來後，您能向她好好傳達這些想法。",
  ui_story_5053_50531401_30_dialog_content = "不然剛醒來的夫人，會被您氣得再次昏倒的。",
  ui_story_5053_50531401_31_dialog_content = "……我會記得的。",
  ui_story_5053_50531401_32_dialog_content = "城主大人，您和紅女士聊完了嗎？我們想和您商量一下之後的對策。",
  ui_story_5053_50531401_33_dialog_content = "沒問題。",
  ui_story_5053_50531401_34_dialog_content = "……凱萊布呢？他好點了嗎？",
  ui_story_5053_50531401_35_dialog_content = "先讓他一個人靜一靜吧。",
  ui_story_5053_50531401_36_dialog_content = "……",
  ui_story_5053_50531401_37_dialog_content = "姐姐，妳是姐姐對吧……？",
  ui_story_5053_50531401_38_dialog_content = "——！",
  ui_story_5053_50531401_39_dialog_content = "為什麼要躲開？",
  ui_story_5053_50531401_40_dialog_content = "難道妳真的……像另一個妳說的那樣，從未把我當做過家人嗎？",
  ui_story_5053_50531401_41_dialog_content = "不……",
  ui_story_5053_50531401_42_dialog_content = "害怕……我……害怕……",
  ui_story_5053_50531401_43_dialog_content = "害怕？",
  ui_story_5053_50531401_44_dialog_content = "凱萊布……喜歡姐姐……相信姐姐……",
  ui_story_5053_50531401_45_dialog_content = "胸好悶……頭好痛……壓力……喘不上氣……",
  ui_story_5053_50531401_46_dialog_content = "爸爸……放下仇恨……為了保護我們……死了……都怪我……",
  ui_story_5053_50531401_47_dialog_content = "什麼意思……？",
  ui_story_5053_50531401_48_dialog_content = "另一個妳說，父親是為了保護復仇的火苗才選擇自盡。",
  ui_story_5053_50531401_49_dialog_content = "但妳卻說父親已經放下了仇恨……到底哪個才是真相，我已經分不清楚了。",
  ui_story_5053_50531401_50_dialog_content = "為了暗殺舒瓦茲的父親，妳一直假扮成我的姐姐。",
  ui_story_5053_50531401_51_dialog_content = "就像親姐姐……不，就像親生母親一樣，無微不至地照顧著我。",
  ui_story_5053_50531401_52_dialog_content = "而我又那麼喜歡黏著妳，妳壓力一定很大吧。",
  ui_story_5053_50531401_53_dialog_content = "……算了。姐姐，對我來說，妳的幸福永遠都是最重要的。",
  ui_story_5053_50531401_54_dialog_content = "如果妳真的不喜歡我，出去之後我再也不會糾纏妳了。去自由過妳想過的生活吧。",
  ui_story_5053_50531401_55_dialog_content = "不……不……別離開……我……",
  ui_story_5053_50531401_56_dialog_content = "我……欺騙……內心……醜陋……我……害怕……",
  ui_story_5053_50531401_57_dialog_content = "害怕……你……討厭……我……",
  ui_story_5053_50531401_58_dialog_content = "……",
  ui_story_5053_50531401_59_dialog_content = "怎麼會呢。",
  ui_story_5053_50531401_60_dialog_content = "姐姐是這世界上最漂亮、最溫柔的人。",
  ui_story_5053_50531401_61_dialog_content = "我怎麼可能會討厭妳呢。",
  ui_story_5053_50531401_62_dialog_content = "那就，我來總結一下剛剛大家討論的內容。",
  ui_story_5053_50531401_63_dialog_content = "到現在為止，我們已經阻止了「白惡魔」的所有計劃。",
  ui_story_5053_50531401_64_dialog_content = "走投無路的「白惡魔」，大概會利用被她控制的人群和飛龍發動最後的攻擊。",
  ui_story_5053_50531401_65_dialog_content = "雖然我們現在一個不少，且小舒瓦茲舉白夜城上下之力拖住了她的攻勢。",
  ui_story_5053_50531401_66_dialog_content = "但永憶鏡晶所剩的光能，應該不足以讓他們和飛龍全力一戰。",
  ui_story_5053_50531401_67_dialog_content = "而這一天的時限也只剩下幾個小時。",
  ui_story_5053_50531401_68_dialog_content = "我們首先需要一個簡單有效的方法，在短時間內徹底解決白惡魔的這些棋子。",
  ui_story_5053_50531401_69_dialog_content = "這樣才有機會活捉「白惡魔」。",
  ui_story_5053_50531401_70_dialog_content = "加晴手裡的這個「永憶鏡晶」還有其他功能嗎？比如說像「白惡魔」一樣操縱幻影之類的……",
  ui_story_5053_50531401_71_dialog_content = "嗯～不行！一方面現在「永憶鏡晶」內的光能已經不足以支撐許多功能了。",
  ui_story_5053_50531401_72_dialog_content = "另一方面，這個「永憶鏡晶」說到底只是個緊急避難裝置。",
  ui_story_5053_50531401_73_dialog_content = "照理說它不應該這樣頻繁使用……我們已經拿它做太多設計之外的事情了。",
  ui_story_5053_50531401_74_dialog_content = "真的不行的話，我再編個咒語試試看……！",
  ui_story_5053_50531401_75_dialog_content = "算了吧，加晴。現在情況緊急，容不得節外生枝了。",
  ui_story_5053_50531401_76_dialog_content = "嘿、嘿嘿……好的。",
  ui_story_5053_50531401_77_dialog_content = "用不著那麼麻煩。",
  ui_story_5053_50531401_78_dialog_content = "讓他們自相殘殺就好了。",
  ui_story_5053_50531401_79_dialog_content = "呦，凱萊布你哭完啦？",
  ui_story_5053_50531401_80_dialog_content = "誰哭了！妳當我三歲小孩啊！",
  ui_story_5053_50531401_81_dialog_content = "自相殘殺？他們都受「白惡魔」控制，要怎樣才能讓他們自相殘殺呢？",
  ui_story_5053_50531401_82_dialog_content = "簡單至極。",
  ui_story_5053_50531401_83_dialog_content = "只要能破壞體內光能的平衡，他們就會痛苦得失去控制自身的能力。",
  ui_story_5053_50531401_84_dialog_content = "光能的平衡？我還是第一次聽到這種說法。",
  ui_story_5053_50531401_85_dialog_content = "哼，一般光靈不會懂，但那邊的空裔一定曉得我在說什麼吧？",
  ui_story_5053_50531401_86_dialog_content = "我？呃……我的確能看到一些光的奇妙區別。",
  ui_story_5053_50531401_87_dialog_content = "這是什麼模棱兩可的說法……真令人失望。",
  ui_story_5053_50531401_88_dialog_content = "<size=30>PlayerName，我之前就覺得凱萊布對我們說話越來越不客氣了。難道這人真的是個性上有缺陷？</size>",
  ui_story_5053_50531401_89_dialog_content = "<size=30>哈哈哈哈……我不好說……</size>",
  ui_story_5053_50531401_90_dialog_content = "那邊的！上課不准竊竊私語！",
  ui_story_5053_50531401_91_dialog_content = "切入重點吧，凱萊布，說出你的計畫。",
  ui_story_5053_50531401_92_dialog_content = "我可以調製一種藥劑，令使用者的光能失衡。你們可以理解成一種「針對光能的毒藥」。",
  ui_story_5053_50531401_93_dialog_content = "「永憶鏡晶」中的人事物，都是光能和鏡湖之水交互作用下產生的幻影。",
  ui_story_5053_50531401_94_dialog_content = "這種藥劑對他們應該同樣有效。",
  ui_story_5053_50531401_95_dialog_content = "鑒於身上帶的材料有限，我打算針對那隻飛龍下手。",
  ui_story_5053_50531401_96_dialog_content = "其他的喪屍對牠來說不過是一群螻蟻，只要牠因為痛苦而在廣場上隨意大鬧——",
  ui_story_5053_50531401_97_dialog_content = "那麼另一個姐姐的棋子，也就徹底報廢了吧。",
  ui_story_5053_50531401_98_dialog_content = "嗯～也就是說，我們餵飛龍瀉藥，讓牠痛得滿地打滾吧！",
  ui_story_5053_50531401_99_dialog_content = "……妳就當做是這樣吧。",
  ui_story_5053_50531401_100_dialog_content = "這計畫的確很有你的作風，從小你就喜歡用這種簡單而陰險的招數。",
  ui_story_5053_50531401_101_dialog_content = "哎呀，城主大人居然還記得那件事，那杯紅茶就這麼令您難忘嗎？",
  ui_story_5053_50531401_102_dialog_content = "（這意思是……凱萊布以前給城主大人偷餵過瀉藥嗎？！）",
  ui_story_5053_50531401_103_dialog_content = "<size=30>凱萊布果真是個性有缺陷！</size>",
  ui_story_5053_50531401_104_dialog_content = "噗……哈哈……",
  ui_story_5053_50531401_105_dialog_content = "蜜雅，別笑了。",
  ui_story_5053_50531401_106_dialog_content = "對、對不起，我忍不住……不，我沒有那個意思……",
  ui_story_5053_50531401_107_dialog_content = "藥劑只有一瓶，機會只有一次。我需要一個強大的戰士幫我牽制飛龍。妳來幫我。",
  ui_story_5053_50531401_108_dialog_content = "哎？強大的戰士……我？？",
  ui_story_5053_50531401_109_dialog_content = "對，快跟我走。",
  ui_story_5053_50531401_110_dialog_content = "呀！等等……",
  ui_story_5053_50531401_111_dialog_content = "凱萊布這人又自顧自地跑了！怎麼辦，我們也跟上去嗎？",
  ui_story_5053_50531401_112_dialog_content = "飛龍那邊就交給凱萊布吧。我相信他，也相信蜜雅。",
  ui_story_5053_50531401_113_dialog_content = "城主大人，您……",
  ui_story_5053_50531401_114_dialog_content = "照你所說，我每次都能在「白惡魔」的陰謀中活到最後。但我每次都沒能改變結局。",
  ui_story_5053_50531401_115_dialog_content = "反倒是你們這些年輕人的活躍，總能替事情帶來不一樣的轉機。",
  ui_story_5053_50531401_116_dialog_content = "我一直覺得自己應該保護一切……但或許，是時候放下這種傲慢了。",
  ui_story_5053_50531401_117_dialog_content = "那我們就繼續留在這裡？",
  ui_story_5053_50531401_118_dialog_content = "是的，我們留在這裡靜觀其變。",
  ui_story_5053_50531401_119_dialog_content = "以我對她的瞭解，底牌被抽光後，她一定會主動現身，和我們拼死一搏。",
  ui_story_5053_50531401_120_dialog_content = "她就是這麼頑強的人。",
  ui_story_5053_50531401_121_dialog_content = "而且……",
  ui_story_5053_50531401_122_dialog_content = "…………",
  ui_story_5053_50531401_123_dialog_content = "我還必須說服她。",
  ui_story_5053_50531401_125_dialog_content = "我們又回到這裡了。夜晚，餐桌，妳和我。",
  ui_story_5053_50531401_126_dialog_content = "……",
  ui_story_5053_50531401_127_dialog_content = "之前我扮成年輕的自己，想要改變當年不歡而散的結局。",
  ui_story_5053_50531401_128_dialog_content = "說是不想讓妳再受到傷害，但在這幻境之中，何嘗不是種自我滿足呢。",
  ui_story_5053_50531401_129_dialog_content = "諷刺的是，原來妳就在我眼前，而我的卑劣被妳一覽無遺。也怪不得妳會生氣了。",
  ui_story_5053_50531401_130_dialog_content = "狄安理……",
  ui_story_5053_50531401_131_dialog_content = "沒錯，這一切都是我的錯。我的人頭妳隨時可以拿去。只是不是現在。",
  ui_story_5053_50531401_132_dialog_content = "那些孩子們是無辜的，他們得離開這裡。",
  ui_story_5053_50531401_133_dialog_content = "所以，可以幫我們抓住另一個妳，和我們一起離開這個世界嗎？",
  ui_story_5053_50531401_134_dialog_content = "孩子們……未來……保護……未來……",
  ui_story_5053_50531401_135_dialog_content = "看來妳同意了。謝謝妳，約書亞……也謝謝妳，願意再相信我一次。",
  ui_story_5053_50531401_136_dialog_content = "……",
  ui_story_5053_50531401_137_dialog_content = "凱萊布他們才出發不久，我們還可以再休息一段時間。",
  ui_story_5053_50531401_138_dialog_content = "約書亞，我聽說妳還記得那首歌是嗎？",
  ui_story_5053_50531401_139_dialog_content = "下城……區……的歌……幸福……生活的……歌……",
  ui_story_5053_50531401_140_dialog_content = "對，就是那首。其實我十二年前曾準備了一份禮物給妳。",
  ui_story_5053_50531401_141_dialog_content = "可惜因為一時衝動，錯過了送給妳的機會。我記得……對，就在這裡。",
  ui_story_5053_50531401_142_dialog_content = "唱……片？",
  ui_story_5053_50531401_143_dialog_content = "對，是唱片。我請人將那首歌改編成舞曲的版本。好奇嗎？正好這裡有唱片機。",
  ui_story_5053_50531401_144_dialog_content = "<color=#e8d9bb>~♪</color>",
  ui_story_5053_50531401_145_dialog_content = "……！",
  ui_story_5053_50531401_146_dialog_content = "看來妳很喜歡，真是太好了。",
  ui_story_5053_50531401_147_dialog_content = "這是首舞曲，只是坐著欣賞未免有些無趣。",
  ui_story_5053_50531401_148_dialog_content = "那麼，美麗的女士，可以與我共舞一曲嗎？",
  ui_story_5053_50531401_149_dialog_content = "……",
  ui_story_5053_50531401_150_dialog_content = "……",
  ui_story_5053_50531401_151_dialog_content = "狄安理……",
  ui_story_5053_50531401_152_dialog_content = "怎麼了？",
  ui_story_5053_50531401_153_dialog_content = "大家……過得……好嗎……？",
  ui_story_5053_50531401_154_dialog_content = "……嗯，還好。",
  ui_story_5053_50531401_155_dialog_content = "卡蓮現在已是城中的衛隊隊長。除了出色的部下，也交了很多的朋友。",
  ui_story_5053_50531401_156_dialog_content = "蜜雅依舊由伊斯塔萬照顧。她的病情已經好轉許多，聽說已經能在白天的街上玩耍了。",
  ui_story_5053_50531401_157_dialog_content = "凱萊布……聽說他在黎明學院幹得不錯。他很想妳，這份思念或許勝過我們任何一個人。",
  ui_story_5053_50531401_158_dialog_content = "你……呢……？",
  ui_story_5053_50531401_159_dialog_content = "我？",
  ui_story_5053_50531401_160_dialog_content = "現在已經不是我的時代了。",
  ui_story_5053_50531401_161_dialog_content = "過去的我很無能，犯下許多錯誤。現在孩子們正踩著我的肩膀，邁向更高的地方。",
  ui_story_5053_50531401_162_dialog_content = "我所能做的，就只有堅持站在這裡，托舉著他們，讓他們走向更遠的未來。",
  ui_story_5053_50531401_163_dialog_content = "直到妳我理想中的那個世界變為現實的那一天。",
  ui_story_5053_50531401_164_dialog_content = "妳回來之後，我可以讓妳在凱萊布的家繼續修養。",
  ui_story_5053_50531401_165_dialog_content = "然後把薇羅妮卡接回來和妳同住，把這個好消息告訴卡蓮。這樣一家人又可以在一起了。",
  ui_story_5053_50531401_166_dialog_content = "只是……哈哈，我已經老了，或許配不上妳了。如果妳不嫌棄的話，能否讓我偶爾去看看妳呢？",
  ui_story_5053_50531401_167_dialog_content = "想……家……",
  ui_story_5053_50531401_168_dialog_content = "約書亞？",
  ui_story_5053_50531401_169_dialog_content = "我想……回家……",
  ui_story_5053_50531401_170_dialog_content = "嗯，我們一起回家。",
  ui_story_5053_50531401_171_dialog_content = "……約書亞，妳後悔嗎？",
  ui_story_5053_50531401_172_dialog_content = "如果妳一直都這麼痛苦、這麼憤怒。那麼妳……後悔當初選擇我嗎？",
  ui_story_5053_50531401_173_dialog_content = "幸福……愛……都是你教會我的。",
  ui_story_5053_50531401_174_dialog_content = "恨……是愛的反面。",
  ui_story_5053_50531401_175_dialog_content = "恨，很痛苦……但……也是因為深沉的愛……所以，我不後悔。",
  ui_story_5053_50531401_176_dialog_content = "…………",
  ui_story_5053_50531401_177_dialog_content = "是嗎。",
  ui_story_5053_50531401_178_dialog_content = "這樣啊……",
  ui_story_5053_50531401_179_dialog_content = "第五處設置完畢，第六處設置完畢……",
  ui_story_5053_50531401_180_dialog_content = "好了，引導飛龍的炸彈全部設完，就差引爆裝置了。",
  ui_story_5053_50531401_181_dialog_content = "凱萊布先生，炸彈布得還順利嗎？需要我的幫助嗎？",
  ui_story_5053_50531401_182_dialog_content = "不用，我已經搞定了。",
  ui_story_5053_50531401_183_dialog_content = "這麼短時間內就搞定了，真不愧是您。",
  ui_story_5053_50531401_184_dialog_content = "親戚之間的恭維話就免了吧。而且，真正值得稱讚的是妳。",
  ui_story_5053_50531401_185_dialog_content = "沒有妳在，衛兵不可能給我們一路放行。",
  ui_story_5053_50531401_186_dialog_content = "分內之事而已。不過，兩位真的不需要我的幫助嗎？",
  ui_story_5053_50531401_187_dialog_content = "身為「永憶鏡晶」內的幻影，我更適合執行牽制敵人的危險任務。",
  ui_story_5053_50531401_188_dialog_content = "別這麼說，紅女士……",
  ui_story_5053_50531401_189_dialog_content = "而且我有件更重要的事需要麻煩妳。",
  ui_story_5053_50531401_190_dialog_content = "為您效勞，公主殿下。",
  ui_story_5053_50531401_191_dialog_content = "可以去替我陪陪小卡蓮嗎？她現在一個人待著，一定很不安吧。",
  ui_story_5053_50531401_192_dialog_content = "沒問題。只是我想問您……",
  ui_story_5053_50531401_193_dialog_content = "我們只是一群幻影，為何您還要如此關心我們呢。",
  ui_story_5053_50531401_194_dialog_content = "不……你們和我的重要之人有著一樣的面容，一樣的人格，一樣的記憶。",
  ui_story_5053_50531401_195_dialog_content = "雖然生命的存在形式不同，但我對你們抱有相同的情感。",
  ui_story_5053_50531401_196_dialog_content = "在我看來，我們之間的情感沒有「真實」和「虛擬」的區別。",
  ui_story_5053_50531401_197_dialog_content = "而且我不喜歡思考什麼可以犧牲，什麼不重要……",
  ui_story_5053_50531401_198_dialog_content = "總是想這些，我怕我會迷失初心。",
  ui_story_5053_50531401_199_dialog_content = "蜜雅公主，以前我就覺得您很像約書亞夫人，現在更像了。",
  ui_story_5053_50531401_200_dialog_content = "是......是嗎？",
  ui_story_5053_50531401_201_dialog_content = "一切就緒，該行動了，蜜雅！",
  ui_story_5053_50531401_202_dialog_content = "好的，我來了！那麼卡蓮就麻煩妳了！",
  ui_story_5053_50531401_203_dialog_content = "看來無需我的祈禱，光就已照耀了舒瓦茲一族的未來啊。",
  ui_story_5053_50531401_204_dialog_content = "吸......呼......",
  ui_story_5053_50531401_205_dialog_content = "一旦我按下手中的按鈕，炸彈就會逐一引爆，飛龍會在二十秒內被誘導到我們面前。",
  ui_story_5053_50531401_206_dialog_content = "蜜雅，妳準備好了嗎？",
  ui_story_5053_50531401_207_dialog_content = "算、算是吧……",
  ui_story_5053_50531401_208_dialog_content = "哎……怎麼到了這個節骨眼，妳還是一副沒自信的樣子。",
  ui_story_5053_50531401_209_dialog_content = "打起精神來！",
  ui_story_5053_50531401_210_dialog_content = "抱歉……那個，舅父……",
  ui_story_5053_50531401_211_dialog_content = "長話短說。",
  ui_story_5053_50531401_212_dialog_content = "您為什麼挑我來協助您完成計畫呢。",
  ui_story_5053_50531401_213_dialog_content = "需要強大的戰士的話，父親和紅女士應該比我更適合。",
  ui_story_5053_50531401_214_dialog_content = "嗯？妳為什麼會這麼覺得？",
  ui_story_5053_50531401_215_dialog_content = "歷經一路冒險，妳的實力我已心裡有數，而且聽說妳還有個光能召喚物。",
  ui_story_5053_50531401_216_dialog_content = "牠讓妳在機動性方面更具優勢，沒人比妳更適合這個計畫了。",
  ui_story_5053_50531401_217_dialog_content = "召、召喚物？！",
  ui_story_5053_50531401_218_dialog_content = "我沒怎麼召喚過希頗喀，不一定能好好駕馭牠……",
  ui_story_5053_50531401_219_dialog_content = "沒怎麼召喚過？明明有這種難得的天賦，妳為什麼不用？",
  ui_story_5053_50531401_220_dialog_content = "因為……希頗喀長得太可怕，大家都畏懼牠，說牠是不祥的象徵。",
  ui_story_5053_50531401_221_dialog_content = "不過我現在已經不這麼想了！我不會再為別人的話而輕易懷疑自己了。",
  ui_story_5053_50531401_222_dialog_content = "只是，我和希頗喀一起戰鬥的經驗真的不多，心裡有點沒底……",
  ui_story_5053_50531401_223_dialog_content = "如果我們失敗了，大家的性命可能就……",
  ui_story_5053_50531401_224_dialog_content = "呵，原來如此，是舒瓦茲幹的吧？",
  ui_story_5053_50531401_225_dialog_content = "……",
  ui_story_5053_50531401_226_dialog_content = "因為那些貴族的閒言碎語，就不讓妳使用召喚物。",
  ui_story_5053_50531401_227_dialog_content = "他是不是以為這樣就能讓召喚物背負一切罵名，讓妳遠離非議？",
  ui_story_5053_50531401_228_dialog_content = "哎？父親是為了保護我，才這麼做的嗎……？",
  ui_story_5053_50531401_229_dialog_content = "<size=45>無聊！無聊透頂！！</size>",
  ui_story_5053_50531401_230_dialog_content = "哎……？！",
  ui_story_5053_50531401_231_dialog_content = "聽好了，蜜雅，那些貴族說妳壞話是因為嫉妒妳。妳越是出眾，庸人就越愛詆毀妳。",
  ui_story_5053_50531401_232_dialog_content = "所以別聽舒瓦茲亂說，別人不讓妳幹什麼，妳就偏要幹什麼！！這才是天才的處世之道！",
  ui_story_5053_50531401_233_dialog_content = "天、天才的處世之道？呃，我覺得，身邊人的意見還是多少得聽……",
  ui_story_5053_50531401_234_dialog_content = "不對，蜜雅妳就是長期被人打壓，所以才會這麼想。來，舅父教妳。",
  ui_story_5053_50531401_235_dialog_content = "現在妳就釋放出所有的力量，讓力量支配身體，感受自己的全部！",
  ui_story_5053_50531401_236_dialog_content = "哎…………？？",
  ui_story_5053_50531401_237_dialog_content = "對妳這種過分拘謹的人，就得來一帖猛藥。",
  ui_story_5053_50531401_238_dialog_content = "妳必須完全掌握自己的所有力量，今後才更能好好運用。",
  ui_story_5053_50531401_239_dialog_content = "完全掌握所有力量……",
  ui_story_5053_50531401_240_dialog_content = "（人會恐懼未知的東西，所以我才會害怕。）",
  ui_story_5053_50531401_241_dialog_content = "（雖然舅父的方法有點過於奔放了……但我的確需要掌握自己的力量。）",
  ui_story_5053_50531401_242_dialog_content = "放心，還有我在呢。難道妳以為我是個只會搞學術的草包嗎？",
  ui_story_5053_50531401_243_dialog_content = "我、我沒這麼想過呀！那就聽舅父的……我會使出全力！",
  ui_story_5053_50531401_244_dialog_content = "這才對！",
  ui_story_5053_50531401_245_dialog_content = "那麼，作戰正式開始！",
  ui_story_5053_50531501_1_dialog_content = "<color=#e8d9bb>吼嗚——</color>",
  ui_story_5053_50531501_2_dialog_content = "好淒厲的叫聲，從宅邸也能聽得一清二楚。",
  ui_story_5053_50531501_3_dialog_content = "從爆炸開始已經過去了三分鐘，期間兩種不同顏色的火焰一直在空中碰撞。",
  ui_story_5053_50531501_4_dialog_content = "藍色的是蜜雅，紅色的是飛龍……",
  ui_story_5053_50531501_5_dialog_content = "啊……！！紅色的火焰墜落了！凱萊布和蜜雅成功了！",
  ui_story_5053_50531501_6_dialog_content = "看來我們來得正好。",
  ui_story_5053_50531501_7_dialog_content = "是的！我正想下去通知您。",
  ui_story_5053_50531501_8_dialog_content = "您和她談妥了嗎？",
  ui_story_5053_50531501_9_dialog_content = "嗯，這樣一來局勢就徹底逆轉了。",
  ui_story_5053_50531501_10_dialog_content = "棋盤上孤獨的白皇后，妳這最後一步棋會落在哪裡呢……",
  ui_story_5053_50531501_11_dialog_content = "來了！",
  ui_story_5053_50531501_12_dialog_content = "嗯？什麼來了？",
  ui_story_5053_50531501_13_dialog_content = "「她來了。」",
  ui_story_5053_50531501_14_dialog_content = "地震了？！還有這裂痕……「白惡魔」要來了嗎！！",
  ui_story_5053_50531501_15_dialog_content = "PlayerName！",
  ui_story_5053_50531501_16_dialog_content = "可惡，這到底是怎麼回事！",
  ui_story_5053_50531501_17_dialog_content = "蜜雅和凱萊布，你們不是剛搞定飛龍嗎？怎麼這麼快就回來了！",
  ui_story_5053_50531501_18_dialog_content = "不是的，我們也不知道這是怎麼回事。",
  ui_story_5053_50531501_19_dialog_content = "飛龍倒下之後，中央廣場突然開始扭曲崩潰，除了我和舅父……",
  ui_story_5053_50531501_20_dialog_content = "周圍所有人都化為白光飛到天上。",
  ui_story_5053_50531501_21_dialog_content = "我們一路逃跑，隨手打開一扇住宅的門之後，突然就回到了宅邸。",
  ui_story_5053_50531501_22_dialog_content = "呼……",
  ui_story_5053_50531501_23_dialog_content = "加晴，別睡了！出大事了！",
  ui_story_5053_50531501_24_dialog_content = "嗯？啊？誰啊！不准動我懷裡的「永憶鏡晶」！",
  ui_story_5053_50531501_25_dialog_content = "……永、「永憶鏡晶」怎麼變成這樣了？！",
  ui_story_5053_50531501_26_dialog_content = "啊……為什麼……",
  ui_story_5053_50531501_27_dialog_content = "為什麼，你們會選擇那個骯髒醜陋的東西……",
  ui_story_5053_50531501_28_dialog_content = "媽媽……妳的臉……",
  ui_story_5053_50531501_29_dialog_content = "她臉上破碎的地方，露出了和「黑天使」一樣的顏色？！",
  ui_story_5053_50531501_30_dialog_content = "為什麼沒人選擇我……？",
  ui_story_5053_50531501_31_dialog_content = "為什麼沒人明白「理想」有多重要……",
  ui_story_5053_50531501_32_dialog_content = "<size=45>為什麼！！！</size>",
  ui_story_5053_50531501_33_dialog_content = "怎、怎麼妳也變成「黑天使」了？！",
  ui_story_5053_50531501_34_dialog_content = "看來蜜雅說得沒錯，兩個人格本質都是一樣的……",
  ui_story_5053_50531501_35_dialog_content = "哎，可惜我們沒空勸她乖乖投降了！小占卜球！",
  ui_story_5053_50531501_36_dialog_content = "唔，媽媽……對不起了！",
  ui_story_5053_50531501_37_dialog_content = "姐姐……",
  ui_story_5053_50531501_38_dialog_content = "凱萊布，事到如今你還在猶豫嗎？",
  ui_story_5053_50531501_39_dialog_content = "看你這樣子，簡直還不如我那膽小的大女兒。",
  ui_story_5053_50531501_40_dialog_content = "少廢話！在姐姐的事情上，唯獨你舒瓦茲沒資格指責任何人！！",
  ui_story_5053_50531501_41_dialog_content = "出去了我再找你算帳！給我等著！",
  ui_story_5053_50531501_42_dialog_content = "（傻小子，這麼多年了還是禁不住一點激將法。）",
  ui_story_5053_50531501_43_dialog_content = "……",
  ui_story_5053_50531502_1_dialog_content = "唔……！！",
  ui_story_5053_50531502_2_dialog_content = "加晴！",
  ui_story_5053_50531502_3_dialog_content = "好！",
  ui_story_5053_50531502_4_dialog_content = "別過來……",
  ui_story_5053_50531502_5_dialog_content = "放棄吧，姐姐。",
  ui_story_5053_50531502_6_dialog_content = "別過來……！",
  ui_story_5053_50531502_7_dialog_content = "繼續掙扎只會讓妳更痛苦而已。",
  ui_story_5053_50531502_8_dialog_content = "不要過來！！！",
  ui_story_5053_50531502_9_dialog_content = "城主大人！",
  ui_story_5053_50531502_10_dialog_content = "<size=45>「主宰之刃」——</size>",
  ui_story_5053_50531502_11_dialog_content = "呃啊！！",
  ui_story_5053_50531502_12_dialog_content = "都……怪妳……",
  ui_story_5053_50531502_13_dialog_content = "……",
  ui_story_5053_50531502_14_dialog_content = "都怪妳……我才會變弱……",
  ui_story_5053_50531502_15_dialog_content = "蜜雅、卡蓮、凱萊布、白蘭……舒瓦茲。",
  ui_story_5053_50531502_16_dialog_content = "他們全都是瑕疵品！全都是叛徒！！",
  ui_story_5053_50531502_17_dialog_content = "妳卻要因為他們而放棄「理想」？！妳這歪門邪道的東西——",
  ui_story_5053_50531502_18_dialog_content = "蜜雅，跟我一起壓住她吧，別讓她繼續傷害自己了。",
  ui_story_5053_50531502_19_dialog_content = "好……",
  ui_story_5053_50531502_20_dialog_content = "慢著！別靠近她！",
  ui_story_5053_50531502_21_dialog_content = "既然……如此……為了大義……",
  ui_story_5053_50531502_22_dialog_content = "我要剷除你們……",
  ui_story_5053_50531502_23_dialog_content = "……嗯？起風了？",
  ui_story_5053_50531502_24_dialog_content = "「永憶鏡晶」內的光能都開始往她身上聚集了！！",
  ui_story_5053_50531502_25_dialog_content = "她這是……想要和我們同歸於盡嗎？！",
  ui_story_5053_50531502_26_dialog_content = "加晴，準備送我們出去！其他人一起壓制她！",
  ui_story_5053_50531502_27_dialog_content = "哎？現在？！",
  ui_story_5053_50531502_28_dialog_content = "你打算這樣直接把姐姐帶出去嗎？！",
  ui_story_5053_50531502_29_dialog_content = "如果放任她傷害你們，只會讓約書亞心碎。",
  ui_story_5053_50531502_30_dialog_content = "所有玷污理想的背叛者，都給我去死吧！！！",
  ui_story_5053_50531502_31_dialog_content = "媽媽，為什麼妳要做到這個地步，難道妳心底深處就這麼恨我們嗎……",
  ui_story_5053_50531502_32_dialog_content = "小薇……別難過……",
  ui_story_5053_50531502_33_dialog_content = "交給我……",
  ui_story_5053_50531502_34_dialog_content = "媽媽……？",
  ui_story_5053_50531502_35_dialog_content = "嘖，攻擊沒有用！蜜雅別發呆了，給我專心戰鬥……",
  ui_story_5053_50531502_36_dialog_content = "姐姐？等等，妳要做什麼？！別靠近另一個妳！",
  ui_story_5053_50531502_37_dialog_content = "……凱萊布，相信她吧。",
  ui_story_5053_50531502_38_dialog_content = "別攔著我，舒瓦茲！放開我！姐姐！！！",
  ui_story_5053_50531502_39_dialog_content = "風好大，我的眼睛都要睜不開了！這樣根本沒辦法驅動「永憶鏡晶」啦！",
  ui_story_5053_50531502_40_dialog_content = "嗚哇？！我我我我飛起來了，救命——",
  ui_story_5053_50531502_41_dialog_content = "加晴！",
  ui_story_5053_50531502_42_dialog_content = "呼～謝了，PlayerName……啊？",
  ui_story_5053_50531502_43_dialog_content = "別怕……已經沒事了。",
  ui_story_5053_50531502_44_dialog_content = "這一次一定要緊緊抓住大家的手，千萬不能放開喔。",
  ui_story_5053_50531502_45_dialog_content = "姐、姐姐……？",
  ui_story_5053_50531502_46_dialog_content = "媽媽……是媽媽的臉……",
  ui_story_5053_50531502_47_dialog_content = "妳……不要……過來……",
  ui_story_5053_50531502_48_dialog_content = "別鬧了，我們該放大家回家了。",
  ui_story_5053_50531502_49_dialog_content = "不要過來！！！",
  ui_story_5053_50531502_50_dialog_content = "<size=50>約書亞！！！</size>",
  ui_story_5053_50531601_1_dialog_content = "終於找到妳了。",
  ui_story_5053_50531601_2_dialog_content = "妳別過來！",
  ui_story_5053_50531601_3_dialog_content = "妳就這麼討厭我嗎？",
  ui_story_5053_50531601_4_dialog_content = "不然呢？妳也不照照鏡子，那副醜陋的樣子誰會喜歡。",
  ui_story_5053_50531601_5_dialog_content = "是嗎……其實我也是這麼想的。",
  ui_story_5053_50531601_6_dialog_content = "但我的家人還有朋友都是那麼喜歡我，所以我也開始喜歡上自己的這副樣子了。",
  ui_story_5053_50531601_7_dialog_content = "噁心……",
  ui_story_5053_50531601_8_dialog_content = "妳看過自己的樣子嗎？",
  ui_story_5053_50531601_9_dialog_content = "當然看過。為了訓練表情控制，我每天都會對著鏡子練習三個小時，早就看膩了。",
  ui_story_5053_50531601_10_dialog_content = "對，妳是個英勇的戰士，為了「理想」無所畏懼，什麼都能做到。",
  ui_story_5053_50531601_11_dialog_content = "但妳錯了。世上總會有令妳害怕的東西，比如說……",
  ui_story_5053_50531601_12_dialog_content = "爸爸的死。",
  ui_story_5053_50531601_13_dialog_content = "？！",
  ui_story_5053_50531601_14_dialog_content = "比如說，被孩子們和弟弟得知真相。",
  ui_story_5053_50531601_15_dialog_content = "胡說……",
  ui_story_5053_50531601_16_dialog_content = "比如說，和丈夫分道揚鑣。",
  ui_story_5053_50531601_17_dialog_content = "閉嘴。",
  ui_story_5053_50531601_18_dialog_content = "那是妳害怕的東西……不是我！只有妳才會有那些無聊的感情！",
  ui_story_5053_50531601_19_dialog_content = "我不需要這些東西……我會為了理想奉上一切，我不需要那些！",
  ui_story_5053_50531601_20_dialog_content = "是啊，妳活得非常單純。或許這種活法並不幸福，但妳也不會因為失去而感到痛苦。",
  ui_story_5053_50531601_21_dialog_content = "妳害怕知曉這種感覺，所以才將我趕出身體。",
  ui_story_5053_50531601_22_dialog_content = "閉嘴……別再說了，閉嘴……",
  ui_story_5053_50531601_23_dialog_content = "我才不相信他們，他們不聽我的話，他們會背叛我……",
  ui_story_5053_50531601_24_dialog_content = "人不是器物，每個人都有自己的想法。",
  ui_story_5053_50531601_25_dialog_content = "「自從我阻止妳那天起，我就開始不斷思考。」",
  ui_story_5053_50531601_26_dialog_content = "「我們這樣把夢想寄託於他人，是不是個錯誤的選擇。」",
  ui_story_5053_50531601_27_dialog_content = "妳還記得吧？這是狄安理曾說過的話。",
  ui_story_5053_50531601_28_dialog_content = "他是個騙子……",
  ui_story_5053_50531601_29_dialog_content = "是我們太依賴他了。是我們把自己的理想壓在他身上。",
  ui_story_5053_50531601_30_dialog_content = "妳比我更清楚，身為城主一家不可能擁有普通的幸福，我卻無法放下這份渴望。",
  ui_story_5053_50531601_31_dialog_content = "無情的刺客，完美的城主夫人……",
  ui_story_5053_50531601_32_dialog_content = "這些身分換來換去，全都是他人的附屬品，哪個都不是真正的我。",
  ui_story_5053_50531601_33_dialog_content = "真正的我，到底在哪裡呢。",
  ui_story_5053_50531601_34_dialog_content = "……",
  ui_story_5053_50531601_35_dialog_content = "但是我知道，現在我不想失去眼前珍視的人們。這份感受比什麼都要真切。",
  ui_story_5053_50531601_36_dialog_content = "所以，別鬧了，我們走吧。",
  ui_story_5053_50531601_37_dialog_content = "好痛！怎麼回事，妳的手像是長了刺一樣，一碰到就讓我覺得好痛！",
  ui_story_5053_50531601_38_dialog_content = "但是，又很溫暖……這種感覺是怎麼回事？",
  ui_story_5053_50531601_39_dialog_content = "呵呵，這種感覺就是<color=#FFB400>愛</color>啊。",
  ui_story_5053_50531601_40_dialog_content = "媽媽！媽媽妳在哪裡！！咳咳，媽媽！",
  ui_story_5053_50531601_41_dialog_content = "蜜雅！這邊，抓住我的手！",
  ui_story_5053_50531601_42_dialog_content = "PlayerName、大家……媽媽呢？",
  ui_story_5053_50531601_43_dialog_content = "她……爆炸之後就……",
  ui_story_5053_50531601_44_dialog_content = "加晴，快唸咒語。",
  ui_story_5053_50531601_45_dialog_content = "沒有姐姐我才不要離開！放開我！！",
  ui_story_5053_50531601_46_dialog_content = "地面開始崩潰了，趕快！",
  ui_story_5053_50531601_47_dialog_content = "（好、好……）",
  ui_story_5053_50531601_48_dialog_content = "艾·普勒俄森斯！",
  ui_story_5053_50531601_49_dialog_content = "讓我們回到現實中去吧！",
  ui_story_5053_50531601_50_dialog_content = "阿布拉卡達布拉！",
  ui_story_5053_50531601_51_dialog_content = "姐姐！我在這裡！！姐姐！！",
  ui_story_5053_50531601_52_dialog_content = "頑固的小子……加晴，抓緊蜜雅！",
  ui_story_5053_50531601_53_dialog_content = "你、你說什麼？風太大我聽不清楚！！",
  ui_story_5053_50531601_54_dialog_content = "我要抓不住你了！PlayerName！！",
  ui_story_5053_50531601_55_dialog_content = "啊！！！",
  ui_story_5053_50531601_56_dialog_content = "抓緊我。",
  ui_story_5053_50531601_57_dialog_content = "妳是......？",
  ui_story_5053_50531601_58_dialog_content = "「……，見信如晤。」",
  ui_story_5053_50531601_59_dialog_content = "「您最近過得還好嗎？我和大家過得都很好。」",
  ui_story_5053_50531601_60_dialog_content = "你在寫信？寫給誰呀？",
  ui_story_5053_50531601_61_dialog_content = "哇？！加晴妳嚇我一跳……",
  ui_story_5053_50531601_62_dialog_content = "嘿嘿，抱歉啦～",
  ui_story_5053_50531601_63_dialog_content = "PlayerName，午安呀。",
  ui_story_5053_50531601_64_dialog_content = "午安，你們來得真早啊，我還以為加晴又會遲到呢。",
  ui_story_5053_50531601_65_dialog_content = "誰叫我的專業知識這麼重要呢！每天都有一堆人排著隊問我問題，我忙都忙不過來啦～",
  ui_story_5053_50531601_66_dialog_content = "好好好，「黎明學院臨時顧問」加晴閣下。",
  ui_story_5053_50531601_67_dialog_content = "嘿嘿，說得這麼正式，怪不好意思的……",
  ui_story_5053_50531601_68_dialog_content = "蜜雅，妳那邊的事情都處理好了嗎？",
  ui_story_5053_50531601_69_dialog_content = "嗯，都處理好了。",
  ui_story_5053_50531601_70_dialog_content = "可惜卡蓮太忙了，沒機會和她道別了……",
  ui_story_5053_50531601_71_dialog_content = "放心，下次卡蓮來巨像玩的時候我通知妳，一定會讓你們見到面的。",
  ui_story_5053_50531601_72_dialog_content = "不用了，一切順其自然就好。",
  ui_story_5053_50531601_73_dialog_content = "是嗎……",
  ui_story_5053_50531601_74_dialog_content = "「自那之後，這裡發生了很多事情，許多人都做出了意想不到的決定。」",
  ui_story_5053_50531601_75_dialog_content = "「由於我答應過您要從頭將事情的原委梳理一遍，我們還是從最初講起吧。」",
  ui_story_5053_50531601_76_dialog_content = "「當時，我們成功離開了<color=#FFB400>『永憶鏡晶』</color>。」",
  ui_story_5053_50531601_77_dialog_content = "「顧不上檢查自己的身體狀況，凱萊布就衝出房門，跑回了自己家裡。」",
  ui_story_5053_50531601_78_dialog_content = "「而我們也跟著他……見到了他一直藏在家中的約書亞夫人。」",
  ui_story_5053_50531601_79_dialog_content = "媽媽的眼睛微微動了一下……！",
  ui_story_5053_50531601_80_dialog_content = "快把藥劑拿來！左邊的架子！",
  ui_story_5053_50531601_81_dialog_content = "等等，我還在找紗布啊！",
  ui_story_5053_50531601_82_dialog_content = "我來拿。",
  ui_story_5053_50531601_83_dialog_content = "「經過緊急搶救，約書亞夫人成功脫離了危險，並在數日後醒來。」",
  ui_story_5053_50531601_84_dialog_content = "「可是……她卻失去了所有的記憶。」",
  ui_story_5053_50531601_85_dialog_content = "為什麼會變成這樣？是因為長期的沉睡嗎？還是因為那最後的爆炸？",
  ui_story_5053_50531601_86_dialog_content = "不過姐姐身上人格分裂的傾向完全消失了，這到底是……",
  ui_story_5053_50531601_87_dialog_content = "喂，加晴，難道這和「永憶鏡晶」有關嗎？",
  ui_story_5053_50531601_88_dialog_content = "嗯～不太可能吧。",
  ui_story_5053_50531601_89_dialog_content = "什麼叫做「不太可能吧」？妳能不能認真點。",
  ui_story_5053_50531601_90_dialog_content = "「為了幫助約書亞夫人，也為了修好『永憶鏡晶』……」",
  ui_story_5053_50531601_91_dialog_content = "「加晴暫時留在白夜城，和凱萊布一起進行研究。」",
  ui_story_5053_50531601_92_dialog_content = "「為了哄加晴開心，凱萊布還給她了一個黎明學院臨時顧問的稱號。」",
  ui_story_5053_50531601_93_dialog_content = "「不過聽說這個稱號根本沒有實際意義，希望加晴不會發現這件事……」",
  ui_story_5053_50531601_94_dialog_content = "現在我們唯一知道的是，「白惡魔」和「黑天使」最後不知何故終於接納了彼此。",
  ui_story_5053_50531601_94X1_dialog_content = "於是雙重人格消失，約書亞夫人的精神就此恢復了正常。",
  ui_story_5053_50531601_95_dialog_content = "關於「種子」的問題還有許多地方需要深入研究，不過這方面就只能靠凱萊布了。",
  ui_story_5053_50531601_96_dialog_content = "有勞妳這幾日在白夜城中停留，協助凱萊布做研究，辛苦了，北境使者加晴。",
  ui_story_5053_50531601_97_dialog_content = "應該的～和大家出生入死這麼多次，我也不算是外人了呀！",
  ui_story_5053_50531601_98_dialog_content = "而且我明明是來替「永憶鏡晶」補充鏡湖之水的，結果卻把它弄壞了，這也說不過去呀……",
  ui_story_5053_50531601_99_dialog_content = "喔對，說到這個，「永憶鏡晶」已經修好了！現在約書亞夫人回來了，您真的可以隨時使用它了！",
  ui_story_5053_50531601_100_dialog_content = "謝謝妳。為了不讓他人再誤入其中，我會把它好好收起來的。",
  ui_story_5053_50531601_101_dialog_content = "哈哈哈……不過啊，其實我有點擔心凱萊布。自從約書亞夫人醒來之後，他就天天圍著夫人轉！",
  ui_story_5053_50531601_102_dialog_content = "聽說他還想辭去黎明學院的職位，專心留在家裡照顧約書亞夫人。哎，他到底行不行啊。",
  ui_story_5053_50531601_103_dialog_content = "這長不大的小子……加晴，聽說妳在尋找名為「希羅娜」的騎士，確有此事？",
  ui_story_5053_50531601_104_dialog_content = "對！城主大人您的消息真靈通啊！既然如此，您能幫我引薦一下嗎？",
  ui_story_5053_50531601_105_dialog_content = "抱歉，加晴，希羅娜早已離開白夜城，我恐怕無法實現妳的願望了。",
  ui_story_5053_50531601_106_dialog_content = "哎？可是，她不是說要成為最厲害的騎士嗎……",
  ui_story_5053_50531601_107_dialog_content = "你可以去啟光找她，但是切勿向她提起白夜城的事情。",
  ui_story_5053_50531601_108_dialog_content = "別忘了「永憶鏡晶」內發生的一切並非真實，哪怕你與她結下再深的緣分……",
  ui_story_5053_50531601_109_dialog_content = "那也只是大夢一場而已。十二年已過，現在早已物是人非。",
  ui_story_5053_50531601_110_dialog_content = "這樣啊……但是沒關係！只要我們的初心不變，就一定還能成為朋友的！",
  ui_story_5053_50531601_111_dialog_content = "「初心不變」嗎……妳說得有道理。",
  ui_story_5053_50531601_112_dialog_content = "「我本來以為夫人失去記憶這件事，會令她的家人再次陷入悲痛。」",
  ui_story_5053_50531601_113_dialog_content = "「沒想到，大家沒有因此垂頭喪氣。在短暫的失落過後，便沉浸在團聚的喜悅中。」",
  ui_story_5053_50531601_114_dialog_content = "「只要家人平安健康就好……這一家人之間的情感真是純粹而美好。」",
  ui_story_5053_50531601_115_dialog_content = "「但是<color=#FFB400>城主之家</color>這個過於耀眼的身分，卻令他們無法享受這種單純的幸福。」",
  ui_story_5053_50531601_116_dialog_content = "<color=#e8d9bb>麥格努斯爵士宅邸——凱萊布家</color>",
  ui_story_5053_50531601_117_dialog_content = "姐姐，我回來了！妳看，這是影鎮新出的水果紅茶，我覺得妳一定會喜歡！",
  ui_story_5053_50531601_118_dialog_content = "舅父，歡迎回來。",
  ui_story_5053_50531601_119_dialog_content = "歡迎回來……呃，今天是工作日對吧？凱萊布你不去上班嗎？",
  ui_story_5053_50531601_120_dialog_content = "工作哪有姐姐妳重要。我已經向黎明學院遞了辭呈，今後我會一直陪在妳身邊的。",
  ui_story_5053_50531601_121_dialog_content = "天啊，辭呈？難道只是因為我的出現，你就要放棄自己的事業和理想嗎？",
  ui_story_5053_50531601_122_dialog_content = "姐姐妳不要這麼說嘛！哪有什麼事比一家人幸福快樂地生活在一起更重要！",
  ui_story_5053_50531601_123_dialog_content = "蜜雅也一直想要回到白夜城和家人團聚，妳說對不對？",
  ui_story_5053_50531601_124_dialog_content = "那個，其實……我今天就是來和媽媽說這件事的。我今後想在影鎮繼續生活。",
  ui_story_5053_50531601_125_dialog_content = "什……蜜雅妳怎麼會突然這麼說？難道舒瓦茲又欺負妳了？！",
  ui_story_5053_50531601_126_dialog_content = "沒有！這是我自己的想法，父親也支持我的決定。",
  ui_story_5053_50531601_127_dialog_content = "過去我弱小而無力，被迫離開媽媽，吃盡了苦頭……",
  ui_story_5053_50531601_128_dialog_content = "但也因此能面對困難，看到白夜城之外的世界，也成長為如今的自己。可是這還遠遠不夠。",
  ui_story_5053_50531601_129_dialog_content = "舅父您也知道，最近因為您經常請假，而我戴著面紗頻繁出入住宅，有些流言已經在高庭傳開。",
  ui_story_5053_50531601_130_dialog_content = "父親甚至因此無法來家中與母親見面……明明我們已經把媽媽藏起來了。",
  ui_story_5053_50531601_131_dialog_content = "我知道！這方面我也在努力想辦法，大不了我們就搬出白夜城生活！！",
  ui_story_5053_50531601_132_dialog_content = "城主夫人時隔多年復活了又怎麼樣……",
  ui_story_5053_50531601_133_dialog_content = "想扳倒舒瓦茲，就拿出實力來！老是搞政治緋聞，這種下三濫的手段有什麼意思？！",
  ui_story_5053_50531601_134_dialog_content = "嗯，我懂，這一切不是我們一家人的錯。但也是我們一家所必須承受之惡。",
  ui_story_5053_50531601_135_dialog_content = "現在我終於開始理解父親了……所以我不會再貪戀媽媽的懷抱了。",
  ui_story_5053_50531601_136_dialog_content = "既然沒有能力生活在白夜城的光芒之下，那就讓我成為大家的「影子」吧。",
  ui_story_5053_50531601_137_dialog_content = "我會在影鎮努力和伊斯塔萬老爹學習，從一個受人保護的弱者變成強大的騎士。",
  ui_story_5053_50531601_138_dialog_content = "今後就由我來守護大家……！",
  ui_story_5053_50531601_139_dialog_content = "妳為什麼會這麼想？難道舅父我不值得妳信賴和依靠嗎？姐姐，妳也勸勸她嘛。",
  ui_story_5053_50531601_140_dialog_content = "凱萊布，我是一個<color=#FFB400>沒有記憶的人</color>。我沒有過去，所以也不會貪戀過去。",
  ui_story_5053_50531601_141_dialog_content = "我很高興蜜雅妳能找到自己的夢想。寶貝，好好努力吧，我相信妳一定能獲得精彩的未來。",
  ui_story_5053_50531601_142_dialog_content = "媽媽……謝謝妳。",
  ui_story_5053_50531601_143_dialog_content = "說來，蜜雅妳也提醒了我呀。外頭有這麼多精彩的世界，乾脆我也去看看好了。",
  ui_story_5053_50531601_144_dialog_content = "等等，姐姐妳這是什麼意思……？",
  ui_story_5053_50531601_145_dialog_content = "「是的，在經歷這些事後，蜜雅最終還是選擇了離開。」",
  ui_story_5053_50531601_146_dialog_content = "「這是她成長後主動做出的決定，我由衷為她感到高興。」",
  ui_story_5053_50531601_147_dialog_content = "「同時，凱萊布的離職申請也遭到了駁回。」",
  ui_story_5053_50531601_148_dialog_content = "「顯然他本來就會動不動因各種小事衝動辭職，學院早就見怪不怪，照常按駁回處理了。」",
  ui_story_5053_50531601_149_dialog_content = "「另一方面，約書亞夫人似乎也因此受到啟發，有了自己的想法。」",
  ui_story_5053_50531601_150_dialog_content = "「她決定背著大家偷偷離開白夜城，獨自踏上旅途。」",
  ui_story_5053_50531601_151_dialog_content = "辛苦你了，PlayerName。謝謝你用巨像偷偷送我出來。",
  ui_story_5053_50531601_152_dialog_content = "舉手之勞而已。但是，夫人您為什麼要和大家不告而別呢？",
  ui_story_5053_50531601_153_dialog_content = "傻孩子，如果大家知道我要離開，肯定不會輕易同意的。",
  ui_story_5053_50531601_154_dialog_content = "但我必須離開，這既是為了保護他們，也是我身為母親和姐姐要給他們的最後一課。",
  ui_story_5053_50531601_155_dialog_content = "……約書亞夫人，您真的失憶了嗎？",
  ui_story_5053_50531601_156_dialog_content = "呵呵，那是當然的啦。你可不要偷偷用空裔的能力偷窺淑女的祕密喔？",
  ui_story_5053_50531601_157_dialog_content = "好、好的。那麼回去之後我會把您離開的消息告訴大家……我這樣做應該不算欺君之罪吧？",
  ui_story_5053_50531601_158_dialog_content = "呵呵，好像算呢。",
  ui_story_5053_50531601_159_dialog_content = "哎？ ！",
  ui_story_5053_50531601_160_dialog_content = "逗你的～狄安理應該早就猜到我的想法了，我們倆之間有著不言而喻的默契。",
  ui_story_5053_50531601_161_dialog_content = "而卡蓮……她和狄安理太像了。聽說你和她關係很好，你應該也明白吧？",
  ui_story_5053_50531601_162_dialog_content = "看似堅強能幹，其實總是在硬撐。所以大家都不約而同對她保持沉默。",
  ui_story_5053_50531601_163_dialog_content = "以卡蓮的能力，她想知道的真相一定能親自找到。如果沒找到……",
  ui_story_5053_50531601_164_dialog_content = "那麼一定是她還沒準備好接受真相。",
  ui_story_5053_50531601_165_dialog_content = "……哈哈哈，雖然說了這些高高在上的話，但其實我自己心中也藏著一個不得了的陰霾呢。",
  ui_story_5053_50531601_166_dialog_content = "要不是被植入了「種子」，恐怕我這輩子也意識不到，其實自己也在暗自壓抑著暴戾的一面吧。",
  ui_story_5053_50531601_167_dialog_content = "約書亞夫人……",
  ui_story_5053_50531601_168_dialog_content = "除了溫暖地包容對方，有時也需要嚴格督促對方，這也是家人間關心的一種方式，對嗎？",
  ui_story_5053_50531601_169_dialog_content = "沒錯，溫暖的港灣有時也會成為成長的絆腳石。",
  ui_story_5053_50531601_170_dialog_content = "比起我們，現在的卡蓮更需要可靠的戰友，以及與她志同道合的朋友。",
  ui_story_5053_50531601_171_dialog_content = "所以，PlayerName，可以拜託你繼續陪卡蓮一起成長嗎？",
  ui_story_5053_50531601_X171_option_content = "沒問題！",
  ui_story_5053_50531601_X172_option_content = "哎，拜託我嗎……？",
  ui_story_5053_50531601_X173_dialog_content = "最後的空之末裔，與我們光靈截然不同的種族，我從你身上能看到未來的光芒。",
  ui_story_5053_50531601_X174_dialog_content = "這是在白夜城這個封閉環境中，永遠無法窺見的珍寶。",
  ui_story_5053_50531601_X175_dialog_content = "我相信你一定可以引導卡蓮，不，引導更多人走向不一樣的明天。",
  ui_story_5053_50531601_X176_dialog_content = "你的存在，以及蜜雅的勇氣，讓我看到了外面世界潛藏著無窮可能。",
  ui_story_5053_50531601_X177_dialog_content = "說不定在見識了更廣闊的天地後，我也會找到自己真正想要的東西。",
  ui_story_5053_50531601_X178_dialog_content = "有朝一日，再帶著那份寶貴的感悟，回到我心愛之人身邊……",
  ui_story_5053_50531601_X179_dialog_content = "「於是，那日我悄悄與您分別，並將您離去的消息帶回白夜城。」",
  ui_story_5053_50531601_X180_dialog_content = "「有的人微微一笑，坦然送上祝福；有的人在驚訝後，欣然接受。」",
  ui_story_5053_50531601_X181_dialog_content = "「有的人無法理解，奪門而去；而有的人，似乎早已料到了這個結局。」",
  ui_story_5053_50531601_X182_dialog_content = "「經過一番波折後，大家姑且接受了這個結局，不再阻撓失憶者開啟新的人生。」",
  ui_story_5053_50531601_X183_dialog_content = "「至於您偷偷與我保持著書信聯繫這件事，我一定會向其他人保密。」",
  ui_story_5053_50531601_X184_dialog_content = "「我也會遵守約定，偶爾向您更新您家人們的近況。」",
  ui_story_5053_50531601_172_dialog_content = "「希望下次見面，我們能以旅行者的身分彼此分享一路上的有趣見聞。」",
  ui_story_5053_50531601_173_dialog_content = "PlayerName——！！別寫啦！",
  ui_story_5053_50531601_174_dialog_content = "啊？！哎，加晴妳怎麼又嚇我！",
  ui_story_5053_50531601_175_dialog_content = "這次可不能怪我！誰叫你只顧著悶頭寫信，不是說好要跟蜜雅一起送我回北境嗎？",
  ui_story_5053_50531601_176_dialog_content = "稍、稍等一下，我約了信使幫忙送信，人家馬上就要過來了。",
  ui_story_5053_50531601_177_dialog_content = "我真沒想到加晴會準時到……",
  ui_story_5053_50531601_178_dialog_content = "喂！我都聽見了喔！",
  ui_story_5053_50531601_179_dialog_content = "嘿嘿，既然如此，我們就等一會兒吧。",
  ui_story_5053_50531601_180_dialog_content = "對了，PlayerName，你收到明信片了嗎？",
  ui_story_5053_50531601_181_dialog_content = "明信片？",
  ui_story_5053_50531601_182_dialog_content = "啊，約書亞夫人寄來的明信片！我收到了喔！",
  ui_story_5053_50531601_183_dialog_content = "上面寫說她來到一個偏僻的小城鎮，還遇到了會說話的小鳥！",
  ui_story_5053_50531601_184_dialog_content = "嗯……那可能是某種亞人吧。媽媽說她們很合得來，成了無話不說的朋友，真好呀。",
  ui_story_5053_50531601_185_dialog_content = "哎？難道只有我沒收到嗎……",
  ui_story_5053_50531601_186_dialog_content = "看來PlayerName的待遇還是比我們差一點喔？",
  ui_story_5053_50531601_187_dialog_content = "只、只是送信延誤罷了！早晚會寄到我手上的！",
  ui_story_5053_50531601_188_dialog_content = "開門開門！信使阿褐來上門服務啦！",
  ui_story_5053_50531601_189_dialog_content = "哇，真是說到就到。",
  ui_story_5053_50531601_190_dialog_content = "來了來了！信在這裡，麻煩妳了。",
  ui_story_5053_50531601_191_dialog_content = "嗯，阿褐收到了。然後這封是給你的。",
  ui_story_5053_50531601_192_dialog_content = "給我的？啊……這是！",
  ui_story_5053_50531601_193_dialog_content = "有什麼好玩的東西嗎？",
  ui_story_5053_50531601_194_dialog_content = "怎麼了嗎，PlayerName？",
  ui_story_5053_50531601_195_dialog_content = "PlayerName，我們可以一起看看嗎？",
  ui_story_5053_50531601_196_dialog_content = "啊啊啊抱歉這個不能給妳們看啊！",
  ui_story_5053_50531601_197_dialog_content = "「親愛的PlayerName，別來無恙。」",
  ui_story_5053_50531601_198_dialog_content = "「我現在正在旅途路上……」",
  ui_story_5053_50531601_199_dialog_content = "摘一束玫瑰，送給我的寶貝～♪",
  ui_story_5053_50531601_200_dialog_content = "暖風吹拂面龐，妳的笑顏就是唯一的珍寶～♪",
  ui_story_5053_50531601_201_dialog_content = "摘一束玫瑰，送給親愛的爸爸媽媽～♪",
  ui_story_5053_50531601_202_dialog_content = "任由世事變化，我們永遠是彼此的最愛～♪"
